Ceviri.ekle("bn","olay",{
"OLAYLAR_EK5:1770-08-01:0":{"b": ["কার্তাল (কাগুল) সমভূমির পরাজয়", "6f408eaf"], "d": ["চেশমেতে নৌবহর পোড়ানোর তিন সপ্তাহ পর দানিয়ুব তীরের প্রধান অটোমান সেনাবাহিনী কার্তাল সমভূমিতে মার্শাল রুমিয়ান্তসেভের সংখ্যায় অনেক ছোট কিন্তু শৃঙ্খলাবদ্ধ বাহিনীর সামনে ছত্রভঙ্গ হলো। শিবির, রসদ বহর ও শত শত কামান শত্রুর হাতে গেল; পালানো বাহিনী দানিয়ুব পার হওয়ার সময় বড় ক্ষতি সইল। একই গ্রীষ্মে নৌবহর ও স্থলসেনা দুটির ধ্বংস কিলিয়া, আক্কিরমান, ইসমাইল ও বেন্দেরের একের পর এক পতন এবং ক্রিমিয়া দখলের কারণ হলো।", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["ক্রিমিয়া উপদ্বীপের রুশ দখল", "217837b0"], "d": ["এক বছর আগে বুজাক দখল করা রুশ সেনাবাহিনী প্রিন্স দোলগোরুকভের নেতৃত্বে ওর কাপি পার হয়ে ক্রিমিয়া উপদ্বীপের সবটা আক্রমণ করল। খান সিংহাসনচ্যুত হলেন, রুশপন্থী সাহিব গিরাইকে ক্ষমতায় বসিয়ে খানাতকে অটোমানদের কাছ থেকে বিচ্ছিন্ন করার প্রথম পদক্ষেপ নেওয়া হলো। তিন শতাব্দী অটোমানদের উত্তর ঢাল ক্রিমিয়ার হাতছাড়া হওয়া 1774 সালে স্বাধীনতা এবং 1783 সালে সরাসরি সংযুক্তি প্রক্রিয়ার সূচনা ছিল।", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["তৃতীয় মুস্তাফার মৃত্যু এবং প্রথম আবদুলহামিদের সিংহাসনারোহণ", "42cba8e2"], "d": ["রুশ যুদ্ধের সবচেয়ে সংকটময় মুহূর্তে মারা যাওয়া তৃতীয় মুস্তাফার জায়গায় তেতাল্লিশ বছর প্রাসাদের কাফেসে কাটানো ভাই প্রথম আবদুলহামিদ উনপঞ্চাশ বছর বয়সে সিংহাসনে বসলেন। রাষ্ট্রের সবচেয়ে কঠিন সময়ের একটি উত্তরাধিকার পাওয়া নতুন সুলতান একই বছর স্বাক্ষরিত কুচুক কায়নারজা চুক্তির ভারী শর্তের মুখোমুখি হতে বাধ্য হলেন। পনেরো বছরের রাজত্ব ক্রিমিয়া হারানো ও নতুন রুশ যুদ্ধে কাটবে এবং 1789 সালে ওজির পতনের খবর পড়ার সময় আসা পক্ষাঘাতে শেষ হবে।", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["কোজলুজা পরাজয় — কুচুক কায়নারজার পথে পরাজয়", "8e0542f9"], "d": ["শুমনুর সামনে সমবেত অটোমান বাহিনী সুভোরভ ও কামেনস্কির মিলিত শাখার কাছে কোজলুজায় পরাজিত হলো এবং সেনাবাহিনীর বড় অংশ ছত্রভঙ্গ হলো। এই পরাজয়ে বলকানে প্রতিরোধ করার মতো বাহিনী রইল না; রুশ অগ্রবর্তী দল শুমনু অবরোধ করল এবং সদরে আজমের সদর দপ্তর হুমকির মুখে পড়ল। এক মাস না পেরোতেই কুচুক কায়নারজায় টেবিলে বসা এবং অসাধারণ ভারী শর্ত মেনে নেওয়া সরাসরি এই পরাজয়ের ফল।", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["বুকোভিনার (উত্তর মলদোভা) অস্ট্রিয়াকে ছেড়ে দেওয়া", "190f9caa"], "d": ["কুচুক কায়নারজার সৃষ্ট দুর্বলতার সুযোগ নেওয়া অস্ট্রিয়া মলদোভা ও ট্রান্সিলভানিয়ার মধ্যে যোগসূত্র স্থাপনকারী বুকোভিনা অঞ্চল দাবি করল এবং যুদ্ধে না গিয়ে হুমকি ও ঘুষের মাধ্যমে এই ভূমি পেল। খোতিনের দক্ষিণ-পশ্চিমের এই উর্বর ও কৌশলগত অঞ্চলের হারানো মলদোভা ভয়েভোদাত্বকে কার্যত দুই ভাগ করল। একটি গুলিও না ছুড়ে ঘটা এই ত্যাগ অটোমান রাষ্ট্র আর প্রতিরোধ ক্ষমতা ধরে রাখতে পারছে না তার সবচেয়ে স্পষ্ট ইঙ্গিতগুলোর একটি গণ্য হলো। 1775 সালে বুকোভিনা ত্যাগের সঙ্গে সুচেভা ও চেরনোভিৎস অস্ট্রিয়ার হাতে গেল (দিন অনিশ্চিত)।", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["বসরার ইরানি দখলে পড়া", "0161e709"], "d": ["জান্দ শাসক করিম খানের ভাই সাদিক খান এক বছর স্থায়ী অবরোধের পর বসরা দখল করলেন এবং অটোমান রাষ্ট্র বসরা উপসাগরের সবচেয়ে গুরুত্বপূর্ণ বন্দর হারাল। দখল ভারতীয় বাণিজ্যপথ, খেজুর ও মুক্তার আয় এবং ইরাকের দক্ষিণ প্রতিরক্ষাকে সরাসরি নাড়িয়ে দিল। শহর কেবল 1779 সালে করিম খানের মৃত্যুতে ইরানে শুরু হওয়া সিংহাসন-দ্বন্দ্বের সময় ফিরিয়ে নেওয়া গেল।", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["আইনালিকাভাক তেনকিহনামে — ক্রিমিয়া নিয়ে সাময়িক সমঝোতা", "9b3b0468"], "d": ["ক্রিমিয়া খানাতের প্রধান কে হবেন তা নিয়ে যুদ্ধের দ্বারপ্রান্তে আসা দুই রাষ্ট্র ফ্রান্সের মধ্যস্থতায় আইনালিকাভাক প্রাসাদে একটি ব্যাখ্যা-পাঠ স্বাক্ষর করল। রাশিয়া ক্রিমিয়া থেকে সৈন্য সরাতে, অটোমান রাষ্ট্র রুশপন্থী শাহিন গিরাইয়ের খানত্ব মেনে নিতে সম্মত হলো; সুলতানের ক্রিমিয়ার ওপর ধর্মীয় খিলাফত অধিকার নিশ্চিত হলো। চার বছর স্থায়ী এই ভঙ্গুর ভারসাম্য 1783 সালে রাশিয়ার উপদ্বীপ সরাসরি সংযুক্তিতে সম্পূর্ণ ভেঙে পড়বে।", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["আনাপা দুর্গ নির্মাণ — ককেশীয় প্রতিরক্ষা রেখা", "be92a80f"], "d": ["কুচুক কাইনারজা চুক্তি ও ক্রিমিয়া হাতছাড়া হওয়ার পর ককেশাসে অটোমান প্রভাব রক্ষায় কুবান নদীর মোহনায় নতুন দুর্গ নির্মাণ শুরু হয়। জেনোয়ীয় উপনিবেশের ধ্বংসাবশেষের ওপর গড়া আনাপা বাজার, হাম্মাম ও আড়াইশোর বেশি দোকান নিয়ে অল্প সময়েই সার্কাসীয় গোত্রগুলোর সঙ্গে যোগাযোগ রক্ষাকারী শহরে পরিণত হয়। রাশিয়ার ককেশাসে নেমে আসার বিরুদ্ধে দুর্গটি আটচল্লিশ বছর ধরে অটোমানদের সবচেয়ে অগ্রবর্তী ঘাঁটি ছিল।", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["প্রধান উজির হালিল হামিদ পাশার অপসারণ ও মৃত্যুদণ্ড", "c44001ca"], "d": ["প্রথম আবদুলহামিদ বিভিন্ন উপলক্ষে যাঁর সেবায় সন্তোষ প্রকাশ করেছিলেন, সেই সংস্কারপন্থী প্রধান উজির হালিল হামিদ পাশা 31 মার্চ 1785 সকালের দিকে হঠাৎ অপসারিত হয়ে গেলিবোলুতে নির্বাসিত হন এবং তাঁর সব সম্পদ বাজেয়াপ্ত হয়। প্রথমে তাঁকে হাবেশ প্রদেশ, জেদ্দা সানজাক ও মক্কার শায়খুল-হারামের পদ দেওয়া হয়; এপ্রিল 1785 যাত্রার প্রস্তুতিতে বজকাদায় কাটানোর সময় এই গভর্নরত্ব থেকেও অপসারিত হন এবং জারি হওয়া মৃত্যুদণ্ডের ফরমানে আলজেরীয় গাজি হাসান পাশার লোকদের একজন কারাকেথুদাজাদে আলির হাতে নিহত হন। কর্তিত মাথা ইস্তানবুলে পাঠিয়ে অর্তাকাপিতে প্রদর্শন করা হয়। টিডিভি অনুসারে এই আকস্মিক পতন সুলতানকে সিংহাসনচ্যুত করে শাহজাদা সেলিমকে বসানোর ষড়যন্ত্রের অভিযোগে ব্যাখ্যা করা হলেও প্রকৃত কারণ সম্ভবত ক্রিমিয়ার সংযুক্তিতে নীরব থাকায় সৃষ্ট ক্ষোভ, তাঁর সংস্কারে ক্ষতিগ্রস্ত মহলের শত্রুতা এবং গাজি হাসান পাশার বিরোধিতা।", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["রাশিয়ার বিরুদ্ধে যুদ্ধ ঘোষণা — 1787-1792 অটোমান-রুশ যুদ্ধ শুরু", "3bfb870c"], "d": ["দ্বিতীয় ক্যাথরিনের জাঁকজমকপূর্ণ ক্রিমিয়া সফর এবং জর্জিয়াকে আশ্রয়ে নেওয়ায় দিওয়ান সংযুক্তি ফিরিয়ে আনার উদ্দেশ্যে যুদ্ধের সিদ্ধান্ত নিল এবং রুশ দূতকে আবার ইয়েদিকুলে বন্দি করা হলো। কিন্তু সেনাবাহিনী প্রস্তুত ছিল না, কোষাগার খালি ছিল এবং মিত্র খোঁজা নিষ্ফল হয়েছিল। পাঁচ বছর স্থায়ী যুদ্ধ ওজির গণহত্যাসহ পতন, ইসমাইল হারানো এবং ইয়াশ চুক্তির ভারী শর্তে পরিণতি পাবে।", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["অস্ট্রিয়ার যুদ্ধে প্রবেশ — দুই ফ্রন্টের সংগ্রাম", "ae912290"], "d": ["রাশিয়ার সঙ্গে 1781 সালে করা গোপন মৈত্রী অনুযায়ী অস্ট্রিয়ার সম্রাট দ্বিতীয় যোসেফ অটোমান রাষ্ট্রের বিরুদ্ধে যুদ্ধ ঘোষণা করে বেলগ্রেড ও বসনিয়ার দিকে অগ্রসর হলেন। অটোমান সেনাবাহিনী হঠাৎ উত্তরে রাশিয়া, পশ্চিমে অস্ট্রিয়া — দুই ফ্রন্টে একসঙ্গে লড়তে বাধ্য হলো। লাজারেতহানে, মেহাদিয়া ও শেবেশে অস্ট্রিয়ানদের বিরুদ্ধে অর্জিত বিজয় সত্ত্বেও 1789 সালে বেলগ্রেড হারানোয় পশ্চিম ফ্রন্টও ভেঙে পড়বে।", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["অটোমান-প্রুশিয়া মৈত্রী", "03b88e51"], "d": ["সিংহাসনে বসেই ইউরোপে মিত্র খোঁজা তৃতীয় সেলিম প্রুশিয়ার সঙ্গে পারস্পরিক সাহায্য নির্ধারণকারী মৈত্রী চুক্তি স্বাক্ষর করলেন; প্রুশিয়া রাশিয়া ও অস্ট্রিয়ার বিরুদ্ধে যুদ্ধ ঘোষণার, অটোমান রাষ্ট্রও ক্রিমিয়া ফিরে না পাওয়া পর্যন্ত শান্তি না করার অঙ্গীকার করল। এটি অটোমান ইতিহাসে কোনো ইউরোপীয় রাষ্ট্রের সঙ্গে স্বাক্ষরিত প্রথম প্রকৃত পারস্পরিক মৈত্রী পাঠ এবং ক্লাসিক 'কাফেরদের সঙ্গে মৈত্রী হয় না' ধারণা ত্যাগের ইঙ্গিত দিল। প্রুশিয়া যুদ্ধে প্রবেশ না করলেও অস্ট্রিয়াকে শান্তিতে বাধ্য করে জিশতোভি চুক্তির পথ খুলল।", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["ইসমাইল দুর্গের পতন ও গণহত্যা", "6a296b0c"], "d": ["দানিয়ুব ব-দ্বীপের সবচেয়ে শক্তিশালী দুর্গ গণ্য ইসমাইল দুর্গ জেনারেল সুভোরভের সংগঠিত রক্তাক্ত সাধারণ আক্রমণে একদিনে হস্তগত হলো; গ্যারিসন ও শহরের জনগণ বহুলাংশে তরবারির আঘাতে নিহত হলো। ইউরোপে বিস্তৃত সাড়া জাগানো এই গণহত্যা অটোমান জনমতে গভীর আঘাত দিল এবং দানিয়ুব প্রতিরক্ষা রেখার মেরুদণ্ড ভাঙল। দুর্গ এক বছর পর ইয়াশ চুক্তিতে ফেরত আসবে, তবে তত দিনে যুদ্ধের ভাগ্য নির্ধারিত হয়ে গেছে।", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["জিশতোভি চুক্তি — অস্ট্রিয়া ফ্রন্টের সমাপ্তি", "58741f1d"], "d": ["প্রুশিয়ার চাপ এবং ফরাসি বিপ্লবের অস্ট্রিয়াকে পশ্চিমে ব্যস্ত রাখার সুবাদে দুই রাষ্ট্র যুদ্ধপূর্ব সীমান্তকে ভিত্তি করে শান্তিতে পৌঁছাল। অস্ট্রিয়া দখলকৃত বেলগ্রেডসহ সব স্থান ফিরিয়ে দিল; অটোমান রাষ্ট্র কেবল ক্রোয়েশিয়া সীমান্তে ছোট সংশোধন মেনে নিল। পশ্চিম ফ্রন্ট এই শর্তে বন্ধ হওয়া অটোমান রাষ্ট্রকে সমস্ত শক্তি রাশিয়ার বিরুদ্ধে সংগ্রহ করতে সক্ষম করল এবং ইয়াশ চুক্তিতে ক্ষতি সীমিত করল। ক্রোয়েশিয়া সীমান্তের এই সংশোধনে চেতিন (চেতিনগ্রাদ) ও দ্রেজনিক গ্রাদ অটোমানদের কাছ থেকে হাবসবুর্গের হাতে যায় (TDV zistovi-antlasmasi; Korić 2016, n. 118, ধারা 4)। ওরসোভা (পুরোনো ওরসোভা) অবশ্য ফেরত না দেওয়া একমাত্র স্থান (Bánlaky 0019/1796); অ্যাটলাস আইনত হস্তান্তর এই দিনে লিখেছে (প্রকৃত দখল 16 এপ্রিল 1790)।", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["ইয়াশ চুক্তি — ক্রিমিয়ার চূড়ান্ত হারানো এবং দনিস্টার সীমান্ত", "a56fd194"], "d": ["পাঁচ বছরের যুদ্ধের শেষে স্বাক্ষরিত চুক্তিতে তুর্লা (দনিস্টার) নদীকে সীমান্ত মানা হলো; নদীর বাম তীর রাশিয়ার, ডান তীর অটোমানদের হাতে থাকল এবং ওজি ও তার আশপাশ চূড়ান্তভাবে হাতছাড়া হলো। অটোমান রাষ্ট্র ক্রিমিয়া ফিরিয়ে নেওয়ার আশা সম্পূর্ণ ত্যাগ করল এবং 1783 সালের সংযুক্তি আইনত স্বীকার করল; ওয়ালাচিয়া ও মলদোভা দুই বছরের কর অব্যাহতিসহ ফেরত দেওয়া হলো। বারো মিলিয়ন কুরুশের যুদ্ধক্ষতিপূরণের দায়ও মেনে নিয়ে কৃষ্ণ সাগরের উত্তর স্থায়ীভাবে রাশিয়ার হাতে ছাড়া হলো। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: ইসমাইল।", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["ওরানের (ভেহরান) স্পেনীয়দের দ্বারা খালি করা ও আলজিয়ার্সকে হস্তান্তর", "9f95cee6"], "d": ["1790 সালের ভূমিকম্পে দুর্গ ও শহর অনেকাংশে ধ্বংস হলে তিন শতাব্দী ধরে ব্যয়বহুল গ্যারিসন বহন করতে অক্ষম স্পেন আলজিয়ার্স ওজাকের সঙ্গে সমঝোতা করে ওরান ও মার্সা এল-কেবির যুদ্ধ ছাড়াই হস্তান্তর করে। এভাবে উত্তর আফ্রিকার উপকূলের শেষ ইউরোপীয় ঘাঁটিও বিলুপ্ত হয়। অটোমান আলজেরিয়া ফরাসি দখল পর্যন্ত আটত্রিশ বছর পুরো উপকূলে কর্তৃত্ব ধরে রাখে।", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["পাজভানদওগলু ওসমানের ভিদিনে প্রকৃত শাসন", "0ce70361"], "d": ["নিজাম-ই জেদিদ ব্যবস্থার বিরুদ্ধে বিদ্রোহ করা পাজভানদওগলু ওসমান ভিদিনের গভর্নরকে পালাতে বাধ্য করে শহর দখল করলেন এবং দানিয়ুব বরাবর গভীর পরিখা দিয়ে সুরক্ষিত করলেন। 1797 সালে শক্তির শীর্ষে আশি হাজারের কাছাকাছি বাহিনী সংগ্রহ করে নিকোপোল, জিশতোভি, রুসচুক, সোফিয়া ও নিশ নিয়ন্ত্রণে নিলেন; নিজেকে বিদ্রোহী নয়, সংস্কারক হিসেবে উপস্থাপন করলেন। বাবে-আলির 1798-1799 সালে মাসের পর মাস চলা অবরোধ ব্যর্থ হলো এবং তিনি 1807 সালে মৃত্যু পর্যন্ত উত্তর বুলগেরিয়ায় আধা-স্বাধীনভাবে শাসন করলেন।", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["মুহান্দিসহানে-ই বার্রি-ই হুমায়ুনের উদ্বোধন", "e9a3a34b"], "d": ["নিজাম-ই জেদিদ বাহিনীর জন্য কামান, দুর্গ প্রকৌশল ও মানচিত্রকার অফিসার তৈরির উদ্দেশ্যে হাসকোয়ে স্থলবাহিনীর প্রকৌশল বিদ্যালয় খোলা হলো; 1773 সালে প্রতিষ্ঠিত নৌ প্রকৌশল বিদ্যালয়ের স্থলবাহিনীর প্রতিরূপ ছিল এটি। পাঠ্যসূচিতে বীজগণিত, জ্যামিতি, বলবিদ্যা, দুর্গবিদ্যা ও গোলন্দাজ বিদ্যা পড়ানো হলো, ইউরোপীয় ভাষা থেকে গণিত ও কামানবিদ্যার বই অনূদিত হলো। তুরস্কে আধুনিক প্রকৌশল শিক্ষার মূল গণ্য এই বিদ্যালয় আজকের ইস্তানবুল টেকনিক্যাল ইউনিভার্সিটির সূচনা বলে মানা হয়।", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["ফ্রান্সের বিরুদ্ধে যুদ্ধ ঘোষণা এবং রাশিয়া-ব্রিটেনের সঙ্গে মৈত্রী", "80e95bd7"], "d": ["নেপোলিয়নের মিসর দখলে অটোমান রাষ্ট্র আড়াই শতাব্দীর ঐতিহ্যবাহী ফরাসি বন্ধুত্ব ভেঙে ফ্রান্সের বিরুদ্ধে যুদ্ধ ঘোষণা করল। একই প্রক্রিয়ায় ইতিহাসে প্রথমবার রাশিয়ার সঙ্গে মৈত্রী করল এবং রুশ নৌবহরকে প্রণালী পার হয়ে ভূমধ্যসাগরে যাওয়ার অনুমতি দিল; এর পর ব্রিটেনের সঙ্গেও মৈত্রী স্বাক্ষরিত হলো। এই মৈত্রীর ফলে আয়োনীয় দ্বীপপুঞ্জ ফরাসিদের কাছ থেকে নেওয়া হলো, তবে প্রণালী বিদেশি নৌবহরের জন্য খুলে দেওয়া ভবিষ্যতে ভারী মূল্যের নজির গড়ল।", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["প্রেভেজা ফরাসিদের কাছ থেকে দখল — নিকোপোলিসের যুদ্ধ", "d8e5e892"], "d": ["1797 সালে ভেনিস প্রজাতন্ত্র ভেঙে পড়লে আইওনীয় দ্বীপপুঞ্জ এবং মূল ভূখণ্ডের প্রেভেজা, পার্গা, ভোনিৎসা ফ্রান্সের হাতে যায়। ইয়ানিনার শাসক তেপেদেলেনলি আলি পাশা ফ্রান্সের মিসর আক্রমণের ফলে শুরু হওয়া যুদ্ধের সুযোগে প্রেভেজার দিকে অগ্রসর হন এবং শহরের বাইরে নিকোপোলিসের ধ্বংসাবশেষে ফরাসি গ্যারিসনকে ভারী পরাজয়ে ফেলেন। এভাবে পাসারোভিৎসে ভেনিসের হাতে রাখা এই বন্দর আশি বছর পর অটোমান শাসনে আসে। বুত্রিন্ট (Butrinto) ফরাসি গ্যারিসন দুর্গ উড়িয়ে দিয়ে কর্ফুতে সরে গেলে 25 অক্টোবর পতিত হয় (Curlin, Preveza B, 2010; অ্যাটলাসের দিন প্রেভেজা থেকে নেওয়া) এবং অটোমান শাসনে আসে।", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["আক্কা প্রতিরক্ষা — নেপোলিয়নের প্রতিহত হওয়া", "56b5c45b"], "d": ["মিসর থেকে সিরিয়ায় অগ্রসর নেপোলিয়ন আক্কা অবরোধ করলেন এবং দুই মাস ধরে পরপর আক্রমণ চালালেন; শহর জাজ্জার আহমেদ পাশা ব্রিটিশ নৌবহরের সমর্থন এবং ইস্তানবুল থেকে পাঠানো নিজাম-ই জেদিদ বাহিনী দিয়ে রক্ষা করলেন। অবরোধ তুলে মিসরে সরে যেতে বাধ্য হওয়া নেপোলিয়ন পূর্বে প্রসারিত হওয়ার স্বপ্ন এই প্রাচীরের সামনে কবর দিলেন। খবর ইস্তানবুলে বড় আনন্দে গৃহীত হলো এবং নবগঠিত প্রশিক্ষিত সেনাবাহিনী প্রথম গুরুতর পরীক্ষা উত্তীর্ণ হওয়ার প্রমাণ গণ্য হলো।", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["ওয়াহহাবিদের কারবালা হামলা", "522341ed"], "d": ["নাজদ থেকে ওঠা ওয়াহহাবি বাহিনী কারবালায় প্রবেশ করে শহর লুট করল, হযরত হুসাইনের সমাধি ধ্বংস করল এবং তিন হাজারের বেশি মানুষ হত্যা করল। অটোমান রাষ্ট্রের ইরাকের কোলেমেন গভর্নররা হামলা ঠেকাতে পারলেন না; ঘটনা ইরান ও ইস্তানবুল দুই জায়গায় বড় প্রতিক্রিয়া জাগাল। এই হামলা সৌদি আন্দোলন আর মরূদ্যান আমিরাত না থেকে অটোমানদের পবিত্র শহরগুলোকে হুমকি দেওয়া আঞ্চলিক শক্তিতে পরিণত হওয়ার ঘোষণা ছিল।", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["কার্তলি-কাখেতি (পূর্ব জর্জিয়া) রাশিয়ায় সংযুক্ত", "3b650c5e"], "d": ["1783 সালে রুশ আশ্রয় গ্রহণ করা এবং 1795 সালে ইরানের ধ্বংসাত্মক অভিযানে ক্ষতিগ্রস্ত কার্তলি-কাখেতি রাজ্য বিলুপ্ত হয়; 12 সেপ্টেম্বর 1801 তারিখের আদেশে রাশিয়ার একটি প্রদেশ ঘোষিত হয়ে রুশ প্রশাসনব্যবস্থা প্রতিষ্ঠা শুরু হয়। জর্জিয়া এই তারিখ থেকে স্বাধীনতা হারায়; কয়েক বছরের মধ্যে মেগ্রেলিয়া (1803), ইমেরেতি ও গুরিয়া (1804)ও রুশ কর্তৃত্বে আসে এবং রাশিয়া অটোমানদের ককেশীয় সীমান্তে পৌঁছায়। এই ঘটনায় গোরি, দুশেতি (কার্তলি) ও তেলাভি (কাখেতি) রাশিয়ায় যায়।", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["ফরাসিদের মিসর ত্যাগ", "00cfdc8c"], "d": ["অটোমান ও ব্রিটিশ বাহিনীর স্থল ও সমুদ্রপথে যৌথ অভিযানের ফলে প্রথমে কায়রো, পরে আলেকজান্দ্রিয়া হস্তগত হলো এবং ফরাসি বাহিনী জাহাজে করে দেশে পাঠানো হলো। তিন বছর স্থায়ী দখলের অবসানে মিসর কাগজে-কলমে অটোমান শাসনে ফিরল, কিন্তু কোলেমেন বে ও আলবেনীয় বাহিনীর মধ্যে কর্তৃত্বের সংগ্রাম দেশকে বিশৃঙ্খলায় ঠেলে দিল। এই শূন্যতা কয়েক বছরের মধ্যে কাভালার মেহমেদ আলির উত্থানের ভিত্তি প্রস্তুত করবে।", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["প্যারিস চুক্তি — ফ্রান্সের সঙ্গে শান্তি পুনঃস্থাপন", "1b76991f"], "d": ["মিসর ত্যাগের পর স্বাক্ষরিত চুক্তিতে অটোমান রাষ্ট্র ও ফ্রান্সের মধ্যে যুদ্ধাবস্থা আনুষ্ঠানিকভাবে শেষ হলো এবং পুরোনো ক্যাপিটুলেশন নবায়িত হলো। ফরাসি বাণিজ্য জাহাজকে কৃষ্ণ সাগরে প্রবেশের অনুমতি দেওয়া হলো; বিনিময়ে ফ্রান্স অটোমান ভূখণ্ডগত অখণ্ডতা স্বীকার করল। শান্তি স্থাপন তৃতীয় সেলিমের রাশিয়া ও ব্রিটেনের পাশে সংকুচিত পররাষ্ট্রনীতিতে আবার কৌশলের জায়গা এনে দিল।", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["ওয়াহহাবিদের তায়েফ দখল", "7b791359"], "d": ["সৌদ ইবনে আবদুল আজিজের নেতৃত্বাধীন ওয়াহহাবি বাহিনী হিজাজের দিকে প্রথম আঘাতে তায়েফ অবরোধ করে লুট করল; শহর পবিত্র ভূমির প্রথম দ্বার হিসেবে পড়ল। হারামাইনের রক্ষক উপাধিধারী অটোমান সুলতানের জন্য এটি রাজত্বের বৈধতাকে সরাসরি নাড়িয়ে দেওয়া আঘাত ছিল। আড়াই মাস পর একই বাহিনী মক্কার দিকে অগ্রসর হবে।", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["ওয়াহহাবিদের প্রথমবার মক্কা দখল", "21157c05"], "d": ["তায়েফের পতনের আড়াই মাস পর ওয়াহহাবি বাহিনী মক্কায় প্রবেশ করে সমাধিগুলো ধ্বংস করল এবং নিজেদের ধারণা অনুযায়ী ব্যবস্থা গড়ল; শরিফ গালিব জেদ্দায় সরে যেতে বাধ্য হলেন। হজপথ বন্ধ হওয়া সমগ্র ইসলামি বিশ্বে প্রতিধ্বনি তুলল এবং ইস্তানবুলকে মিসরের গভর্নর মেহমেদ আলির কাছে সামরিক সাহায্য চাইতে বাধ্য করল। এই প্রথম কর্তৃত্ব কেবল তিন মাস স্থায়ী হবে।", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["শরিফ গালিবের মক্কা পুনরুদ্ধার", "83d08dff"], "d": ["জেদ্দায় সরে যাওয়া শরিফ গালিব সংগৃহীত বাহিনী নিয়ে মক্কা অবরোধ করলেন এবং পঁচিশ দিনের অবরোধের পর শহর ওয়াহহাবিদের কাছ থেকে ফিরিয়ে নিলেন; অটোমানদের নামে খুতবা আবার পাঠ করা হলো। এই দ্বিতীয় কর্তৃত্বও স্থায়ী হবে না, সৌদ বাহিনী 1806 সালে শহর আবার দখল করবে।", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["প্রথম সার্বীয় বিদ্রোহের সূচনা", "0f6e8767"], "d": ["বেলগ্রেডে শাসন দখল করা বিদ্রোহী জ্যানিসারি দাহিরা সার্ব নেতাদের গণহারে হত্যা করায় কারাজোর্জের নেতৃত্বে সশস্ত্র প্রতিরোধ শুরু হলো। প্রথমে সুলতানের প্রতি অনুগত থেকে কেবল দাহিদের বিরুদ্ধে চালানো আন্দোলন অল্প সময়ে স্বায়ত্তশাসন ও স্বাধীনতা দাবিকারী জাতীয় বিদ্রোহে রূপ নিল। সার্ব বাহিনী 1806 সালে বেলগ্রেড দখল করল; এই অভ্যুত্থান বলকানে জাতীয়তাবাদী স্বাধীনতা আন্দোলনের প্রথম কড়া হলো।", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["ওয়াহহাবিদের মদিনা দখল", "84e310d7"], "d": ["মক্কার পর মদিনাও ওয়াহহাবি বাহিনীর হাতে গেল; রওজা-ই মুতাহহারার ধনভাণ্ডার বিতরণ করা হলো এবং শহরের গম্বুজযুক্ত সমাধিগুলো ধ্বংস হলো। এভাবে দুই পবিত্র শহর একসঙ্গে অটোমান নিয়ন্ত্রণ থেকে বেরিয়ে গেল এবং দামেস্ক ও মিসর থেকে আসা হজ কাফেলা বছরের পর বছর রওনা দিতে পারল না। মদিনা কেবল সাত বছর পর, 1812 সালে মেহমেদ আলি পাশার ছেলে তোসুন পাশার নেতৃত্বাধীন মিসরীয় সেনাবাহিনী ফিরিয়ে নিতে পারল।", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["রাশিয়ার সঙ্গে যুদ্ধের সূচনা (1806-1812 অটোমান-রুশ যুদ্ধ) এবং প্রণালী বন্ধ", "ea170804"], "d": ["নেপোলিয়নের অস্টারলিৎস বিজয়ের পর ফ্রান্সের নিকটবর্তী হওয়া তৃতীয় সেলিমের ওয়ালাচিয়া ও মলদোভার ভয়েভোদাদের রুশ চাপ সত্ত্বেও অপসারণ করায় রুশ সেনাবাহিনী দুই প্রিন্সিপালিটি দখল করল এবং যুদ্ধ শুরু হলো। অটোমান রাষ্ট্র প্রণালী রুশ নৌবহরের জন্য বন্ধ করল; বিনিময়ে ব্রিটেনও রাশিয়ার পাশে অবস্থান নিয়ে ইস্তানবুলে একটি বহর পাঠাল। ছয় বছর স্থায়ী এই যুদ্ধ কাবাকচি বিদ্রোহ ও তৃতীয় সেলিমের সিংহাসনচ্যুতির সঙ্গে জড়িয়ে 1812 সালের বুখারেস্ট চুক্তিতে বেসারাবিয়া হারানোয় শেষ হবে।", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["ব্রিটিশ নৌবহরের ইস্তানবুলের সামনে আগমন (ডাকওয়ার্থ অভিযান)", "195bb58f"], "d": ["অটোমান রাষ্ট্রকে ফ্রান্সের সঙ্গে বন্ধন ছিন্ন করতে বাধ্য করতে চাওয়া ব্রিটেন অ্যাডমিরাল ডাকওয়ার্থের নেতৃত্বাধীন বহর চানাক্কালে পার করে ইস্তানবুলের সামনে নোঙর ফেলল। ফরাসি দূত সেবাস্তিয়ানির নির্দেশনায় ইস্তানবুলের জনগণ সংগঠিত হলো, উপকূলীয় ব্যাটারি কয়েক দিনে শক্তিশালী করা হলো এবং শহরে গোলাবর্ষণ করতে না পেরে বহর পিছু হটতে বাধ্য হলো; ফেরার পথে চানাক্কালে ভারী ক্ষতি সইল। রাজধানী বিদেশি নৌবহরের এত কাছ থেকে প্রথমবার হুমকির মুখে পড়া প্রণালী প্রশ্নকে ইউরোপীয় কূটনীতির কেন্দ্রে স্থাপন করল।", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["চতুর্থ মুস্তাফাকে শ্বাসরোধে হত্যা", "eeb75c20"], "d": ["আলেমদার মুস্তাফা পাশা আক্রান্ত হয়ে মারা যাওয়া এবং বিদ্রোহীরা প্রাসাদের দিকে যেতে চাওয়ায়, সিংহাসনচ্যুত চতুর্থ মুস্তাফাকে ভাই দ্বিতীয় মাহমুদের আদেশে শ্বাসরোধে হত্যা করা হয়। মরদেহ বাহচেকাপিতে পিতা প্রথম আবদুলহামিদের সমাধিতে দাফন করা হয়; বিদ্রোহীদের মধ্যে কফিন খালি বলে গুজব ছড়ায়।", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["কালআ-ই সুলতানিয়্যে চুক্তি — ব্রিটেনের সঙ্গে শান্তি এবং প্রণালী নীতি", "fe282117"], "d": ["ডাকওয়ার্থ অভিযানের ব্যর্থতার পর ব্রিটেনের সঙ্গে স্বাক্ষরিত চুক্তিতে দুই রাষ্ট্রের মধ্যে যুদ্ধ শেষ হলো এবং ব্রিটিশ বণিকদের পুরোনো সুবিধা ফিরিয়ে দেওয়া হলো। পাঠে থাকা এবং 'কাদিম কাইদা' (প্রাচীন নীতি) নামে পরিচিত বিধান শান্তির সময়ে কোনো বিদেশি যুদ্ধজাহাজ প্রণালী পার হতে পারবে না বলে নথিভুক্ত করল। এই নীতি ঊনবিংশ শতাব্দী জুড়ে প্রণালী ব্যবস্থাকে আকার দেওয়া সব আন্তর্জাতিক ব্যবস্থার আইনি ভিত্তি হলো।", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["স্লোবোজিয়া পরাজয় — দানিয়ুব সেনাবাহিনীর অবরোধ", "54b60fd1"], "d": ["রুসচুকের সামনে দানিয়ুব পার হওয়া অটোমান সেনাবাহিনীর বড় অংশ কুতুজভের নদীর অপর তীর থেকে চালানো বেষ্টনী কৌশলে স্লোবোজিয়ায় আটকা পড়ল এবং ক্ষুধায় ছেড়ে দেওয়া হলো। হাজার হাজার সৈন্য আত্মসমর্পণে বাধ্য হলো; সদরে আজমের হাতে থাকা বাহিনী কার্যত গলে গেল এবং বাবে-আলি এক মাস পর যুদ্ধবিরতি চাইতে বাধ্য হলো। এই পরাজয় 1812 সালের বুখারেস্ট চুক্তিতে বেসারাবিয়া ছেড়ে দিতে সম্মত হওয়ার সরাসরি কারণ।", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["বেলগ্রেডের পুনরুদ্ধার এবং প্রথম সার্বীয় বিদ্রোহ দমন", "06f56f52"], "d": ["বুখারেস্ট চুক্তিতে রুশ সমর্থন হারানো সার্ব বিদ্রোহীরা বসনিয়া ও রুমেলিয়া থেকে আসা বাহিনীর যৌথ অভিযানের সামনে টিকতে পারল না; হুরশিদ আহমেদ পাশা বেলগ্রেডে প্রবেশ করলেন এবং নয় বছরের বিদ্রোহ সম্পূর্ণ দমন হলো। কারাজোর্জ অস্ট্রিয়ায় পালালেন, সেমেন্দিরে সানজাক আবার সরাসরি অটোমান শাসনের সঙ্গে যুক্ত হলো। তবে প্রয়োগ করা কঠোর ব্যবস্থা দুই বছর পর মিলোশ ওব্রেনোভিচের নেতৃত্বে দ্বিতীয় ও স্থায়ী বিদ্রোহের উস্কানি দেবে।", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["দ্বিতীয় সার্বীয় বিদ্রোহ এবং Miloš Obrenović-এর বাশকনেজত্ব", "e6e82ad2"], "d": ["প্রথম বিদ্রোহ দমনের পর প্রয়োগ করা ভারী ব্যবস্থার বিরুদ্ধে Miloš Obrenović-এর নেতৃত্বে নতুন অভ্যুত্থান ফেটে পড়ল; এবার বাবে-আলি শক্তির বদলে সমঝোতা বেছে নিল। সম্পাদিত চুক্তিতে Miloš 'বাশকনেজ' পদবিতে স্বীকৃত হলেন, কর আদায় ও অভ্যন্তরীণ বিষয় পরিচালনার ক্ষমতা সার্ব কনেজদের হাতে ছাড়া হলো। প্রকৃত স্বায়ত্তশাসনের এই প্রথম বীজ 1830 সালের ফরমান ও 1878 সালের স্বাধীনতা পর্যন্ত বিস্তৃত প্রক্রিয়ার সূচনাবিন্দু হলো।", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["ওয়ালাচিয়া বিদ্রোহ — ইপসিলান্তির প্রুত পার হওয়া এবং ভ্লাদিমিরেস্কুর অভ্যুত্থান", "67d46a98"], "d": ["রুশ সেনাবাহিনীর জেনারেল আলেকসান্দর ইপসিলান্তি ফিলিকি এতেরিয়ার পক্ষে প্রুত পার হয়ে ওয়ালাচিয়া ও মলদোভায় সাধারণ গ্রিক অভ্যুত্থান শুরুর চেষ্টা করলেন; একই দিনগুলোতে তুদোর ভ্লাদিমিরেস্কুও স্থানীয় কৃষকদের সক্রিয় করলেন। দুই আন্দোলন একত্র হতে পারল না: ভ্লাদিমিরেস্কু ইপসিলান্তির একসঙ্গে তুর্কিদের বিরুদ্ধে লড়ার আহ্বানে 'আমি তুর্কিদের বিরুদ্ধে নয়, গ্রিকদের বিরুদ্ধে বিদ্রোহ করেছি' উত্তর দিলেন এবং অল্পকাল পরে ইপসিলান্তির লোকদের হাতে নিহত হলেন। বিদ্রোহ অটোমান বাহিনী মে মাসে দমন করল, তবে ফেনারি ভয়েভোদাত্ব ব্যবস্থা শেষ হলো এবং বিদ্রোহের আগুন মোরিয়ায় ছড়াল।", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["রিয়াদে দ্বিতীয় সৌদি রাষ্ট্রের প্রতিষ্ঠা", "34dad3bd"], "d": ["1818 সালে দিরিয়ার পতন এবং প্রথম সৌদি রাষ্ট্র ধ্বংসের ছয় বছর পর তুর্কি ইবনে আবদুল্লাহ মিসরীয় গ্যারিসনকে নাজদ থেকে বের করে রিয়াদকেন্দ্রিক নতুন সৌদি আমিরাত প্রতিষ্ঠা করলেন। নতুন কাঠামো হিজাজ পর্যন্ত প্রসারণ এড়িয়ে নাজদে থাকাকেই বেছে নিল এবং অটোমান-মিসরীয় বাহিনীর সঙ্গে সরাসরি সংঘর্ষ থেকে দূরে রইল। এই দ্বিতীয় রাষ্ট্র শতাব্দীর শেষ পর্যন্ত টিকবে এবং বর্তমান সৌদি আরবের প্রতিষ্ঠায় যাওয়া শৃঙ্খলের দ্বিতীয় কড়া গঠন করবে। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: দিরিয়া (নাজদ)।", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["আক্কিরমান চুক্তি — সার্বিয়া ও প্রিন্সিপালিটিগুলোকে ছাড়", "c75f15d0"], "d": ["জ্যানিসারি বাহিনী বিলুপ্তির ঠিক পরে সেনাবাহিনীহীন অটোমান রাষ্ট্র রাশিয়ার আল্টিমেটামের মুখে ভারী শর্তের চুক্তি মেনে নিতে বাধ্য হলো। সার্বিয়াকে প্রতিশ্রুত স্বায়ত্তশাসন নিশ্চিত হলো, ওয়ালাচিয়া ও মলদোভার ভয়েভোদাদের রুশ অনুমোদন ছাড়া অপসারণ করা যাবে না বলে মানা হলো, রুশ বাণিজ্য জাহাজকে প্রণালীতে পূর্ণ স্বাধীনতা দেওয়া হলো। বাবে-আলি দুই বছর পর গ্রিক প্রশ্নে চুক্তি স্বীকার করে না বলে ঘোষণা করলে রাশিয়া একে যুদ্ধের কারণ গণ্য করবে।", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["তিমার ব্যবস্থার অবসান", "84d5d1d6"], "d": ["জ্যানিসারি বাহিনী বিলুপ্তির এক বছর পর রুমেলিয়া ও আনাতোলিয়ার তিপ্পান্নটি সানজাকে থাকা প্রায় 5.200 তিমারধারী সিপাহি তিমার আয়সহ আসাকির-ই মানসুরে অশ্বারোহী বাহিনীতে রূপান্তরিত হলো। এভাবে অটোমান ভূমি, কর ও সেনা ব্যবস্থার চার শতাব্দীর মেরুদণ্ড তিমার ব্যবস্থা কার্যত শেষ হলো। খালি হওয়া তিমারগুলো কোষাগারে স্থানান্তরিত হলো এবং কেন্দ্রীয় বেতনভুক্ত সেনাবাহিনী ও নগদ কর ব্যবস্থায় উত্তরণের পথ খুলল।", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["তিপহানে-ই আমিরের প্রতিষ্ঠা — আধুনিক চিকিৎসা শিক্ষার সূচনা", "ac3e57c0"], "d": ["নবগঠিত আসাকির-ই মানসুরে বাহিনীর জন্য চিকিৎসক ও শল্যচিকিৎসক তৈরির উদ্দেশ্যে হেকিমবাশি মুস্তাফা বেহচেত এফেন্দির প্রস্তাবে শেহজাদেবাশিতে তিপহানে-ই আমিরে খোলা হলো। পাঠ ইউরোপের পাঠ্যক্রম অনুযায়ী সাজানো হলো এবং শিক্ষা প্রথমে ফরাসিতে হলো; কয়েক বছর পর জাররাহহানে-ই আমিরেও প্রতিষ্ঠা করে দুই প্রতিষ্ঠান একীভূত করা হলো। তুরস্কে আধুনিক চিকিৎসা শিক্ষার সূচনা গণ্য এই বিদ্যালয় আজকের ইস্তানবুল মেডিকেল ফ্যাকাল্টির মূল বলে মানা হয়।", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["1828-1829 অটোমান-রুশ যুদ্ধের সূচনা", "9dff4e05"], "d": ["নাভারিনোতে নৌবহর পোড়ানো এবং বাবে-আলির আক্কিরমান চুক্তি স্বীকার করে না বলে ঘোষণায় রাশিয়া একসঙ্গে দুই ফ্রন্টে যুদ্ধ শুরু করল। জ্যানিসারি বাহিনী সদ্য বিলুপ্ত, নতুন সেনাবাহিনী গঠনের পর্যায়ে থাকায় অটোমান প্রতিরক্ষা শুরু থেকেই দুর্বল ছিল; রুশরা দানিয়ুব পার হওয়ার সময় পূর্বে কার্স ও আখালতসিখে নিল। এক বছরের মধ্যে এডির্ন পর্যন্ত এগোনো রুশ সেনাবাহিনী 1829 সালের এডির্ন চুক্তির ভারী শর্ত ও গ্রিসের স্বাধীনতা চাপিয়ে দেবে।", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["মার্কিন যুক্তরাষ্ট্রের সঙ্গে প্রথম চুক্তি", "d737516f"], "d": ["বছরের পর বছর যোগাযোগের পর স্বাক্ষরিত বাণিজ্য ও নৌচলাচল চুক্তিতে যুক্তরাষ্ট্র অটোমান ভূমিতে 'সর্বাধিক সুবিধাপ্রাপ্ত জাতি' মর্যাদা এবং প্রণালী দিয়ে বাণিজ্যিক যাতায়াতের অধিকার পেল। একটি আলাদা গোপন ধারায় অটোমানদের চাইলে মার্কিন নৌঘাঁটিতে জাহাজ বানানো, তৈরি জাহাজ ও কাঠ কেনার ব্যবস্থা ছিল; মার্কিন সিনেট চুক্তি অনুমোদন করলেও এই গোপন ধারা 18-এর বিপরীতে 27 ভোটে প্রত্যাখ্যান করল। জাহাজের পথ তবু বন্ধ হলো না: হেনরি একফোর্ড 1831 সালে আনা জাহাজ অটোমানদের কাছে বিক্রি করলেন, আইনালিকাভাকে কাজ করা মার্কিন কারিগররা নৌবহরকে নতুন ধরনের জাহাজ দিলেন। এই চুক্তি অটোমান রাষ্ট্রের ইউরোপের বাইরের কোনো রাষ্ট্রের সঙ্গে গড়া প্রথম ব্যাপক সম্পর্কের দলিল হলো।", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["বাগদাদে কোলেমেন শাসনের অবসান", "7e1d38a3"], "d": ["কেন্দ্রীকরণ নীতি অনুসরণকারী দ্বিতীয় মাহমুদ চাওয়া অর্থ না পাঠানো এবং কেন্দ্র থেকে আসা কর্মকর্তাকে হত্যা করানো বাগদাদের গভর্নর দাউদ পাশাকে বিদ্রোহী ঘোষণা করলেন। আলি রিজা পাশার নেতৃত্বাধীন বাহিনী নব্বই দিনের অবরোধের পর শহর দখল করল এবং কোলেমেনদের প্রায় সবাইকে সরিয়ে দেওয়া হলো। এভাবে 1704 সাল থেকে চলা আধা-স্বাধীন কোলেমেন শাসন শেষ হলো এবং ইরাক আবার সরাসরি কেন্দ্রের সঙ্গে যুক্ত হলো।", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["মাচকা সেনানিবাসে মেকতেব-ই হারবিয়ের প্রতিষ্ঠা", "bf31c7d9"], "d": ["আসাকির-ই মানসুরে-ই মুহাম্মদিয়্যেকে ইউরোপীয় ধাঁচে প্রশিক্ষিত অফিসার জোগাতে মাচকা সেনানিবাসে মেকতেব-ই ফুনুন-ই হারবিয়্যে খোলা হলো। শিক্ষার্থীদের গণিত, মানচিত্র, দুর্গবিদ্যা ও বিদেশি ভাষা পড়ানো হলো; অল্প সময় পর ভিয়েনা ও প্যারিসে শিক্ষার্থী পাঠিয়ে কর্মীদল শক্তিশালী করা হলো। এই বিদ্যালয় অটোমান সেনাবাহিনীতে বিদ্যালয়-শিক্ষিত অফিসার ঐতিহ্যের এবং ফলে ঊনবিংশ শতাব্দীর শেষে আবির্ভূত নতুন সেনা-বুদ্ধিজীবী প্রজন্মের জন্মস্থান হলো।", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["ত্রিপোলির সরাসরি কেন্দ্রের সঙ্গে যুক্ত হওয়া — কারামানলি রাজবংশের অবসান", "faabcb96"], "d": ["কারামানলি পরিবারের অভ্যন্তরীণ সিংহাসন-দ্বন্দ্ব এবং ফ্রান্সের 1830 সালে আলজিয়ার্স দখলের পর বেড়ে ওঠা ইউরোপীয় চাপে বাবে-আলি ত্রিপোলিতে সরাসরি হস্তক্ষেপ করল। ইস্তানবুল থেকে পাঠানো নৌবহর শহরে প্রবেশ করল, শেষ কারামানলি বে অপসারিত হয়ে ইস্তানবুলে আনা হলো এবং প্রদেশ কেন্দ্র থেকে নিযুক্ত একজন গভর্নরের হাতে সমর্পিত হলো। 124 বছরের রাজবংশীয় যুগ শেষ হওয়ার সময় উত্তর আফ্রিকায় অটোমান রাষ্ট্রের সরাসরি শাসিত শেষ ভূখণ্ড সুদৃঢ় হলো।", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["দেফতারদারত্ব বিলুপ্ত করে অর্থ মন্ত্রণালয়ের প্রতিষ্ঠা", "89f8125e"], "d": ["ক্লাসিক অটোমান আর্থিক ব্যবস্থার শীর্ষ দেফতারদারত্ব পদ বিলুপ্ত করে ইউরোপীয় ধাঁচের মন্ত্রণালয় মালিয়ে নাজারেতি প্রতিষ্ঠিত হলো এবং বিক্ষিপ্ত কোষাগারগুলো এক হাতে আনা হলো। একই বছর বাবে-আলির অন্যান্য ইউনিটও নাজারেত নামে পুনর্গঠিত হয়ে আধুনিক মন্ত্রিসভা কাঠামোয় যাওয়া হলো। এই ব্যবস্থা এক বছর পর ঘোষিত তানজিমাত ফরমানের প্রশাসনিক ভিত্তি প্রস্তুতকারী সবচেয়ে গুরুত্বপূর্ণ পদক্ষেপগুলোর একটি ছিল।", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["ব্রিটিশদের আদেনে বসতি স্থাপন", "ddbd556b"], "d": ["ব্রিটেন 1802 সালে লাহিজ সুলতান আহমেদ ইবনে আবদুল করিমের সঙ্গে স্বাক্ষরিত বাণিজ্য ও বন্ধুত্ব চুক্তির ভিত্তিতে আদেন বন্দরে সৈন্য নামিয়ে শহর নিয়ন্ত্রণে নিল। লোহিত সাগরের মুখ ধরে রাখা এই বন্দর ভারতের পথের কয়লা সরবরাহ ঘাঁটি হিসেবে ব্রিটিশ সাম্রাজ্যিক কৌশলের মূল বিন্দুতে পরিণত হলো। অটোমান রাষ্ট্রের ইয়েমেনের ওপর দাবি কাগজে চললেও দক্ষিণ উপকূলে প্রকৃত কর্তৃত্ব এই তারিখের পর আর ফিরল না।", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["তিহামা উপকূলে প্রত্যাবর্তন: হুদাইদা, জাবিদ ও মোখা দখল", "353982d2"], "d": ["1840 সালে মিসরীয় সেনাবাহিনী সরে যাওয়ায় মালিকহীন ইয়েমেন উপকূলে মক্কার শরিফের তত্ত্বাবধানে তাওফিক পাশার নেতৃত্বাধীন বাহিনী নেমে হুদাইদা, জাবিদ ও মোখা বন্দর অটোমান শাসনের সঙ্গে যুক্ত করল। সানা পর্যন্ত এগোনোর ইচ্ছা থাকলেও জনগণের প্রতিরোধে হুদাইদায় ফিরে আসা হলো; এভাবে উচ্চভূমি জায়দি ইমামদের হাতে রইল এবং অটোমান কর্তৃত্ব তেইশ বছর কেবল তিহামা ফালিতে চলল। অভ্যন্তরীণ ইয়েমেন কেবল 1872 সালে আহমেদ মুখতার পাশার অভিযানে ফিরিয়ে নেওয়া হবে।", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["বালতালিমানি চুক্তি: ওয়ালাচিয়া ও মলদোভায় যৌথ অটোমান-রুশ আশ্রয়", "d3bb22e9"], "d": ["1848 সালের বিপ্লব ওয়ালাচিয়া ও মলদোভায় ছড়ানোর পর অটোমান ও রুশ বাহিনী প্রিন্সিপালিটি দুটি যৌথভাবে দখল করেছিল। বালতালিমানিতে স্বাক্ষরিত চুক্তিতে ভয়েভোদাদের নির্বাচনে নয়, সুলতানের নিযুক্তিতে সাত বছরের জন্য রাখা এবং দুই রাষ্ট্রের অঞ্চলে যৌথ নিয়ন্ত্রণ প্রতিষ্ঠা স্থির হলো। চুক্তি অটোমানদের কাগজে-কলমে সার্বভৌমত্ব রক্ষা করলেও রাশিয়াকে প্রকৃত অংশীদারত্বের অধিকার দিল এবং দানিয়ুব প্রিন্সিপালিটির অটোমানদের কাছ থেকে বিচ্ছিন্ন হওয়া ত্বরান্বিত করল।", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["হাঙ্গেরীয় শরণার্থী প্রশ্ন: কসুথ ও সঙ্গীদের অটোমানদের আশ্রয় গ্রহণ", "1c7d7ef4"], "d": ["1848-1849 সালের হাঙ্গেরীয় বিপ্লব রুশ-অস্ট্রিয়ান হস্তক্ষেপে দমন হওয়ায় লাইয়োশ কসুথ ও হাজার হাজার হাঙ্গেরীয়-পোলিশ শরণার্থী অটোমান ভূমিতে আশ্রয় নিলেন। অস্ট্রিয়া ও রাশিয়া শরণার্থীদের ফেরত চাইল কঠোরভাবে; বাবে-আলি ব্রিটেন ও ফ্রান্সের সমর্থনে ফেরত দিতে অস্বীকার করল এবং দলটিকে কুতাহিয়ায় বসাল। কসুথের দল এখানে প্রায় আঠারো মাস থাকল, শত শত শরণার্থী মুসলমান হয়ে অটোমান সেবায় যোগ দিল। ঘটনা তানজিমাত অটোমানদের ইউরোপীয় জনমতে মর্যাদা বাড়ানো বিরল কূটনৈতিক বিজয়গুলোর একটি গণ্য হলো।", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["এনজুমেন-ই দানিশের প্রতিষ্ঠা: ইস্তানবুলে প্রথম অটোমান একাডেমি", "6fda1365"], "d": ["মজলিস-ই মাআরিফ-ই উমুমিয়্যের সিদ্ধান্তে প্রতিষ্ঠিত এনজুমেন-ই দানিশ তুর্কি ভাষায় জ্ঞান ও পাঠ্যবই প্রস্তুত করার জন্য গঠিত প্রথম অটোমান বিজ্ঞান একাডেমি। 18 জুলাই 1851 সালে দারুল-মাআরিফ ভবনে অনুষ্ঠানের মাধ্যমে উদ্বোধিত হলো; স্থানীয় ও বিদেশি সদস্যদের মধ্যে আহমেদ জেভদেত পাশাও ছিলেন। স্বল্পস্থায়ী হলেও জেভদেত পাশার তারিখ ও কাওয়াইদ-ই উসমানিয়্যের মতো রচনা এই প্রতিষ্ঠানের ফল হলো এবং তুর্কি ভাষার জ্ঞানের ভাষা হয়ে ওঠায় ভিত্তিপ্রস্তর গণ্য হলো।", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["ওলতেনিৎসা বিজয়: দানিয়ুব ফ্রন্টে প্রথম অটোমান সাফল্য", "a660ad2f"], "d": ["ক্রিমিয়া যুদ্ধের উদ্বোধনী পর্বে সেরদার-ই একরেম ওমর লুৎফি পাশা দানিয়ুব পার হয়ে ওলতেনিৎসায় রুশ বাহিনীকে ভারী ক্ষতিসহ প্রতিহত করলেন। বিজয় যুদ্ধের একেবারে শুরুতে রুশ অগ্রগতি থামিয়ে অটোমান সেনাবাহিনীর তানজিমাত-পরবর্তী প্রশিক্ষণে অর্জিত শক্তি ইউরোপকে দেখাল। এই সাফল্য ব্রিটেন ও ফ্রান্সের অটোমানদের পক্ষে যুদ্ধে নামার সিদ্ধান্ত সহজ করা মনস্তাত্ত্বিক ভিত্তি প্রস্তুত করল।", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["ইস্তানবুলে ব্রিটেন ও ফ্রান্সের সঙ্গে মৈত্রী চুক্তি", "04809278"], "d": ["ক্রিমিয়া যুদ্ধে রাশিয়ার বিরুদ্ধে অটোমান রাষ্ট্র এবং ব্রিটেন ও ফ্রান্সের মধ্যে স্বাক্ষরিত মৈত্রী চুক্তি তিন রাষ্ট্রের যৌথ অভিযান পরিচালনা এবং মিত্ররা যুদ্ধ শেষ হওয়ার আগে আলাদা শান্তি না করার বিধান করল। এভাবে অটোমান রাষ্ট্র ইতিহাসে প্রথমবার বড় ইউরোপীয় রাষ্ট্রগুলোর সঙ্গে সমান পক্ষ হিসেবে সামরিক মৈত্রীতে প্রবেশ করল। এই চুক্তি দুই বছর পর প্যারিসে অটোমানদের ইউরোপীয় রাষ্ট্র ব্যবস্থায় আনুষ্ঠানিক গ্রহণের আইনি ভিত্তিও গঠন করল।", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["ইস্তানবুল শেহরেমানেতির প্রতিষ্ঠা: প্রথম আধুনিক পৌরসভা সংগঠন", "be4af27f"], "d": ["ক্রিমিয়া যুদ্ধের সময় ইস্তানবুলে জড়ো হওয়া মিত্র সৈন্য ও বেড়ে ওঠা জনসংখ্যার সৃষ্ট অবকাঠামো সংকট কাজিকেন্দ্রিক ক্লাসিক শহর প্রশাসনের অপর্যাপ্ততা প্রকাশ করল। ইউরোপীয় দৃষ্টান্ত অনুযায়ী গঠিত শেহরেমানেতির মাধ্যমে পরিচ্ছন্নতা, মূল্য নির্ধারণ, বাজার পরিদর্শন ও নগর উন্নয়ন এক হাতে আনা হলো; পরের বছর বেইওগলু-গালাতায় ষষ্ঠ পৌর বিভাগ পরীক্ষামূলক অঞ্চল হিসেবে গঠিত হলো। এই পদক্ষেপ অটোমানদের আধুনিক পৌরব্যবস্থার সূচনা গণ্য হয়।", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["প্যারিস চুক্তি: ক্রিমিয়া যুদ্ধের সমাপ্তি এবং অটোমানদের ইউরোপীয় রাষ্ট্র ব্যবস্থায় গ্রহণ", "4aee0e2a"], "d": ["ক্রিমিয়া যুদ্ধ শেষ করা প্যারিস চুক্তিতে অটোমান রাষ্ট্র ইউরোপীয় রাষ্ট্র আইনের সমান সদস্য ঘোষিত হলো এবং ভূখণ্ডগত অখণ্ডতা বড় শক্তিগুলোর যৌথ গ্যারান্টির আওতায় এল। কৃষ্ণ সাগর নিরপেক্ষ করা হলো, কুচুক কায়নারজা থেকে রাশিয়ার অর্জিত অর্থোডক্স প্রজাদের ওপর আশ্রয়ের দাবি বাতিল হলো, বেসারাবিয়ার দক্ষিণ (কিলিয়া, কাহুল, ইসমাইল ও বলগ্রাদ কাজা) মলদোভাকে দেওয়া হলো। তবে একই চুক্তি ইসলাহাত ফরমানকে আন্তর্জাতিক অঙ্গীকারে পরিণত করে অভ্যন্তরীণ বিষয়ে হস্তক্ষেপের দরজাও খুলে দিল।", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["দলমাবাহচে প্রাসাদের উদ্বোধন: প্রশাসনকেন্দ্রের তোপকাপি থেকে স্থানান্তর", "71ad26d0"], "d": ["আবদুলমেজিদের 1842 সালে বালিয়ান পরিবারকে ফরমায়েশ দেওয়া প্রাসাদ চৌদ্দ বছরের নির্মাণের পর খোলা হলো এবং রাষ্ট্রের প্রশাসনকেন্দ্র চার শতাব্দীর তোপকাপি থেকে প্রণালী তীরে সরানো হলো। ইউরোপীয় শৈলী, স্ফটিক সিঁড়ি ও মুআয়েদে হলসহ প্রাসাদ তানজিমাতের পশ্চিমীকরণ দাবির পাথুরে প্রকাশ হলো। বিপুল ব্যয় অটোমান অর্থব্যবস্থার বৈদেশিক ঋণের ঘূর্ণিতে প্রবেশের বছরগুলোর সবচেয়ে সমালোচিত খাতগুলোর একটিতে পরিণত হলো।", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["কুজার নেতৃত্বে ওয়ালাচিয়া ও মলদোভার একীকরণ: রোমানিয়ার জন্ম", "baef4da5"], "d": ["প্যারিস চুক্তির পর অনুষ্ঠিত নির্বাচনে দুই প্রিন্সিপালিটিই কর্নেল আলেকসান্দ্রু ইওয়ান কুজাকে ভয়েভোদা নির্বাচিত করে প্রকৃত একীকরণ ঘটাল। বাবে-আলি ও অস্ট্রিয়া বিরোধিতা করলেও ফ্রান্সের সমর্থিত এই সম্পন্ন-ঘটনা মেনে নিতে হলো। কাগজে অটোমানদের সঙ্গে যুক্ত থাকা এই ঐক্য 1862 সালে রোমানিয়া নাম নেবে, 1877 সালে একতরফা স্বাধীনতা ঘোষণা করবে; দানিয়ুব তীরে অটোমান কর্তৃত্বের ভাঙনে মোড় গণ্য।", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["কুলেলি ঘটনা: ইস্তানবুলে আবদুলমেজিদের বিরুদ্ধে প্রথম অভ্যুত্থান চেষ্টা", "e3653b21"], "d": ["তানজিমাত নীতি ও ইসলাহাত ফরমানের অমুসলিমদের দেওয়া সমতার প্রতি প্রতিক্রিয়াশীল সেনা-বেসামরিক মিশ্র গোপন সংগঠন সুলতানকে সিংহাসনচ্যুত করার পরিকল্পনা করার সময় কিলিচ আলি পাশা মসজিদের বৈঠকে অভিযানের শিকার হলো। অভিযুক্তদের কুলেলি সেনানিবাসে বিচার হওয়ায় ঘটনা এই নামে পরিচিত; মৃত্যুদণ্ড নির্বাসনে পরিবর্তিত হলো। অটোমান ইতিহাসে মতাদর্শগত কারণে গঠিত সংগঠনের প্রথম প্রাসাদ অভ্যুত্থান প্রচেষ্টা গণ্য।", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["লেবানন পর্বতে দ্রুজ-মারোনি গৃহযুদ্ধ এবং দামেস্ক ঘটনা", "5595fdd6"], "d": ["1860 সালের মে মাসে সিডনের কাছে দুই দ্রুজের মৃত্যুতে ফেটে পড়া সংঘর্ষ পর্বতের সবচেয়ে রক্তাক্ত দ্রুজ-মারোনি গৃহযুদ্ধে পরিণত হলো এবং জুলাইয়ে দামেস্কে ছড়িয়ে হাজার হাজার খ্রিস্টানের মৃত্যুতে শেষ হলো। ফ্রান্সের সৈন্য নামানোয় বাবে-আলি ফুয়াদ পাশাকে অসাধারণ ক্ষমতাসহ অঞ্চলে পাঠাল; কঠোর শাস্তিমূলক অভিযান চলল। ঘটনাগুলো ইউরোপীয় হস্তক্ষেপের অজুহাত তৈরি করল এবং লেবাননের বিশেষ মর্যাদা পাওয়ার সরাসরি কারণ হলো।", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["তের্জুমান-ই আহওয়ালের প্রকাশ শুরু: ইস্তানবুলে প্রথম বেসরকারি তুর্কি সংবাদপত্র", "24792957"], "d": ["আগাহ এফেন্দির প্রকাশিত এবং শিনাসির সম্পাদনার দায়িত্বে থাকা তের্জুমান-ই আহওয়াল রাষ্ট্রীয় সমর্থন ছাড়া প্রকাশিত প্রথম তুর্কি সংবাদপত্র। প্রথম সংখ্যার ভূমিকায় জনগণের নিজের বিষয়ে কথা বলার অধিকার সমর্থিত হয়েছিল, পত্রিকা শিনাসির 'শাইর এভলেনমেসি' ধারাবাহিক ছেপে আধুনিক তুর্কি সাহিত্যের দরজাও খুলেছিল। অটোমানদের জনমত ধারণা ও বিরোধী সংবাদমাধ্যমের জন্ম এই তারিখের ওপর ভিত্তি করে ধরা হয়।", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["লেবানন পর্বত নিয়মাবলি: লেবাননকে সুবিধাভোগী মুতাসাররিফিয়াত মর্যাদা", "bf375603"], "d": ["1860 সালের হত্যাকাণ্ডের পর বড় শক্তিগুলোর চাপে প্রস্তুত নিয়মাবলি লেবানন পর্বতকে সরাসরি বাবে-আলির অধীন, সম্প্রদায়গত ভারসাম্য অনুযায়ী গঠিত প্রশাসন পরিষদ দ্বারা শাসিত সুবিধাভোগী মুতাসাররিফিয়াতে পরিণত করল। মুতাসাররিফকে অটোমান প্রজা ক্যাথলিক খ্রিস্টান হতে হবে এবং নিযুক্তি বড় শক্তিগুলোর অনুমোদনে পেশ করতে হবে বলে শর্ত রাখা হলো; প্রথম মুতাসাররিফ হলেন দাউদ পাশা। এই ব্যবস্থা 1915 সাল পর্যন্ত চলবে এবং আধুনিক লেবানন রাষ্ট্রের মূল গঠন করবে।", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["আবদুলমেজিদের মৃত্যু এবং সুলতান আবদুলআজিজের সিংহাসনারোহণ", "27204d7c"], "d": ["বাইশ বছরের রাজত্বে তানজিমাত ও ইসলাহাত ফরমানে স্বাক্ষর করা আবদুলমেজিদ যক্ষ্মায় মারা গেলে ভাই আবদুলআজিজ সিংহাসনে বসলেন। নতুন সুলতান প্রথম বছরগুলোতে ব্যয়সংকোচন ব্যবস্থা ও সাদাসিধে জীবনযাপনে আশা জাগালেন; নৌবহরকে বিশ্বের গণনাযোগ্য শক্তিগুলোর একটিতে পরিণত করলেন। কিন্তু রাজত্বের শেষে ভারী বৈদেশিক ঋণ, 1875 সালের দেউলিয়াত্ব ও বলকান বিদ্রোহ জমে 1876 সালের অপসারণ আন্দোলনের ভিত্তি প্রস্তুত করবে।", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["সংযুক্ত প্রিন্সিপালিটির রোমানিয়া নাম গ্রহণ", "d960e3fc"], "d": ["1859 সালে কুজার দ্বৈত নির্বাচনে প্রকৃতপক্ষে একীভূত ওয়ালাচিয়া ও মলদোভা 1862 সালে সংসদ ও সরকার বুখারেস্টে এক ছাদের নিচে এনে আনুষ্ঠানিকভাবে রোমানিয়া নাম নিল। অটোমান রাষ্ট্র আইনত সুজারেন মর্যাদা ও বার্ষিক কর বজায় রাখলেও প্রিন্সিপালিটির ওপর নিয়ন্ত্রণ প্রকৃতপক্ষে হারাল। দানিয়ুবের উত্তরে চার শতাব্দীর অটোমান প্রভাবের অবসান এই তারিখে প্রতীকীভাবে চিহ্নিত।", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["সাওয়াকিন, মাসাওয়া ও দাহলাকের মিসরের সঙ্গে যুক্ত হওয়া", "a0924860"], "d": ["1846 সালে সুলতান আবদুলমেজিদ কর্তৃক মিসরের খেদিভ মেহমেদ আলি পাশাকে সাওয়াকিনের সঙ্গে সালিয়ানে (আয় বরাদ্দ) হিসেবে দেওয়া মাসাওয়া, খেদিভ ইসমাইল পাশার আমলে দাহলাক ও সাওয়াকিনের সঙ্গে মিসরের সম্পত্তিতে অন্তর্ভুক্ত হয়ে কায়মাকামত মর্যাদায় সংগঠিত হলো। এভাবে লোহিত সাগরের আফ্রিকা উপকূলের এই তিন বন্দর আইনত অটোমান ভূমি থাকলেও প্রশাসনিকভাবে সরাসরি বাবে-আলি থেকে কায়রোর হাতে গেল — প্রতিবেশী মিসর ও সুদানের মতো একই অনুগত স্তরে পড়ল।", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["ক্রিট বিদ্রোহের সূচনা (1866-1869)", "3679b861"], "d": ["গ্রিসের প্রকাশ্য সমর্থনে দ্বীপে ফেটে পড়া ব্যাপক অভ্যুত্থান ক্রিটের গ্রিকদের এনোসিস (গ্রিসের সঙ্গে যুক্ত হওয়ার) দাবিকে প্রথমবার আন্তর্জাতিক প্রশ্নে পরিণত করল। তিন বছর স্থায়ী কঠিন পাহাড়ি যুদ্ধ অটোমান সেনাবাহিনীকে ভারী ক্ষতি সহাল, ইউরোপীয় জনমতে বড় সাড়া জাগাল। বিদ্রোহ কেবল 1868 সালে আলি পাশার দ্বীপে গিয়ে বিস্তৃত সুবিধা দেওয়া নিয়মাবলি কার্যকর করায় প্রশমিত হলো।", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["বেলগ্রেড ও সার্বিয়ার দুর্গগুলো থেকে শেষ অটোমান গ্যারিসনের সরে যাওয়া", "b34217db"], "d": ["বড় শক্তিগুলোর চাপ এবং প্রিন্স মিহাইলোর জোরালো দাবিতে বাবে-আলি সার্বিয়ায় অবশিষ্ট শেষ সামরিক ঘাঁটিগুলো খালি করতে সম্মত হলো; 18 এপ্রিল 1867 সালে বেলগ্রেড দুর্গের অটোমান পতাকা নামিয়ে চাবি প্রিন্সের হাতে সমর্পণ করা হলো। এভাবে 1521 সাল থেকে চলা প্রকৃত অটোমান সামরিক উপস্থিতি শেষ হলো এবং সার্বিয়ার স্বাধীনতার পথে শেষ বড় বাধা সরে গেল। সুলতানের সুজারেনত্ব কেবল প্রতীকী পতাকা ও করের বিষয়ে নেমে এল।", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["মিসরের গভর্নরদের খেদিভ উপাধি প্রদান", "09e10c12"], "d": ["কাভালা রাজবংশের তৃতীয় প্রজন্মের ইসমাইল পাশার তীব্র তদবির এবং ইস্তানবুলে ঢালা অর্থের ফলে মিসরের গভর্নরকে অন্য গভর্নরদের চেয়ে শ্রেষ্ঠত্ব জোর দেওয়া খেদিভ উপাধি দেওয়া হলো। একই বছরগুলোতে উত্তরাধিকার ব্যবস্থাও পিতা থেকে পুত্রে হস্তান্তরের ধরনে বদলানো হলো এবং মিসরকে বৈদেশিক ঋণ নেওয়া, পদক দেওয়া, কনসুলেট রাখার মতো সার্বভৌমত্বমূলক ক্ষমতা দেওয়া হলো। এই পদক্ষেপগুলো মিসরের অটোমানদের কাছ থেকে আইনত বিচ্ছিন্ন হওয়া ত্বরান্বিতকারী শৃঙ্খলের প্রথম কড়া।", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["ক্রিট নিয়মাবলি: দ্বীপে বিস্তৃত প্রশাসনিক সুবিধা", "12052262"], "d": ["তিন বছরের বিদ্রোহ শেষ করতে সদরে আজম আলি পাশা নিজে দ্বীপে গেলেন এবং সুলতানের অনুমোদনে প্রকাশিত নিয়মাবলিতে ক্রিটবাসীদের মিশ্র প্রশাসন পরিষদ, স্থানীয় আদালত, সরকারি কাজে গ্রিক ভাষার ব্যবহার ও কর সুবিধা দেওয়া হলো। এই ব্যবস্থা দ্বীপে অটোমান কর্তৃত্ব আরও ত্রিশ বছর টিকিয়ে রাখল। তবে খ্রিস্টান জনসংখ্যাকে দেওয়া সুবিধা মুসলিম ক্রিটবাসীদের অবস্থান দুর্বল করল এবং 1896-1898 সংকটের বীজ বপন করল।", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["শুরা-ই দেভলেতের উদ্বোধন: অটোমান কাউন্সিল অব স্টেটের প্রতিষ্ঠা", "70b16497"], "d": ["5 মার্চ 1868 তারিখের ইরাদে দ্বারা মজলিস-ই আহকাম-ই আদলিয়্যে দুই ভাগ হয়ে প্রশাসনিক-আইনসংক্রান্ত কাজ শুরা-ই দেভলেতে, বিচারকাজ দিওয়ান-ই আহকাম-ই আদলিয়্যেতে দেওয়া হলো; প্রতিষ্ঠান বাবে-আলিতে অনুষ্ঠানের মাধ্যমে খোলা হলো এবং প্রথম সভাপতি করা হলো মিধহাত পাশাকে। আইনের খসড়া তৈরি, প্রশাসনিক বিরোধ নিষ্পত্তি ও কর্মকর্তাদের বিচার পরিচালনার দায়িত্ব দেওয়া হলো। মুসলিম-অমুসলিম মিশ্র সদস্য কাঠামোয় অটোমানদের ক্ষমতা পৃথকীকরণ ধারণার প্রথম প্রাতিষ্ঠানিক প্রয়োগ গণ্য।", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["সুয়েজ খালের উদ্বোধন: মিসর হয়ে ভারতের পথ সংক্ষিপ্ত", "377ccd04"], "d": ["1859 সালে শুরু হওয়া নির্মাণ দশ বছর চলল এবং ভূমধ্যসাগরকে লোহিত সাগরের সঙ্গে যুক্ত করা 163 কিলোমিটারের খাল জাঁকজমকপূর্ণ অনুষ্ঠানে চালু হলো। ইউরোপকে ভারতের সঙ্গে যুক্ত করা পথ হাজার হাজার মাইল সংক্ষিপ্ত হওয়ায় মিসর হঠাৎ বিশ্ব বাণিজ্যের মূল বিন্দুতে পরিণত হলো। এই ভূ-কৌশলগত মূল্য খাল খোলার তেরো বছর পর ব্রিটেনের মিসর দখলের প্রধান কারণ হবে; খাল মিসরের ওপর যে ঋণ চাপাল তা খেদিভিয়াতকে দেউলিয়াত্বে ঠেলে দেবে।", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["বুলগার এক্সার্কেটের প্রতিষ্ঠা: বুলগার চার্চের ফেনার থেকে পৃথক হওয়া", "33a8272c"], "d": ["সুলতানের ফরমানে গ্রিক প্যাট্রিয়ার্কেট থেকে আলাদা স্বতন্ত্র বুলগার চার্চ (এক্সার্কেট) গঠিত হলো এবং কোন কাজা এক্সার্কেটের সঙ্গে যুক্ত হবে তা জনগণের ভোটে ছাড়া হলো। বাবে-আলি এই পদক্ষেপ গ্রিক প্রভাব ভাঙতে নিলেও ফল উল্টো হলো: চার্চ বুলগার জাতীয় পরিচয় এবং ম্যাসিডোনিয়ার ওপর বুলগার দাবির সংগঠিত কেন্দ্রে পরিণত হলো। বলকানে বুলগার-গ্রিক-সার্ব প্রতিদ্বন্দ্বিতা ও 1876 সালের বিদ্রোহের প্রাতিষ্ঠানিক ভিত্তি এভাবে স্থাপিত হলো।", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["আসিরকে সরাসরি শাসনে আনা", "4559e099"], "d": ["সুয়েজ খাল খোলার ফলে লোহিত সাগরের কৌশলগত গুরুত্ব বাড়লে ইয়েমেনগামী স্থলপথের মাঝখানের আসির পর্বতমালা অনিয়ন্ত্রিত রাখা যাবে না বলে বোঝা যায়। ইয়েমেন অভিযানে যাওয়া রেদিফ পাশার বাহিনী আবহায় প্রবেশ করে অঞ্চলটিকে সরাসরি অটোমান শাসনে আনে এবং আসির সানজাক গঠিত হয়। পার্বত্য ভূগোল ও ইদ্রিসি প্রভাবের কারণে এই কর্তৃত্ব কখনো পুরোপুরি জমেনি।", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["মিধহাত পাশার নাজদ অভিযান: আল-হাসায় অটোমান কর্তৃত্বের পুনঃপ্রতিষ্ঠা", "7db51461"], "d": ["বাগদাদের গভর্নর মিধহাত পাশা সৌদি পরিবারের অভ্যন্তরীণ সিংহাসন-দ্বন্দ্বের সুযোগ নিয়ে বসরা উপসাগরের পশ্চিম উপকূলে সৈন্য পাঠালেন এবং আল-হাসা অঞ্চল নাজদ সানজাক নামে বসরা প্রদেশের সঙ্গে যুক্ত করলেন। আবদুল্লাহ ইবনে ফয়সালকে মুতাসাররিফ নিযুক্ত করে অটোমান কর্তৃত্ব কাগজে-কলমে প্রতিষ্ঠিত হলো। অভিযান উপসাগরে ব্রিটিশ প্রভাব বিস্তার থামানোর উদ্দেশ্যে ছিল এবং একই বছর কাতারও অটোমান নিয়ন্ত্রণে আসার কারণ হলো।", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["সদরে আজম আলি পাশার মৃত্যু: তানজিমাত কর্মীদলের সমাপ্তি", "1cf0141c"], "d": ["ফুয়াদ পাশার 1869 সালের মৃত্যুর পর একা তানজিমাত নীতির ভার বহনকারী আলি পাশার মৃত্যুতে রাষ্ট্রের পররাষ্ট্রনীতি ত্রিশ বছর পরিচালনাকারী দক্ষ কূটনীতিক প্রজন্ম নিঃশেষ হলো। স্থলাভিষিক্ত মাহমুদ নেদিম পাশার রুশপন্থী ও খেয়ালি শাসন আবদুলআজিজের ব্যক্তিগত শাসন সুদৃঢ় করল। আলি পাশার মৃত্যুর পর পাঁচ বছরের মধ্যে অর্থব্যবস্থা দেউলিয়া হলো, বলকান বিদ্রোহ করল এবং রাজত্ব পরিবর্তন অনিবার্য হয়ে উঠল।", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["কাতারে অটোমান নিয়ন্ত্রণ প্রতিষ্ঠা", "3b453165"], "d": ["ব্রিটিশ চাপে থাকা শেখ কাসিম ইবনে সানির আমন্ত্রণে অটোমান বাহিনী কাতার উপদ্বীপে নামল এবং 1871 সালের শরতে অঞ্চলে অটোমান নিয়ন্ত্রণ নিশ্চিত হলো। কাতার নাজদ সানজাকের অধীন কাজা হিসেবে সংগঠিত হলো এবং শেখকে কায়মাকাম নিযুক্ত করা হলো। এই পদক্ষেপ মিধহাত পাশার উপসাগরে ব্রিটেনের বিরুদ্ধে পরিচালিত অগ্রবর্তী নীতির সবচেয়ে বাস্তব অর্জন; অটোমান পতাকা উপদ্বীপে 1913 সাল পর্যন্ত উড়ল।", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["তিউনিসের উত্তরাধিকার ফরমান — বেইত্ব মেহমেদ সাদিক পাশার বংশে", "1509ebb0"], "d": ["প্রুশিয়ার কাছে ফ্রান্সের পরাজয়ের সুযোগ নেওয়া তিউনিসের বে মেহমেদ সাদিক পাশা ইস্তানবুলে পাঠানো খায়রুদ্দিন পাশার উদ্যোগে জারি হওয়া ফরমানে তিউনিস সরাসরি ইস্তানবুলের অধীন থাকার শর্তে মেহমেদ সাদিক পাশা ও তাঁর বংশধরদের উত্তরাধিকার-পদ্ধতিতে দেওয়া হয়। সুলতানের অনুমতি ছাড়া যুদ্ধ ও শান্তি আলোচনা করা যাবে না, দেশের কোনো ভূমি অন্যকে দেওয়া যাবে না, অটোমানদের সৈন্য-দাবি পূরণ করতে হবে। ফ্রান্স ফরমান মানল না; দশ বছর পর তিউনিস দখল করল।", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["সানা দখল: ইয়েমেনে অটোমান কর্তৃত্বের পুনঃপ্রতিষ্ঠা", "978e20a0"], "d": ["সুয়েজ খাল খোলায় লোহিত সাগরের কৌশলগত মূল্য বাড়ায় বাবে-আলি ইয়েমেনে আহমেদ মুখতার পাশার নেতৃত্বে ফিরকা-ই ইহতিয়াতিয়্যে বাহিনী পাঠাল। সানা দখলের মাধ্যমে দুই শতাব্দী ধরে কার্যত হারানো অভ্যন্তরীণ ইয়েমেনে রাষ্ট্রীয় কর্তৃত্ব পুনঃস্থাপিত হলো এবং অঞ্চল প্রদেশে পরিণত করা হলো। তবে জায়দি ইমামদের সঙ্গে সংগ্রাম কখনো শেষ হয়নি; 1891, 1898 ও 1904 সালের বিদ্রোহ অটোমানদের সবচেয়ে ব্যয়বহুল ও দীর্ঘতম অভ্যন্তরীণ ফ্রন্ট গঠন করল। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: সানা, তাইজ।", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["হারজেগোভিনা বিদ্রোহের সূচনা: প্রাচ্য প্রশ্নের নতুন করে জ্বলে ওঠা", "571b18ec"], "d": ["ভারী কর ও আয়ান চাপের কারণে নেভেসিনের আশপাশের খ্রিস্টান কৃষকদের বিদ্রোহ অল্প সময়ে সমগ্র হারজেগোভিনায় ছড়াল এবং সার্বিয়া ও মন্টেনিগ্রো থেকে আসা স্বেচ্ছাসেবকদের দ্বারা পুষ্ট হলো। অস্ট্রিয়া ও রাশিয়ার সংস্কার চাপিয়ে দেওয়ার কারণ হওয়া বিদ্রোহ পরের বছর বুলগার অভ্যুত্থান এবং সার্ব-মন্টেনিগ্রো যুদ্ধ ঘোষণা ঘটাল। এভাবে 93 যুদ্ধ এবং বার্লিন চুক্তিতে বলকান হারানোর দিকে যাওয়া বড় শৃঙ্খলের প্রথম কড়া ভাঙল।", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["অটোমান অর্থব্যবস্থার দেউলিয়াত্ব: বৈদেশিক ঋণ পরিশোধ অর্ধেকে নামানো", "2cac2fa5"], "d": ["1854 সাল থেকে পরপর নেওয়া ঋণ, ক্রিমিয়া যুদ্ধের ব্যয়, প্রাসাদ নির্মাণ ও 1873-74 সালের আনাতোলিয়া দুর্ভিক্ষ বাজেট ঘাটতিকে পাঁচ মিলিয়ন লিরার বেশি খাদে পরিণত করল। মাহমুদ নেদিম পাশার সরকার ঋণের সুদ ও আসল পরিশোধ পাঁচ বছরের জন্য অর্ধেকে নামানো হবে ঘোষণা করে কার্যত মরাটোরিয়াম ঘোষণা করল। ইউরোপীয় শেয়ারবাজারে বড় প্রতিক্রিয়া সৃষ্টি করা এই সিদ্ধান্ত ছয় বছর পর মুহাররম ফরমান ও দুয়ুন-ই উমুমিয়্যে প্রশাসন প্রতিষ্ঠায় পরিণত প্রক্রিয়া শুরু করল।", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["পঞ্চম মুরাদের অপসারণ এবং দ্বিতীয় আবদুলহামিদের সিংহাসনারোহণ", "cffb2271"], "d": ["আবদুলআজিজের সিংহাসনচ্যুতির পর সিংহাসনে বসা পঞ্চম মুরাদ চাচার মৃত্যু ও চেরকেস হাসান ঘটনায় নাড়া খাওয়া মানসিক স্বাস্থ্যের কারণে দায়িত্ব পালনে অক্ষম হয়ে পড়লেন; তিরানব্বই দিনের রাজত্বের কেবল সাত দিনে তাঁর বিচারবোধ ঠিক ছিল। শেখুল ইসলামের ফতোয়ায় অপসারিত হয়ে ভাই দ্বিতীয় আবদুলহামিদ স্থলাভিষিক্ত হলেন। নতুন সুলতান মিধহাত পাশাকে সাংবিধানিক রাজতন্ত্র ঘোষণার প্রতিশ্রুতি দিয়ে সিংহাসনে উঠলেন; তেত্রিশ বছর স্থায়ী এক যুগ শুরু হচ্ছিল।", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["নৌঘাঁটি সম্মেলন: বড় শক্তিগুলোর বলকান সংস্কার চাপিয়ে দেওয়া", "b5006a2c"], "d": ["বলকান সংকট সমাধানে বড় শক্তিগুলোর ইস্তানবুলে সমবেত সম্মেলন বুলগেরিয়াকে দুই স্বায়ত্তশাসিত প্রদেশে বিভক্ত করা এবং বসনিয়া-হারজেগোভিনায় আন্তর্জাতিক নিয়ন্ত্রণে সংস্কার প্রয়োগ চাইল। বাবে-আলি সম্মেলন শুরুর দিনে কামান দেগে কানুন-ই এসাসি ঘোষণা জানিয়ে চাপিয়ে দেওয়া দাবিগুলো সাংবিধানিক সংস্কারে মোকাবিলার চেষ্টা করল। প্রতিনিধিরা এটিকে সময়ক্ষেপণ ভেবে 20 জানুয়ারি 1877 সালে ভেঙে গেল; চার মাস পর রাশিয়া যুদ্ধ ঘোষণা করল।", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["প্রথম মজলিস-ই মেবুসানের দলমাবাহচেতে উদ্বোধন", "429bb279"], "d": ["কানুন-ই এসাসি অনুযায়ী নির্বাচিত 115 জন সদস্য 19 মার্চ 1877 সালে দলমাবাহচে প্রাসাদের মুআয়েদে হলে অনুষ্ঠানের মাধ্যমে প্রথমবার সমবেত হলেন; এভাবে অটোমান ইতিহাসে প্রতিনিধিত্বমূলক সংসদের যুগ শুরু হলো। মুসলিম ও অমুসলিম সদস্যরা সরকারকে কঠোরভাবে জেরা করলেন, যুদ্ধ পরিচালনা এবং মন্ত্রীদের দায়িত্ব নিয়ে আলোচনা করলেন। এই সাহসী বিরোধিতা সংসদের আয়ু সংক্ষিপ্ত করার প্রধান কারণ হবে।", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["প্লেভেন প্রতিরক্ষার সূচনা: গাজি ওসমান পাশার প্রতিরোধ", "0e04a878"], "d": ["93 যুদ্ধে দানিয়ুব পার হওয়া রুশ সেনাবাহিনীর ইস্তানবুলের পথ আটকাতে ভিদিন থেকে প্লেভেনে অগ্রসর ওসমান পাশা শহরটিকে দুর্গ ও পরিখা দিয়ে সুরক্ষিত করে পাঁচ মাসের কিংবদন্তি প্রতিরক্ষা শুরু করলেন। পরপর তিনটি বড় রুশ-রোমানীয় আক্রমণ ভারী ক্ষতিসহ প্রতিহত হলো এবং জার দ্বিতীয় আলেকজান্ডারের নিজে পরিচালিত সেনাবাহিনী অবরোধে বাধ্য হলো। প্লেভেন অটোমান সেনাবাহিনীর ঊনবিংশ শতাব্দীর সবচেয়ে উজ্জ্বল প্রতিরক্ষা সাফল্য হিসেবে ইতিহাসে স্থান পেল।", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["প্লেভেনের পতন: দানিয়ুব ফ্রন্টের ভাঙন", "185e7602"], "d": ["পাঁচ মাসের অবরোধে রসদ ফুরিয়ে যাওয়া ওসমান পাশা ভিদ নদীর পথে বেরিয়ে আক্রমণে নামলেন; আহত ও বন্দি হওয়ায় শহর আত্মসমর্পণ করল। রুশ সেনাপতিরা বন্দি পাশাকে তরবারি ফিরিয়ে দিয়ে অভিবাদন জানালেন এবং ওসমান পাশাকে 'গাজি' উপাধি দেওয়া হলো। প্লেভেনের পতনে রুশ সেনাবাহিনীর পথ খুলল; দুই মাসের মধ্যে সোফিয়া, ফিলিবে ও এডির্ন পড়ল, রুশ অগ্রবর্তী দল ইয়েশিলকয়ে পৌঁছাল।", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["রুশ বাহিনীর সোফিয়া দখল", "ef369d22"], "d": ["প্লেভেনের পতনের পর বলকান পার হওয়া রুশ সেনাবাহিনী অরক্ষিত সোফিয়ায় প্রবেশ করল। শহর আর কখনো অটোমান শাসনে ফিরবে না, 1878 সালের শেষে স্বায়ত্তশাসিত বুলগেরিয়া প্রিন্সিপালিটির, 1879 সালে প্রকৃত রাজধানী হবে। মানচিত্রে সোফিয়া এই তারিখ থেকে অটোমান সরাসরি শাসন থেকে বেরিয়ে সাময়িক রুশ দখলে, এর পর স্বায়ত্তশাসিত বুলগার প্রশাসনে যায়।", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["এডির্ন যুদ্ধবিরতি: 93 যুদ্ধে অস্ত্র নীরব", "1f899180"], "d": ["সোফিয়া, ফিলিবে ও এডির্নের পরপর পতন এবং রুশ সেনাবাহিনী মারমারা উপকূলে পৌঁছানোয় বাবে-আলি যুদ্ধবিরতি চাইতে বাধ্য হলো। এডির্নে স্বাক্ষরিত যুদ্ধবিরতি বুলগেরিয়াকে স্বায়ত্তশাসন, মন্টেনিগ্রো-সার্বিয়া-রোমানিয়ার স্বাধীনতা এবং ভারী যুদ্ধক্ষতিপূরণের মতো প্রাথমিক শান্তি শর্ত অটোমানদের দিয়ে মানাল। এই শর্ত এক মাস পর আয়াসতেফানোসে চুক্তির পাঠে পরিণত হবে।", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["দ্বিতীয় আবদুলহামিদের মজলিস-ই মেবুসান অনির্দিষ্টকালের জন্য স্থগিত করা", "e770b540"], "d": ["যুদ্ধের বিপর্যয়ে পরিণতির জন্য সরকার ও প্রাসাদকে দায়ী করা সদস্যদের কঠোর সমালোচনায় দ্বিতীয় আবদুলহামিদ কানুন-ই এসাসির দেওয়া ক্ষমতার ভিত্তিতে সংসদ অনির্দিষ্টকালের জন্য স্থগিত করলেন। প্রায় এগারো মাস কাজ করা প্রথম অটোমান সংসদ এভাবে বন্ধ হলো এবং ত্রিশ বছর স্থায়ী স্বৈরাচার যুগ শুরু হলো। সংসদ কেবল 1908 সালের বিপ্লবের পর আবার বসতে পারবে।", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["আয়াসতেফানোস চুক্তি: বৃহৎ বুলগেরিয়া পরিকল্পনা", "2c7cc611"], "d": ["93 যুদ্ধ শেষ করা আয়াসতেফানোস চুক্তি এজিয়ান পর্যন্ত বিস্তৃত এবং ম্যাসিডোনিয়াকে অন্তর্ভুক্ত করা বিশাল স্বায়ত্তশাসিত বুলগেরিয়া গড়ছিল; সার্বিয়া, মন্টেনিগ্রো ও রোমানিয়ার স্বাধীনতা স্বীকার করছিল; কার্স, আর্দাহান, বাতুম ও দোগুবায়েজিদ রাশিয়াকে ছেড়ে দিচ্ছিল এবং পরিশোধ অসম্ভব যুদ্ধক্ষতিপূরণ চাপাচ্ছিল। রাশিয়াকে ভূমধ্যসাগরে নামানো এই পাঠ ব্রিটেন ও অস্ট্রিয়ার তীব্র প্রতিক্রিয়া ডেকে আনল। কার্যকর না হয়ে চার মাসের মধ্যে বার্লিন কংগ্রেসে নতুন করে সাজানো হলো; তবু অটোমান রুমেলিয়ার সমাপ্তি ঘোষণাকারী দলিল হিসেবে রয়ে গেল।", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["কার্স, আর্দাহান ও বাতুম রাশিয়াকে ছেড়ে দেওয়া — এলভিয়ে-ই সেলাসে", "99bdfad2"], "d": ["বার্লিন চুক্তিতে অটোমান রাষ্ট্র যুদ্ধক্ষতিপূরণের একাংশের বিনিময়ে কার্স, আর্দাহান ও বাতুম রাশিয়াকে ছেড়ে দেয়; আয়াস্তেফানোসে রাশিয়াকে দেওয়া দোগুবায়াজিত ও এলেশকিরত উপত্যকা অটোমানদের হাতে থেকে যায়। বাতুম মুক্ত বন্দর হিসেবে দেওয়া হলেও এই মর্যাদা কেবল 1886 পর্যন্ত টিকে। রুশরা কার্সকে কেন্দ্র তিফলিস এমন ট্রান্সককেশীয় গভর্নর-জেনারেলের অধীন প্রদেশ করে; এলভিয়ে-ই সেলাসে থেকে সংখ্যায় 100.000 পর্যন্ত জনগোষ্ঠী এরজুরুমের দিকে দেশান্তরে বাধ্য হয়। একই চুক্তিতে দক্ষিণ বেসারাবিয়া (কিলিয়া, কাহুল, বলগ্রাদ) রোমানিয়া থেকে রাশিয়াকে ফিরিয়ে দেওয়া হয়।", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["বসনিয়া-হারজেগোভিনা ও ইয়েনিপাজারের অস্ট্রিয়া-হাঙ্গেরি কর্তৃক দখল", "e5f901df"], "d": ["বার্লিন চুক্তির দেওয়া অধিকারের ভিত্তিতে অস্ট্রিয়া-হাঙ্গেরির সেনাবাহিনী বসনিয়ায় প্রবেশ করল; অটোমান সরকার প্রতিরোধ না করতে সম্মত হলেও সারাজেভো ও মোস্তারের স্থানীয় মুসলিম-অর্থোডক্স জনগণ অস্ত্র হাতে নিয়ে তিন মাস কঠোর প্রতিরোধ দেখাল। দখল কেবল 20 অক্টোবর 1878 সালে সম্পন্ন হতে পারল। সুলতানের আইনি সার্বভৌমত্ব 1908 পর্যন্ত কাগজে চলল, তবে চার শতাব্দীর অটোমান বসনিয়া কার্যত হাতছাড়া হলো এবং বড় মুসলিম অভিবাসন ঢেউ শুরু হলো। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: বানা লুকা।", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["মুহাররম ফরমান এবং দুয়ুন-ই উমুমিয়্যে প্রশাসনের প্রতিষ্ঠা", "02b7cc03"], "d": ["1875 সালের দেউলিয়াত্বের পর পাওনাদার রাষ্ট্রগুলোর প্রতিনিধিদের সঙ্গে চালানো আলোচনা 28 মুহাররম 1299 (20 ডিসেম্বর 1881) তারিখের ফরমানে পরিণতি পেল: ঋণের আসল অর্ধেকের বেশি কমানো হলো, বিনিময়ে লবণ, তামাক, রেশম, স্ট্যাম্প ও মাছের শুল্কের মতো সবচেয়ে উৎপাদনশীল আয়খাত সরাসরি পাওনাদারদের পরিচালিত দুয়ুন-ই উমুমিয়্যে প্রশাসনের হাতে ছাড়া হলো। হাজার হাজার কর্মকর্তা নিয়োগকারী এই প্রশাসন রাষ্ট্রের ভেতরে আলাদা অর্থ সংগঠনে পরিণত হলো। অটোমান আর্থিক স্বাধীনতার কার্যত শেষ হওয়ার তারিখ বলে মানা হয়।", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["সাওয়াকিন — মাহদির হাতে না পড়া একমাত্র বন্দর", "5a37b198"], "d": ["1884 সালের ফেব্রুয়ারি থেকে সাওয়াকিন বাদে সমগ্র পূর্ব সুদান অঞ্চল মুহাম্মদ আহমদ আল-মাহদির কর্তৃত্বে গেলেও বন্দর জেনারেল গ্রাহামের নেতৃত্বাধীন তিন ব্যাটালিয়ন ব্রিটিশ বাহিনীর সামরিক সুরক্ষায় টিকে রইল। এটি প্রকৃত ও আইনি অবস্থা আলাদা হয়ে যাওয়ার এক যুগের সূচনা: উপকূল প্রকৃতপক্ষে ব্রিটিশ সামরিক নিয়ন্ত্রণে থাকলেও প্রশাসনিক বন্ধন 1885 সালে মিসর থেকে নিয়ে সরাসরি ইয়েমেন প্রদেশের, অর্থাৎ বাবে-আলির সঙ্গে যুক্ত করা হবে — সেই ব্যবস্থা 1888 সালে ফ্রান্সের জেইলা দখলে শেষ হওয়া পর্যন্ত চলল।", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["মিধহাত পাশার তায়েফের কারাগারে হত্যা", "f4562261"], "d": ["কানুন-ই এসাসির স্থপতি এবং প্রথম সাংবিধানিক যুগের প্রতীক মিধহাত পাশা আবদুলআজিজের মৃত্যু-সংক্রান্ত ইলদিজ আদালতে দোষী সাব্যস্ত হয়ে মৃত্যুদণ্ড নির্বাসনে পরিবর্তিত হয়ে তায়েফে প্রেরিত হয়েছিলেন। TDV নথি অনুযায়ী 7-8 মে 1884 রাতে নিজ কক্ষে শ্বাসরোধে নিহত হলেন, সরকারি কারণ 'শিরপেঞ্জে' রোগ বলে ঘোষণা করা হলো। তাঁর মৃত্যু দ্বিতীয় আবদুলহামিদের আমলে সাংবিধানিক বিরোধিতা শুদ্ধির প্রতীকে পরিণত হলো।", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["হায়দারপাশা-আঙ্কারা রেলপথের ছাড়পত্র জার্মানদের দেওয়া", "5705b163"], "d": ["সুলতানের ইরাদে হায়দারপাশা-আঙ্কারা লাইনের নির্মাণ ও পরিচালনার ছাড়পত্র ডয়চে ব্যাংকের প্রতিনিধি ব্যাংকার আলফ্রেড ফন কাউল্লাকে দেওয়া হলো এবং আনাতোলিয়া রেলওয়ে কোম্পানি গঠিত হলো। এই ছাড়পত্র অটোমান পরিবহন ও পররাষ্ট্রনীতিতে ব্রিটিশ-ফরাসি একচেটিয়া ভেঙে জার্মান প্রভাব প্রতিষ্ঠার মোড় হলো। এগারো বছর পর একই কোম্পানিকে দেওয়া বাগদাদ লাইনের ছাড়পত্রের সঙ্গে 'বার্লিন-বাগদাদ' স্বপ্ন জন্ম নেবে, যা প্রথম বিশ্বযুদ্ধের আগে বড় শক্তির প্রতিদ্বন্দ্বিতার প্রধান অক্ষগুলোর একটি হবে।", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["ইস্তানবুলে ইত্তিহাদ-ই উসমানি সমিতির প্রতিষ্ঠা", "b7187939"], "d": ["সামরিক চিকিৎসা বিদ্যালয়ের চার ছাত্র স্বৈরশাসনের বিরুদ্ধে গোপন সংগঠন হিসেবে ইত্তিহাদ-ই উসমানি সমিতি গঠন করলেন; এই কাঠামো অল্প সময়ে তরুণ তুর্কি আন্দোলনের সব বিরোধী উপাদানকে নিজের ছাদের নিচে আনা ইত্তিহাদ ও তারাক্কি সমিতিতে রূপ নিল। কোষভিত্তিক সংগঠন ইউরোপের নির্বাসিত এবং থেসালোনিকির অফিসারদের সঙ্গে মিলল। 1908 সালে দ্বিতীয় সাংবিধানিক যুগ ঘোষণা করাবে, 1913-এর পর রাষ্ট্র একা পরিচালনা করবে সেই কর্মীদল এই ছোট ছাত্র কোষ থেকে উঠে এল।", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["অটোমান ব্যাংক হামলা: তাশনাক কর্মীদের গালাতা অভিযান", "08b3095f"], "d": ["আর্মেনীয় তাশনাকসুত্যুন সংগঠনের একটি সশস্ত্র দল ইউরোপের দৃষ্টি আর্মেনীয় প্রশ্নের দিকে আকর্ষণের উদ্দেশ্যে গালাতার অটোমান ব্যাংকের সদর দপ্তর দখল করে জিম্মি করল এবং ভবন উড়িয়ে দেওয়ার হুমকি দিল। সংকট রাষ্ট্রদূতদের হস্তক্ষেপে কর্মীদের একটি জাহাজে দেশ থেকে বের করে দেওয়ার বিনিময়ে শেষ হলো। হামলার পরের দিনগুলোতে ইস্তানবুলে ঘটা রক্তাক্ত ঘটনা আর্মেনীয় প্রশ্নকে আন্তর্জাতিক হস্তক্ষেপের লিভারে পরিণত করার নির্ধারক হলো।", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["1897 অটোমান-গ্রিক যুদ্ধের সূচনা: থেসালি ফ্রন্ট", "33e490ab"], "d": ["গ্রিসের ক্রিটে নৌবহর ও সৈন্য নামানো এবং রুমেলিয়া সীমান্তে দস্যুদলের হামলায় অটোমান রাষ্ট্র যুদ্ধ ঘোষণা করল। জার্মান সংস্কার প্রতিনিধিদলের প্রশিক্ষিত অটোমান সেনাবাহিনী থেসালিতে দ্রুত এগিয়ে এক মাসে ইয়েনিশেহির, চাতালজা ও দোমেকে নিল; গ্রিক সেনাবাহিনী ছত্রভঙ্গ হলো। বড় শক্তিগুলোর হস্তক্ষেপে অর্জিত ভূমি ফেরত দেওয়া হলেও যুদ্ধ দ্বিতীয় আবদুলহামিদের আমলের একমাত্র নিশ্চিত সামরিক বিজয় হিসেবে রইল এবং ক্রিটের প্রকৃত হারানো ঠেকাতে পারল না।", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["কোনিয়া-বাগদাদ লাইনের ছাড়পত্র জার্মানদের দেওয়া", "fd8b6cbd"], "d": ["কাইজার দ্বিতীয় উইলহেলমের 1898 সালের ইস্তানবুল ও দামেস্ক সফরের পর আনাতোলিয়া রেলওয়ে কোম্পানিকে কোনিয়া থেকে বাগদাদ ও বসরা পর্যন্ত বিস্তৃত লাইনের প্রাথমিক ছাড়পত্র দেওয়া হলো। বাগদাদ রেলপথ প্রকল্প অটোমানদের জন্য আরব প্রদেশের ওপর কেন্দ্রীয় নিয়ন্ত্রণ শক্তিশালী করা, জার্মানির জন্য বসরা উপসাগরে পৌঁছানো বোঝাত। ব্রিটেন ও রাশিয়ার তীব্র বিরোধিতা করা এই প্রকল্প প্রথম বিশ্বযুদ্ধের দিকে যাওয়া সাম্রাজ্যবাদী প্রতিদ্বন্দ্বিতার সবচেয়ে বিতর্কিত ফাইলগুলোর একটি হলো।", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["দামেস্কে হিজাজ রেলপথ নির্মাণ শুরু", "62f58f68"], "d": ["দ্বিতীয় আবদুলহামিদের 2 মে 1900 তারিখের ইরাদে আদেশ করা লাইনের নির্মাণ 1 সেপ্টেম্বর 1900 সালে দামেস্কে আনুষ্ঠানিক অনুষ্ঠানে শুরু হলো। সম্পূর্ণ ইসলামি বিশ্ব থেকে সংগৃহীত অনুদান ও অটোমান প্রকৌশলী-সৈন্যদের শ্রমে নির্মিত প্রকল্প হাজিদের দামেস্ক-মদিনা যাত্রা চল্লিশ দিন থেকে পাঁচ দিনে নামিয়ে আনল। এটি খিলাফতের আধ্যাত্মিক কর্তৃত্ব দৃঢ় করা মর্যাদার কীর্তি এবং হিজাজের ওপর সামরিক নিয়ন্ত্রণ শক্তিশালী করা কৌশলগত বিনিয়োগ উভয়ই ছিল।", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["মুর্ৎসস্টেগ কর্মসূচি: ম্যাসিডোনিয়ায় আন্তর্জাতিক সংস্কার তত্ত্বাবধান", "4c7464da"], "d": ["ইলিন্দেন বিদ্রোহের পর রুশ ও অস্ট্রীয় সম্রাটরা মুর্ৎসস্টেগে মিলিত হয়ে ম্যাসিডোনিয়ার জন্য নতুন সংস্কার প্যাকেজ প্রস্তুত করলেন। কর্মসূচি অটোমান সাধারণ পরিদর্শকের পাশে দুজন বিদেশি বেসামরিক এজেন্ট বসানো, জেন্ডারমেরি ইউরোপীয় অফিসারদের দ্বারা পুনর্গঠন এবং প্রশাসনিক সীমানা জাতীয়তার ভিত্তিতে বদলানোর বিধান করছিল। বাবে-আলি সার্বভৌম অধিকার ক্ষুণ্ণ হওয়ার অজুহাতে প্রতিরোধ করলেও যৌথ চাপে মেনে নিতে বাধ্য হলো; কর্মসূচি তরুণ অফিসারদের মধ্যে ইত্তিহাদি সংগঠন ত্বরান্বিত করা মূল কারণগুলোর একটি হলো।", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["পঞ্চম মুরাদের মৃত্যু", "396659a7"], "d": ["1876 সালে প্রায় তিন মাস সিংহাসনে থেকে অপসারিত পঞ্চম মুরাদ, তাঁকে আবার সিংহাসনে বসানোর প্রচেষ্টার পর কড়া পাহারায় আঠাশ বছর বন্দি জীবন কাটান এবং বহুমূত্র রোগে মারা যান। ইয়েনিজামির জেদিদ হাভাতিন সমাধিতে মায়ের পাশে সমাহিত হন। তিনি সবচেয়ে কম সময় সিংহাসনে থাকা অটোমান সুলতান হিসেবে ইতিহাসে স্থান পান।", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["সানার ইমাম ইয়াহিয়ার কাছে হারানো", "e7f876cb"], "d": ["জায়দি ইমাম ইয়াহিয়া হামিদুদ্দিনের 1904 সালে শুরু করা অভ্যুত্থান 1905 সালের এপ্রিলে অবরোধের শেষে সানার পতনে পরিণতি পেল; শহর অটোমান শাসন থেকে বেরিয়ে গেল এবং অবরোধ জুড়ে অনাহার ও মহামারি দেখা দিল। ইয়েমেনের পার্বত্য ভূগোল, রসদ লাইনের দীর্ঘতা এবং জায়দি ইমামতের স্থানীয় বৈধতা এখানে অটোমান কর্তৃত্বকে শুরু থেকেই ভঙ্গুর করেছিল। শহর পাঁচ মাস পর ভারী ক্ষতির বিনিময়ে ফিরিয়ে নেওয়া হবে, তবে ইয়েমেন সমস্যা 1918 পর্যন্ত শেষ হবে না।", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["ইলদিজ হত্যাচেষ্টা: দ্বিতীয় আবদুলহামিদের ওপর বোমা হামলা", "1ee2e1a6"], "d": ["তাশনাকসুত্যুন সংগঠন জুমার সেলামলিক থেকে বের হওয়া সুলতানের গাড়ির কাছে টাইমার-বোমা লাগানো একটি ঘোড়ার গাড়ি বিস্ফোরণ ঘটিয়ে হত্যাচেষ্টা সংগঠিত করল; আবদুলহামিদের শেখুল ইসলামের সঙ্গে কথা বলে কয়েক মিনিট দেরি করা তাঁর প্রাণ বাঁচাল। বিস্ফোরণে ছাব্বিশজন নিহত এবং পঞ্চাশের বেশি আহত হলেন। ঘটনা সুলতানের নিরাপত্তা-আতঙ্ক এবং গুপ্তচর সংগঠননির্ভর স্বৈরশাসনকে আরও কঠোর করল; তেভফিক ফিকরেতের 'বির লাহজা-ই তাআহহুর' কবিতারও বিষয় হলো।", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["সানার পুনরুদ্ধার: ইমাম ইয়াহিয়ার বিদ্রোহ দমন", "dec3b8f9"], "d": ["1904 সালে জায়দি ইমাম ইয়াহিয়ার নেতৃত্বে শুরু হওয়া অভ্যুত্থান 1905 সালের এপ্রিলে সানার পতনে পরিণতি পেল এবং শহরে অনাহার ও মহামারি দেখা দিল। আলি রিজা পাশা ও আহমেদ ফেইজি পাশার নেতৃত্বাধীন সাহায্যকারী সেনাবাহিনী 15 জুলাই - 1 সেপ্টেম্বর 1905 সালের মধ্যে চালানো এবং তাইজের বাহিনীর সমর্থনে পরিচালিত অভিযানে ভারী ক্ষতির বিনিময়ে শহর ফিরিয়ে নিল এবং বিদ্রোহ দমন হলো। ইয়েমেন অভিযান অটোমান সেনাবাহিনীকে হাজার হাজার ক্ষতি ও বিপুল আর্থিক বোঝা দিল; রুমেলিয়ার অফিসারদের মধ্যে 'ইয়েমেনে নির্বাসনের' ভয় ইত্তিহাদি সংগঠনকে পুষ্ট করা অভিযোগের শীর্ষে ছিল।", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["দ্বিতীয় সাংবিধানিক যুগের প্রথম মজলিস-ই মেবুসানের সমাবেশ", "e7fd2716"], "d": ["ত্রিশ বছরের বিরতির পর দুই ধাপ নির্বাচনে গঠিত সংসদ 17 ডিসেম্বর 1908 সালে সুলতানের ভাষণে উদ্বোধিত হলো এবং সভাপতি নির্বাচিত হলেন তরুণ তুর্কি আন্দোলনের নেতা আহমেদ রিজা বে। তুর্কি, আরব, আলবেনীয়, গ্রিক, আর্মেনীয় ও ইহুদি সদস্যদের নিয়ে গঠিত সংসদ ছিল উসমানিয়াত আদর্শের শেষ বড় পরীক্ষা। তবে বুলগেরিয়ার স্বাধীনতা, বসনিয়ার সংযুক্তি এবং ক্রিটের গ্রিসের সঙ্গে যুক্ত হওয়ার ঘোষণা সংসদ খোলার আগেই এই আশাবাদকে ম্লান করেছিল।", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["হারেকেত অর্ডু এবং দ্বিতীয় আবদুলহামিদের অপসারণ: পঞ্চম মেহমেদ রেশাদের সিংহাসনারোহণ", "6a65a704"], "d": ["31 মার্চ ঘটনার কারণে থেসালোনিকি থেকে যাত্রা করা হারেকেত অর্ডু 22-23 এপ্রিল রাতে চার দিক থেকে ইস্তানবুলে প্রবেশ করল এবং 24 এপ্রিল ইলদিজ প্রাসাদ আত্মসমর্পণ করল। মজলিস-ই উমুমি-ই মিল্লি 27 এপ্রিল দ্বিতীয় আবদুলহামিদের অপসারণের সিদ্ধান্ত নিল; সুলতানকে থেসালোনিকিতে পাঠানো হলো, ভাই পঞ্চম মেহমেদ রেশাদ সিংহাসনে বসলেন। তেত্রিশ বছরের ব্যক্তিগত শাসন এভাবে শেষ হলো, তবে এর জায়গা নিল সুলতানের প্রতীকে পরিণত হওয়া এবং ইত্তিহাদ ও তারাক্কির সেনা সমর্থনে শাসনকারী নতুন যুগ।", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["আলবেনীয় বিদ্রোহ: কসোভো ও ইশকোদ্রায় সশস্ত্র প্রতিরোধ", "93ed30c6"], "d": ["ইত্তিহাদি সরকারের কেন্দ্রিকতাবাদী কর নীতি, অস্ত্র সংগ্রহ অভিযান এবং ল্যাটিন বর্ণমালা বিতর্ক সেই সময় পর্যন্ত রাষ্ট্রের প্রতি সবচেয়ে অনুগত গণ্য আলবেনীয় গোত্রগুলোকে বিদ্রোহী করল। মাহমুদ শেভকেত পাশার নেতৃত্বাধীন সেনাবাহিনী বিদ্রোহ কঠোরভাবে দমন করলেও অশান্তি 1911 ও 1912 সালে আবার জ্বলে উঠল। এই বিদ্রোহ অটোমান সেনাবাহিনীকে বলকান যুদ্ধের প্রাক্কালে ক্লান্ত করল এবং আলবেনীয় জাতীয় আন্দোলনের জন্মও ত্বরান্বিত করল।", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["উশি চুক্তি: ত্রিপোলি ও বেনগাজি ইতালিকে ছেড়ে দেওয়া", "4ffa1fd2"], "d": ["বলকান রাষ্ট্রগুলোর যুদ্ধ প্রস্তুতির বিপরীতে দুই ফ্রন্টের সংঘর্ষ সামলাতে না পারা বাবে-আলি সুইজারল্যান্ডের উশি শহরে ইতালির সঙ্গে গোপন শান্তি স্বাক্ষর করে ত্রিপোলি ও বেনগাজি ছেড়ে দিল। অটোমান রাষ্ট্র আফ্রিকায় শেষ ভূমি এভাবে হারাল; বিনিময়ে ইতালির দখলকৃত রোডস ও বারো দ্বীপপুঞ্জ ফেরত দেওয়ার প্রতিশ্রুতি থাকলেও তা কখনো পালিত হলো না। চুক্তি স্বাক্ষরের সময় বলকান যুদ্ধ আগেই শুরু হয়ে গেছে। এই ঘটনায় মুরজুক (ফেজ্জান), গাত, সেভহা, উবারি, তিরগান (Traghan), জাভিলা (Zawila) ও আল-কাত্রুন (ফেজ্জান (ত্রিপোলি প্রদেশের সানজাক)) ইতালীয় শাসনে গেল।", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["গ্রিসের লেমনস দখল", "9555af1d"], "d": ["প্রথম বলকান যুদ্ধে গ্রিক নৌবহর লেমনস দখল করে; দ্বীপের মুদ্রোস বন্দর চানাক্কালে প্রণালী অবরোধের ঘাঁটি হয়। দ্বীপটি লোজানে (24 জুলাই 1923) গ্রিসকে ছেড়ে দেওয়া হয়।", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["গ্রিসের থাসোস দখল", "6c03c7f0"], "d": ["প্রথম বলকান যুদ্ধে গ্রিস থাসোস ও সামোথ্রাকি দখল করে।", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["গ্রিসের সামোথ্রাকি দখল", "911e82a3"], "d": ["প্রথম বলকান যুদ্ধে গ্রিস সামোথ্রাকি দখল করে।", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["গ্রিসের লেসবস (মিদিল্লি) দখল", "6b2b07ba"], "d": ["গ্রিক নৌবহর লেসবসে (মিদিল্লি) অবতরণ করে; দ্বীপটি প্রথম বলকান যুদ্ধের শেষে গ্রিক সেনা ও নৌবহর দখল করে। লন্ডন সম্মেলন (মে 1913) পরিস্থিতি নিশ্চিত করে।", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["খিওসে গ্রিক অবতরণ", "901c6539"], "d": ["প্রথম বলকান যুদ্ধে 7 এপ্রিল 1912 বোমা হামলার শিকার খিওসে (সাকিজ) গ্রিকরা অবতরণ করে; অটোমান গ্যারিসন 3 জানুয়ারি 1913 আত্মসমর্পণ করে। দ্বীপটি লোজান চুক্তিতে (24 জুলাই 1923) গ্রিসকে ছেড়ে দেওয়া হয়।", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["সদরে আজম মাহমুদ শেভকেত পাশার ইস্তানবুলে হত্যা", "68e60e63"], "d": ["বাব-ই আলি হামলার পর সদরে আজম হওয়া মাহমুদ শেভকেত পাশা হারবিয়ে নাজারেতে যাওয়ার পথে চার্শিকাপির কাছে গাড়িতে গুলিবর্ষণে নিহত হলেন। ইত্তিহাদ ও তারাক্কি হত্যাকাণ্ড বিরোধীদের ওপর চাপিয়ে ব্যাপক গ্রেফতার ও মৃত্যুদণ্ডের ঢেউ শুরু করল, হুররিয়েত ভে ইতিলাফ ফিরকা কার্যত শুদ্ধ করা হলো। এই ঘটনার সঙ্গে ইত্তিহাদিদের এনভার-তালাত-জেমাল ত্রয়ীনির্ভর একদলীয় স্বৈরতন্ত্র নিশ্চিতভাবে প্রতিষ্ঠিত হলো।", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["দ্বিতীয় বলকান যুদ্ধের সূচনা: মিত্রদের ভাগাভাগির দ্বন্দ্ব", "48d088a2"], "d": ["লন্ডন চুক্তিতে অটোমানদের কাছ থেকে পাওয়া ভূমি ভাগ করতে না পারা বলকান মিত্ররা একে অপরের বিরুদ্ধে দাঁড়াল; বুলগেরিয়ার সার্ব ও গ্রিক অবস্থানে আক্রমণে দ্বিতীয় যুদ্ধ শুরু হলো। রোমানিয়া ও মন্টেনিগ্রোও বুলগেরিয়ার বিরুদ্ধে ফ্রন্টে নামলে বুলগার সেনাবাহিনী ভেঙে পড়ল। অটোমান রাষ্ট্র এই সুযোগ কাজে লাগিয়ে লন্ডন চুক্তির আঁকা মিদিয়ে-এনেজ রেখা পার হয়ে পূর্ব থ্রেস এডির্নসহ ফিরিয়ে নিল।", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["ইস্তানবুল চুক্তি: বুলগেরিয়ার সঙ্গে শান্তি এবং এডির্নের নিবন্ধন", "c8c18b2d"], "d": ["দ্বিতীয় বলকান যুদ্ধের পর অটোমান রাষ্ট্র ও বুলগেরিয়ার মধ্যে স্বাক্ষরিত চুক্তি মেরিচ নদীকে সীমান্ত মেনে এডির্ন, কিরকলারেলি, দিমেতোকা ও পূর্ব থ্রেস অটোমানদের হাতে থাকা আইনত নিবন্ধিত করল। দেদেআগাচ বুলগেরিয়ায় রাখা হলো (কাভালা অবশ্য 1912 সালের শরতে বুলগার দখলের পর 1913 সালের জুলাইয়ে গ্রিসের হাতে গিয়েছিল এবং 10 আগস্ট 1913 বুখারেস্ট চুক্তিতে গ্রিসে নিবন্ধিত হয়েছিল), দুই দেশের মধ্যে পারস্পরিক জনসংখ্যা বিনিময় এবং বুলগেরিয়ার মুসলিমদের অধিকার নির্ধারিত হলো। বলকান বিপর্যয় থেকে ফিরিয়ে নেওয়া যাওয়া একমাত্র ভূখণ্ডের নিশ্চয়তা এই পাঠ। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: গুমুলচিনা।", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["বজকাদা ও ইমরোজের পুনরুদ্ধার — এথেন্স চুক্তি", "ec084d09"], "d": ["বলকান যুদ্ধে গ্রিসের দখল করা উত্তর ইজিয়ান দ্বীপগুলোর মধ্যে প্রণালীর মুখ পাহারা দেওয়া বজকাদা ও ইমরোজ এথেন্স চুক্তির আলোচনায় চানাক্কালে প্রতিরক্ষার জন্য অপরিহার্য গণ্য হয়ে অটোমানদের ফেরত দেওয়া হয়। অন্য দ্বীপগুলো গ্রিসের হাতে থাকে। এই দুই দ্বীপ সাম্রাজ্যের ইজিয়ানে ধরে রাখা শেষ ভূমি হয় এবং লোজান চুক্তিতেও তুরস্কের থাকে।", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["এথেন্স চুক্তি: গ্রিসের সঙ্গে শান্তি এবং থেসালোনিকি-ইয়ানিনার হস্তান্তর", "8e94def7"], "d": ["অটোমান রাষ্ট্র ও গ্রিসের মধ্যে স্বাক্ষরিত চুক্তি বলকান যুদ্ধে হারানো থেসালোনিকি, ইয়ানিনা ও দক্ষিণ ম্যাসিডোনিয়ার গ্রিসের হাতে যাওয়া আনুষ্ঠানিকভাবে স্বীকার করল এবং ক্রিটের ওপর অটোমান অধিকার ত্যাগ করা হলো। গ্রিসে থাকা মুসলিমদের ধর্ম ও সম্পত্তির অধিকার, ওয়াকফের মর্যাদা ও মুফতি নিযুক্তি বিস্তারিতভাবে নির্ধারিত হলো। এজিয়ান দ্বীপগুলোর মর্যাদা অমীমাংসিত রেখে দুই রাষ্ট্রের মধ্যে স্থায়ী উত্তেজনার উৎস রয়ে গেল।", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["ইস্তানবুলে অটোমান-জার্মান গোপন মৈত্রী চুক্তি স্বাক্ষর", "0472efb3"], "d": ["ইউরোপে যুদ্ধ ফেটে পড়ার সঙ্গে সঙ্গে সদরে আজম সাইদ হালিম পাশার প্রাসাদে অটোমান রাষ্ট্র ও জার্মানির মধ্যে গোপন মৈত্রী চুক্তি স্বাক্ষরিত হলো; পাঠ রাশিয়া জার্মানির বিরুদ্ধে যুদ্ধে নামলে অটোমানরাও জার্মানির পাশে থাকার বিধান করছিল। চুক্তি মন্ত্রিসভা থেকেও গোপন রাখা হলো, কেবল চারজন জানতেন। তিন মাস পর কৃষ্ণ সাগর হামলায় অটোমান রাষ্ট্র কার্যত যুদ্ধে ঢুকে পড়বে, সাম্রাজ্যের ভাগ্য এই দলিলে বাঁধা পড়বে।", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["ক্যাপিটুলেশনের একতরফা বিলুপ্তি", "ec773d18"], "d": ["অটোমান সরকার ইউরোপ যুদ্ধে ব্যস্ত থাকা মুহূর্তে বিদেশিদের বিচারিক, আর্থিক ও শুল্ক সুবিধা দেওয়া ক্যাপিটুলেশন 1 অক্টোবর 1914 থেকে একতরফাভাবে বিলুপ্ত করার ঘোষণা দিল। চার শতাব্দীর এই সুবিধা ব্যবস্থার অবসান দেশের ভেতরে বড় স্বাধীনতা উচ্ছ্বাসে গৃহীত হলো এবং ইস্তানবুলে উদ্‌যাপন হলো। মিত্র জার্মানিসহ সব রাষ্ট্র সিদ্ধান্তের প্রতিবাদ করল; ক্যাপিটুলেশন কেবল 1923 সালে লোজানে চূড়ান্তভাবে ইতিহাসে বিলীন হবে।", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["কৃষ্ণ সাগর হামলা: অটোমান নৌবহরের রুশ বন্দরে গোলাবর্ষণ", "8ad4ef61"], "d": ["জার্মানি থেকে পালিয়ে অটোমান নৌবহরে 'কেনা' হিসেবে যোগ দেওয়া গোয়েবেন ও ব্রেসলাউ (ইয়াভুজ ও মিডিলি), অ্যাডমিরাল সুশনের নেতৃত্বে কৃষ্ণ সাগরে বেরিয়ে রুশ বন্দরে গোলাবর্ষণ করল এবং জাহাজ ডুবিয়ে দিল। এনভার পাশার মন্ত্রিসভা থেকে গোপনে দেওয়া এই আদেশ নিরপেক্ষতা কার্যত শেষ করল। এক সপ্তাহের মধ্যে রাশিয়া, ব্রিটেন ও ফ্রান্স যুদ্ধ ঘোষণা করল এবং অটোমান রাষ্ট্র অপ্রত্যাবর্তনীয়ভাবে প্রথম বিশ্বযুদ্ধে প্রবেশ করল।", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["ব্রিটিশ-ভারতীয় বাহিনীর ফাও দখল — ইরাক ফ্রন্টের সূচনা", "08663813"], "d": ["মিত্র শক্তির অটোমান রাষ্ট্রের বিরুদ্ধে যুদ্ধ ঘোষণার পরের সকালে বাহরাইনে অপেক্ষমাণ ব্রিটিশ-ভারতীয় ব্রিগেড শাত আল-আরবের মুখের ফাওয়ে নামল। ধ্বংসপ্রাপ্ত ফাও দুর্গের ছোট অটোমান বাহিনী যুদ্ধজাহাজের গোলার নিচে সরে গেল এবং ভারতের টেলিগ্রাফ লাইনের স্টেশন ব্রিটিশদের হাতে গেল। ইরাক ফ্রন্ট এভাবে খুলল।", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["জিহাদ-ই আকবর ঘোষণা: ফাতিহ মসজিদে জিহাদের ফতোয়া পাঠ", "2a6174e8"], "d": ["শেখুল ইসলাম উরগুপলু হায়রি এফেন্দির দেওয়া পাঁচটি ফতোয়া খলিফা-সুলতানের নামে ফাতিহ মসজিদে পাঠ করা হয়ে সব মুসলমানকে মিত্র শক্তির বিরুদ্ধে জিহাদে আহ্বান করা হলো। জার্মানির বড় আশা বাঁধা এই পদক্ষেপ ব্রিটিশ ও ফরাসি উপনিবেশের মুসলমানদের বিদ্রোহী করতে চেয়েছিল। প্রত্যাশিত সাধারণ অভ্যুত্থান ঘটল না; বরং দুই বছর পর মক্কার আমির শরিফ হুসাইনের ব্রিটিশ সমর্থনে বিদ্রোহ খিলাফতের রাজনৈতিক প্রভাবের সীমা বেদনাদায়কভাবে দেখাল।", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["কুর্নার ব্রিটিশদের কাছে আত্মসমর্পণ", "621d36b0"], "d": ["বসরার পতনের পর দজলা ও ফুরাতের মিলনস্থল কুর্নায় সরে যাওয়া বসরার গভর্নর সুবহি বের বাহিনী 4-8 ডিসেম্বরের সংঘর্ষের পর 9 ডিসেম্বর 1914 সকালে আত্মসমর্পণ করল।", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["মিসরকে ব্রিটিশ আশ্রয়ে নিয়ে সুলতানত্ব ঘোষণা", "55d4e520"], "d": ["অটোমান রাষ্ট্রের যুদ্ধে প্রবেশে ব্রিটেন 1882 সাল থেকে কার্যত দখলে রাখা মিসরকে আনুষ্ঠানিকভাবে নিজের আশ্রয়ে নেওয়ার ঘোষণা দিল; অটোমানদের প্রতি আনুগত্য বজায় রাখা খেদিভ আব্বাস হিলমি পাশাকে অপসারণ করে স্থলাভিষিক্ত করা হলো হুসাইন কামিলকে 'সুলতান' উপাধিতে। এভাবে 1517 সাল থেকে চলা আইনি অটোমান সার্বভৌমত্ব একতরফাভাবে শেষ করা হলো। বাবে-আলি সিদ্ধান্ত স্বীকার করল না এবং দুই মাস পর খাল অভিযানে মিসর ফিরিয়ে নিতে নামল।", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["সারিকামিশ অভিযান: ককেশাস ফ্রন্টে বিপর্যয়", "5cbde7f0"], "d": ["এনভার পাশা 1878 সালে হারানো কার্স-আর্দাহান-বাতুম ফিরিয়ে নিতে এবং ককেশাসের তুর্কিদের বিদ্রোহী করতে তৃতীয় সেনাবাহিনীকে শীতে আল্লাহু আকবর পর্বতের ওপর দিয়ে রুশ বাহিনীকে ঘিরে ফেলার কৌশলে ঠেলে দিলেন। অপর্যাপ্ত শীতকালীন সরঞ্জাম, ফুরিয়ে যাওয়া রসদ এবং মাইনাস ত্রিশ ডিগ্রিতে পৌঁছানো তুষারঝড়ে সেনাবাহিনী যুদ্ধে ঢোকার আগেই গলে গেল; হাজার হাজার সৈন্য জমে মারা গেল। অভিযান অটোমানদের যুদ্ধে সবচেয়ে ভারী বিপর্যয়গুলোর একটি হলো এবং পূর্ব ফ্রন্ট দুই বছর অরক্ষিত রাখল।", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["প্রথম খাল অভিযান: সিনাই মরুভূমি হয়ে সুয়েজে আক্রমণ", "02dd72f5"], "d": ["চতুর্থ সেনাবাহিনীর সেনাপতি জেমাল পাশা মিসরকে ব্রিটিশ দখল থেকে মুক্ত করা এবং সুয়েজ খাল চলাচলের জন্য বন্ধ করার উদ্দেশ্যে সিনাই মরুভূমি পার হওয়া আক্রমণ সংগঠিত করলেন। অটোমান বাহিনী খালের পূর্ব তীরে পৌঁছে কিছু অংশ ওপারে যেতে সফল হলেও ব্রিটিশ শ্রেষ্ঠত্ব এবং প্রত্যাশিত মিসরীয় গণঅভ্যুত্থান না ঘটায় পিছু হটল। অভিযান লক্ষ্যে পৌঁছাতে পারেনি, তবে ব্রিটেনকে মিসরে বড় বাহিনী রাখতে বাধ্য করে পরোক্ষ কৌশলগত প্রভাব সৃষ্টি করল।", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["সেভক ভে ইসকান (স্থানান্তর) আইন জারি", "2f2bc22c"], "d": ["ভ্যান বিদ্রোহ ও রুশ অগ্রগতির পর সরকার ফ্রন্টের পেছনে নিরাপত্তা ভঙ্গকারী মনে করা জনসংখ্যাকে সেনাপতিদের দ্বারা অন্য অঞ্চলে স্থানান্তরের অনুমতি দেওয়া সাময়িক আইন জারি করল এবং সুলতান 27 মে 1915 সালে অনুমোদন করলেন। প্রয়োগের ফলে আনাতোলিয়ার পূর্ব ও দক্ষিণ প্রদেশের আর্মেনীয় জনসংখ্যার বড় অংশ সিরিয়া ও মোসুলের দিকে পাঠানো হলো; স্থানান্তরকালে রোগ, ক্ষুধা ও আক্রমণে অনেক বড় প্রাণহানি ঘটল। সিদ্ধান্ত অটোমানদের শেষ বছরগুলোর সবচেয়ে ভারী এবং আজও সবচেয়ে বিতর্কিত বিষয় হয়ে রয়েছে।", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["অটোমান বাহিনী মুশ রুশ দখল থেকে ফিরিয়ে নিল", "fb1be113"], "d": ["মুশের প্রথম রুশ দখলের ছয় মাস পর অটোমান 16তম কোর বিতলিস-মুশ পাল্টা আক্রমণে শহরে প্রবেশ করে।", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["মুশ আবার রুশদের হাতে গেল", "43ad8a03"], "d": ["রুশ পাল্টা আক্রমণে অটোমান দল মুশ খালি করে; শহরটি 22-25 আগস্ট 1916-এর মধ্যে আবার রুশ দখলে যায় এবং 1917 সালের বসন্ত পর্যন্ত থাকে।", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["মুশ চূড়ান্তভাবে রুশ দখল থেকে মুক্ত", "f0e89703"], "d": ["প্রথম বিশ্বযুদ্ধে রুশ দখলে যাওয়া মুশ 1 মে 1917 অটোমান বাহিনীর হাতে চূড়ান্তভাবে পুনরুদ্ধার হয়।", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["দ্বিতীয় আবদুলহামিদের বেইলেরবেই প্রাসাদে মৃত্যু", "c9662582"], "d": ["1909 সালে সিংহাসনচ্যুত হয়ে প্রথমে থেসালোনিকিতে, বলকান যুদ্ধে শহর হারানোয় ইস্তানবুলে আনা এবং বেইলেরবেই প্রাসাদে গৃহবন্দি থাকা দ্বিতীয় আবদুলহামিদ মারা গেলেন। তেত্রিশ বছরের রাজত্বে রাষ্ট্রকে যুদ্ধ থেকে দূরে রেখে সময় কেনার চেষ্টা করলেও স্বৈরশাসনের জন্যও স্মরণীয় ছিলেন। জানাজা বিশাল জনসমাগমে দিভানইওলুর প্রথম মাহমুদ সমাধিতে সমাহিত হলো; তাঁর মৃত্যু তাঁর গড়া ব্যবস্থা আগেই ছিন্নভিন্ন হওয়া যুদ্ধ বছরে পড়ল।", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["ব্রেস্ট-লিতভস্ক চুক্তি: কার্স, আর্দাহান ও বাতুমের ফিরিয়ে নেওয়া", "da82636f"], "d": ["বলশেভিক বিপ্লবের পর যুদ্ধ থেকে সরে যাওয়া রাশিয়া ও কেন্দ্রীয় শক্তির মধ্যে স্বাক্ষরিত চুক্তি পূর্ব ফ্রন্ট বন্ধ করল এবং অটোমান রাষ্ট্রকে 1878 সালের বার্লিন চুক্তিতে হারানো কার্স, আর্দাহান ও বাতুম (এলভিয়ে-ই সেলাসে) ফিরিয়ে দিল। এটি অটোমান ইতিহাসে চল্লিশ বছর পর অর্জিত একমাত্র ভূমিলাভ ছিল। তবে মুদ্রোস যুদ্ধবিরতির পর অঞ্চল আবার হাতছাড়া হবে, চূড়ান্ত সমাধান আসবে 1921 সালের কার্স চুক্তিতে।", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["অটোমান বাহিনী আর্ভিনে প্রবেশ করল", "ca7d1778"], "d": ["25 মার্চ 1914 সালের সীমানা পেরোনো অটোমান বাহিনী, ব্রেস্ট-লিতোভস্ক যে এলভিয়ে-ই সেলাসের 1878-পূর্ব সীমানা ফিরিয়ে দিয়েছিল, সেদিকে অগ্রসর হয়ে 28 মার্চ 1918 আর্ভিনে প্রবেশ করে। আর্ভিন বাতুম সানজাকের অংশ হিসেবে 1878 সালে রাশিয়াকে ছেড়ে দেওয়া হয়েছিল; টিডিভি-র আর্ভিন মাদ্দে প্রত্যাবর্তন কেবল 'মার্চ 1918' লেখে, দিনটি মুস্তাফা সারি দেন।", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["আর্দাহান তুর্কি বাহিনীর হাতে এল", "7fd9e3db"], "d": ["এলভিয়ে-ই সেলাসে অভিযানে অটোমান বাহিনী আর্ভিনের পর 3 এপ্রিল 1918 আর্দাহান দখল করে; আর্দাহান 93 সালের যুদ্ধে 1877 সালে পতিত হয়ে 1878 সালে রাশিয়াকে ছেড়ে দেওয়া হয়েছিল। কার্স এক মাস পর, 25 এপ্রিল দখল হবে।", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["বাতুমের পুনর্দখল", "d37a1a0d"], "d": ["ব্রেস্ট-লিতোভস্ক চুক্তিতে রাশিয়া যুদ্ধ থেকে সরে গেলে পূর্বে অগ্রসর অটোমান বাহিনী 1878 সালে হারানো বাতুম বন্দর চল্লিশ বছর পর ফিরে পায়। কৃষ্ণ সাগরের পূর্ব প্রান্তের এই বন্দর ছিল বাকুর তেলের সমুদ্র-নির্গমন পথ। লাভটি মাত্র সাত মাস টেকে; মুদ্রোস যুদ্ধবিরতির পর অঞ্চলটি খালি করতে হবে।", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["এলভিয়ে-ই সেলাসে: কার্স অটোমান শাসনে এল", "02cbf0b3"], "d": ["ব্রেস্ট-লিতোভস্কে 1878 সালের বার্লিন চুক্তিতে হারানো তিন সানজাক — কার্স, আর্দাহান ও বাতুম — ফেরত দেওয়ার সিদ্ধান্ত হয়েছিল; অটোমান বাহিনী আর্দাহানে 3 এপ্রিল, বাতুমে 14 এপ্রিল, কার্সে 25 এপ্রিল 1918 প্রবেশ করে এবং বাস্তবে প্রশাসন প্রতিষ্ঠিত হয়। 'এলভিয়ে-ই সেলাসে' নামে পরিচিত এই ভূমি 93 সালের যুদ্ধ থেকে চলা ক্ষতির পূরণ বলে গণ্য হয়। যুদ্ধবিরতির পর আবার হাতছাড়া হবে, চূড়ান্তভাবে কেবল 1921 সালের কার্স চুক্তিতে তুরস্কের সঙ্গে যুক্ত হবে।", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["ইগদির দখল — আরাস উপত্যকায় অগ্রযাত্রা", "87ebf4d3"], "d": ["1918 সালের ফেব্রুয়ারিতে শুরু হওয়া অগ্রবর্তী অভিযানের অংশ হিসেবে তুর্কি বাহিনী আরাসের উত্তরে সারদারাবাদে আর্মেনীয় বাহিনীকে পরাজিত করে 20 মে 1918 ইগদির দখল করে। ইগদির এলভিয়ে-ই সেলাসের অন্তর্ভুক্ত ছিল না, এটি ইরেভান গুবের্নিয়ার সুরমালি কাজা ছিল; প্রায় 180 বছর পর অঞ্চলে প্রথম অটোমান প্রশাসন প্রতিষ্ঠিত হয়।", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["পঞ্চম মেহমেদ রেশাদের মৃত্যু এবং ষষ্ঠ মেহমেদ ভাহিদেদ্দিনের সিংহাসনারোহণ", "d302ba07"], "d": ["নয় বছরের রাজত্ব ত্রিপোলি, বলকান ও বিশ্বযুদ্ধে কাটানো পঞ্চম মেহমেদ রেশাদ যুদ্ধের সবচেয়ে সংকটময় সময়ে মারা গেলেন এবং ভাই ভাহিদেদ্দিন ষষ্ঠ মেহমেদ নামে সিংহাসনে বসলেন। নতুন সুলতান ইত্তিহাদি কর্মীদলের অভিভাবকত্ব থেকে মুক্তি পেতে চেষ্টা করলেন; চার মাস পর যুদ্ধবিরতি স্বাক্ষরের সময় সাম্রাজ্যের বিলুপ্তি পরিচালনা করতে বাধ্য হবেন। তিনি অটোমান রাজবংশের ছত্রিশতম এবং শেষ সুলতান।", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["মিত্র নৌবহরের ইস্তানবুলের সামনে আগমন এবং শহরের প্রকৃত দখল", "d10cb14d"], "d": ["মুদ্রোস যুদ্ধবিরতির পর ব্রিটিশ, ফরাসি, ইতালীয় ও গ্রিক জাহাজের ষাটের বেশি জাহাজের মিত্র নৌবহর দলমাবাহচের সামনে নোঙর ফেলল এবং ইস্তানবুল কার্যত দখলে এল। চারশো পঁয়ষট্টি বছর পর রাজধানী প্রথমবার বিদেশি সৈন্যদের নিয়ন্ত্রণে গেল। একই দিনে মুস্তাফা কামাল পাশার হায়দারপাশায় নেমে দৃশ্য দেখে বলা বলে প্রচলিত 'যেভাবে এসেছে সেভাবেই যাবে' কথাটি জাতীয় সংগ্রামের প্রতীকী বাক্যগুলোর একটি হবে।", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["আরাস অঞ্চলে পশ্চাদপসরণ: ইগদির খালি করা", "57572ab4"], "d": ["মুদ্রোস যুদ্ধবিরতির 1914 সীমানার পেছনে সরে যাওয়ার শর্ত অনুসারে ইয়াকুপ শেভকি পাশা 21 নভেম্বরের আদেশনামায় ব্রেস্ট-লিতোভস্ক সীমানার বাইরের বাহিনীকে 4 ডিসেম্বরের মধ্যে ফিরিয়ে আনার নির্দেশ দেন; ইগদির ও পার্শ্ববর্তী এলাকা এই তারিখে সম্পূর্ণ খালি করা হয়। এরপর আরাস-তুর্কি সরকার 1918 সালের ডিসেম্বরের শেষে আর্মেনীয়দের হাতে ভেঙে পড়ে।", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["ইংরেজরা আর্ভিনে বসল", "e2cb3153"], "d": ["30 অক্টোবর 1918 মুদ্রোস যুদ্ধবিরতি অটোমান বাহিনীকে 1914 সীমানার পেছনে সরার শর্ত দেওয়ায় আর্ভিন খালি করা হয় এবং 17 ডিসেম্বর 1918 ইংরেজরা তা দখল করে। টিডিভি-র আর্ভিন মাদ্দে অনুযায়ী ইংরেজ দখল 1920 সালের এপ্রিল পর্যন্ত চলে।", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["মুদ্রোসের পর বাতুমে ব্রিটিশ শাসন", "9dd768fc"], "d": ["30 অক্টোবর 1918 মুদ্রোস যুদ্ধবিরতি অনুযায়ী অটোমান রাষ্ট্র বাতুম থেকে সরে যেতে বাধ্য হয়; শহরটি 24 ডিসেম্বর 1918 ব্রিটিশ বাহিনীর দখলে যায়। 1918 সালের এপ্রিলে স্বতন্ত্র সানজাক কেন্দ্র করা বাতুম এই তারিখ থেকে 1920 সালের জুলাই পর্যন্ত ব্রিটিশ নিয়ন্ত্রণে থাকে।", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["আর্দাহান জর্জীয় কর্তৃত্বে গেল", "97cf47f6"], "d": ["মুদ্রোস-এর পর খালি করা আর্দাহান, দক্ষিণ-পশ্চিম ককেশীয় সরকার ইংরেজদের হাতে ভেঙে দেওয়ার দিনগুলোতে, 20 এপ্রিল 1919 জর্জীয় বাহিনী দখল করে। জর্জীয় কর্তৃত্ব 23 ফেব্রুয়ারি 1921 পর্যন্ত চলবে।", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["প্রেস্টন কার্সের শাসন আর্মেনীয় গভর্নরের হাতে তুলে দিলেন", "efa81cb0"], "d": ["12-13 এপ্রিল 1919 দক্ষিণ-পশ্চিম ককেশীয় সরকার ভেঙে দেওয়া ইংরেজ সেনাপতি প্রেস্টন 30 এপ্রিল 1919 অস্থায়ী শুরা সরকার বিলুপ্ত করে শহরের শাসন কার্সের গভর্নর করা আর্মেনীয় কারগানভের হাতে তুলে দেন; কার্সে আর্মেনীয় শাসনের যুগ শুরু হয় এবং কাজিম কারাবেকিরের 30 অক্টোবর 1920 বিজয় পর্যন্ত চলে।", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["এরজুরুম কংগ্রেস: পূর্ব প্রদেশের জাতীয় প্রতিরোধের সিদ্ধান্ত", "41ef0457"], "d": ["পূর্ব আনাতোলিয়া অধিকার রক্ষা সমিতির আহুত কংগ্রেস ব্রিটিশ চাপে স্থগিত হওয়ার পর ছাপ্পান্ন প্রতিনিধিসহ শুরু হলো এবং সভাপতি নির্বাচিত হলেন সামরিক পদ থেকে ইস্তফা দেওয়া মুস্তাফা কামাল পাশা। কংগ্রেস জাতীয় সীমানার মধ্যে মাতৃভূমি অখণ্ড, ম্যান্ডেট ও আশ্রয় গ্রহণযোগ্য নয়, সরকার ভেঙে পড়লে জাতি নিজের ভাগ্য নিজের হাতে নেবে ঘোষণা করল। এই সিদ্ধান্ত ছয় মাস পর মিসাক-ই মিল্লি পাঠের মূল গঠন করবে।", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["সিভাস কংগ্রেস: জাতীয় প্রতিরোধের এক ছাদের নিচে একত্রীকরণ", "0e9ad36b"], "d": ["4 সেপ্টেম্বর 1919 সালে সিভাস সুলতানিতে কাজ শুরু করা কংগ্রেস দেশের চারদিকের অধিকার রক্ষা সমিতিগুলোকে আনাতোলিয়া ও রুমেলিয়া অধিকার রক্ষা সমিতি নামে একত্র করল এবং একটি প্রতিনিধি পরিষদ (হেয়েত-ই তেমসিলিয়্যে) নির্বাচন করল। মার্কিন ম্যান্ডেট প্রস্তাব দীর্ঘ আলোচনার পর প্রত্যাখ্যাত হলো। 11 সেপ্টেম্বর প্রকাশিত ঘোষণাপত্রে জাতীয় সংগ্রাম একক কেন্দ্রের বৈধ রাজনৈতিক আন্দোলনে পরিণত হলো এবং ইস্তানবুল সরকারের সঙ্গে প্রকাশ্য ক্ষমতার সংগ্রাম শুরু হলো।", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["আমাসিয়া প্রোটোকল: ইস্তানবুল সরকারের সঙ্গে প্রতিনিধি পরিষদের আলোচনা", "40e6a6ab"], "d": ["দামাত ফেরিদের পতন এবং আলি রিজা পাশা সরকার গঠনের পর নৌমন্ত্রী সালিহ পাশাকে প্রতিনিধি পরিষদের সঙ্গে আলোচনার জন্য আমাসিয়ায় পাঠানো হলো। স্বাক্ষরিত প্রোটোকলে ইস্তানবুল সরকার আনাতোলিয়া আন্দোলনের অস্তিত্ব কার্যত স্বীকার করল; মজলিস-ই মেবুসান আহ্বান, নির্বাচন অবাধে করা এবং জাতীয় সীমানা রক্ষা মেনে নেওয়া হলো। এটি জাতীয় সংগ্রামের ইস্তানবুলের সামনে অর্জিত প্রথম আনুষ্ঠানিক রাজনৈতিক সাফল্য।", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["শেষ অটোমান সংসদে মিসাক-ই মিল্লি গ্রহণ", "6322865e"], "d": ["শেষ অটোমান মজলিস-ই মেবুসানে 121 সদস্যের স্বাক্ষরিত আহদ-ই মিল্লি পাঠ মুদ্রোস রেখার ভেতরে থাকা এবং মুসলিম-তুর্ক সংখ্যাগরিষ্ঠ ভূমির অবিভাজ্য অখণ্ডতা, আরব প্রদেশ ও পশ্চিম থ্রেসে গণভোট, ক্যাপিটুলেশন বিলুপ্তি এবং পূর্ণ রাজনৈতিক-আর্থিক স্বাধীনতা শর্ত করছিল। পাঠ 17 ফেব্রুয়ারি 1920 সালে সর্বসম্মতিক্রমে গৃহীত হয়ে বিশ্বে ঘোষিত হলো। এই ঘোষণা জাতীয় সংগ্রামের রাজনৈতিক কর্মসূচি হওয়ার পাশাপাশি লোজানে রক্ষা করা সীমানার মানচিত্রও ছিল; মিত্র শক্তির 16 মার্চ ইস্তানবুল আনুষ্ঠানিকভাবে দখলের সরাসরি কারণ হলো।", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["ইংরেজরা সরে যাওয়ার সময় আর্ভিন জর্জিয়ায় থেকে গেল", "6d086b06"], "d": ["টিডিভি-র আর্ভিন মাদ্দে অনুযায়ী ইংরেজ দখল 1920 সালের এপ্রিল মাস পর্যন্ত চলে; ইংরেজরা সরে যাওয়ার সময় শহরটি জর্জিয়াকে ছেড়ে যায়। আর্ভিন জর্জিয়ার হাতে তুর্কি গ্র্যান্ড ন্যাশনাল অ্যাসেম্বলির 23 ফেব্রুয়ারি 1921 আল্টিমেটাম পর্যন্ত ছিল।", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["বাতুম জর্জীয় প্রশাসনে হস্তান্তর", "6523d095"], "d": ["ইংরেজদের বাতুম আনুষ্ঠানিকভাবে জর্জীয়দের হস্তান্তর 7 জুলাই 1920 ঘটে (টিডিভি-র বাতুম মাদ্দে কেবল 'জুলাই 1920')। আঙ্কারা সরকার 25 জুলাই এই হস্তান্তরকে 'দখল' বলে প্রতিবাদ করে।", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["গুমরি চুক্তি: TBMM সরকারের প্রথম আন্তর্জাতিক চুক্তি", "9232c690"], "d": ["কাজিম কারাবেকিরের নেতৃত্বাধীন পূর্ব ফ্রন্ট সেনাবাহিনীর সারিকামিশ ও কার্স ফিরিয়ে নেওয়ায় আর্মেনিয়া শান্তি চাইল এবং গুমরিতে স্বাক্ষরিত চুক্তিতে সেভ্রকে স্বীকার না করা এবং পূর্বে ভূমি দাবি ত্যাগ মেনে নিল। আঙ্কারা সরকারের স্বাক্ষরিত এই প্রথম চুক্তি সেভ্রকে কার্যত প্রত্যাখ্যানকারী প্রথম আন্তর্জাতিক দলিল হলো এবং TBMM-এর আইনি স্বীকৃতির পথ খুলল। পূর্ব সীমান্ত এভাবে নিরাপদ হয়ে পশ্চিম ফ্রন্টে বাহিনী সরানো সম্ভব হলো।", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["প্রথম ইনোনু যুদ্ধ: নিয়মিত সেনাবাহিনীর প্রথম বিজয়", "4add3719"], "d": ["নবগঠিত নিয়মিত সেনাবাহিনী বুরসার দিক থেকে অগ্রসর গ্রিক বাহিনীকে ইনোনু অবস্থানে থামিয়ে পিছু হটতে বাধ্য করল। সামরিক দিক থেকে সীমিত মাপের এই সাফল্য রাজনৈতিক ফলাফলে ছিল অনেক বড়: আঙ্কারা সরকার লন্ডন সম্মেলনে আমন্ত্রিত হলো, সোভিয়েত রাশিয়ার সঙ্গে মস্কো চুক্তির পথ খুলল এবং তেশকিলাত-ই এসাসিয়্যে আইন গৃহীত হলো। দেশের ভেতরের জনমতে নিয়মিত সেনাবাহিনীর প্রতি আস্থাও এই বিজয়ে দৃঢ় হলো।", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["দ্বিতীয় ইনোনু যুদ্ধ: গ্রিক আক্রমণ দ্বিতীয়বার ভাঙা", "a974521c"], "d": ["লন্ডন সম্মেলনে ফল না পাওয়া গ্রিক সেনাবাহিনী বুরসা ও উশাকের দিক থেকে নতুন আক্রমণে নামলেও আবার ইনোনু শৈলশিরায় থামল এবং পিছু হটতে বাধ্য হলো। মুস্তাফা কামাল পাশার ইসমেত পাশাকে পাঠানো 'আপনারা সেখানে কেবল শত্রুকে নয়, জাতির দুর্ভাগ্যকেও হারিয়েছেন' টেলিগ্রাম এই বিজয়ের পর লেখা হয়েছিল। যুদ্ধ জাতীয় সংগ্রামের আন্তর্জাতিক মর্যাদা বাড়াল এবং ইতালির আনাতোলিয়া থেকে সরে যাওয়া ত্বরান্বিত করল।", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["আঙ্কারা চুক্তি: ফ্রান্সের সঙ্গে শান্তি এবং দক্ষিণ ফ্রন্টের সমাপ্তি", "35fc32db"], "d": ["সাকারিয়া বিজয়ের পর ফ্রান্সের সঙ্গে আঙ্কারায় স্বাক্ষরিত চুক্তিতে দক্ষিণ ফ্রন্টের যুদ্ধ শেষ হলো; ফরাসি বাহিনী আদানা, আন্তেপ, মারাশ ও উরফাসহ চুকুরোভা ও দক্ষিণ-পূর্ব খালি করে সিরিয়া সীমান্তে সরে গেল। মিত্র শক্তির একটি এভাবে আঙ্কারা সরকারকে কার্যত স্বীকার করল এবং সেভ্র ফ্রন্টে প্রথম ফাটল ধরল। খালি করা অঞ্চল থেকে নেওয়া অস্ত্র এবং মুক্ত হওয়া বাহিনী মহান আক্রমণের প্রস্তুতিতে গুরুত্বপূর্ণ ভূমিকা রাখল।", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["মুদানিয়া যুদ্ধবিরতি: ইস্তানবুল ও প্রণালীর বিনা যুদ্ধে হস্তান্তর", "ac0d9baf"], "d": ["মহান আক্রমণের পর তুর্কি সেনাবাহিনী চানাক্কালে ও ইজমিতে ব্রিটিশ বাহিনীর মুখোমুখি হওয়ায় মুদানিয়ায় সমবেত সম্মেলন এগারো দিনের কঠিন দর কষাকষির পর যুদ্ধবিরতিতে পরিণতি পেল। পূর্ব থ্রেস মেরিচ পর্যন্ত পনেরো দিনের মধ্যে গ্রিস কর্তৃক খালি হয়ে তুর্কি প্রশাসনে হস্তান্তর এবং ইস্তানবুল ও প্রণালী শান্তি চুক্তির মাধ্যমে সমর্পণ মেনে নেওয়া হলো। এভাবে জাতীয় সংগ্রামের সশস্ত্র পর্ব একটি গুলিও না ছুড়ে অর্জিত কূটনৈতিক বিজয়ে শেষ হলো এবং লোজানের দরজা খুলল।", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["ষষ্ঠ মেহমেদ ভাহিদেদ্দিনের ইস্তানবুল ত্যাগ এবং আবদুলমেজিদ এফেন্দির খলিফা নির্বাচন", "8ab0e847"], "d": ["সালতানাত বিলুপ্তির পর অবস্থান বিতর্কিত হওয়া শেষ সুলতান ষষ্ঠ মেহমেদ ভাহিদেদ্দিন 17 নভেম্বর 1922 শুক্রবার সকালে ব্রিটিশ যুদ্ধজাহাজ মালায়ায় ইস্তানবুল ছেড়ে মাল্টায় গেলেন। TBMM দুই দিন পর, 19 নভেম্বর আবদুলমেজিদ এফেন্দিকে রাজনৈতিক ক্ষমতাহীন খলিফা হিসেবে নির্বাচিত করল। ছয়শো তেইশ বছরের অটোমান রাজবংশীয় শাসন এভাবে কার্যত শেষ হলো; খিলাফত আরও পনেরো মাস প্রতীকীভাবে চলবে। মাল্টা এবং পরে ইতালিতে যাওয়া ভাহিদেদ্দিন সান রেমোর ভিলা নোবেলে বসবাস করলেন; কোনো মুসলিম দেশে গ্রহণের আবেদনে ফল পেলেন না এবং 16 মে 1926 সালে সেখানে সালতানাত ও খিলাফতের অধিকার কখনো ত্যাগ না করার কথা পুনরাবৃত্তি করে মারা গেলেন।", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["শেষ সুলতান ষষ্ঠ মেহমেদ ভাহিদেদ্দিনের সান রেমোতে মৃত্যু", "7149ed0e"], "d": ["ইস্তানবুল ত্যাগের পর ইতালির সান রেমো শহরে বসবাস করা শেষ অটোমান সুলতান মেহমেদ ভাহিদেদ্দিন, সালতানাত ও খিলাফতের অধিকার কখনো ত্যাগ করেননি বলে জানানো খিলাফত কংগ্রেসের (13 মে 1926) সমাবেশের খবর না পেয়েই 16 মে 1926 মারা যান। তিনি তীব্র অর্থকষ্টে ছিলেন; সান রেমোর ব্যবসায়ীদের কাছে তাঁর 60.000 লিরা ঋণ ছিল এবং মৃত্যুর খবর শুনে পাওনাদাররা তাঁর বাড়ির আসবাবে ক্রোক বসান।", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["কোনুরালপের বোলু অঞ্চল বিজয় — মুদুর্নু, কোনুরাপা ও বোলু", "e245cd27"], "d": ["ওরহান গাজির সেনাপতিদের একজন কোনুরালপ সাকারিয়ার পূর্বের পার্বত্য অঞ্চলের দিকে অগ্রসর হয়ে মুদুর্নু, কোনুরাপা ও বোলু অঞ্চলকে অটোমান শাসনে যুক্ত করেন; দুজচে সমভূমির জনপদ তাঁর নামে পরিচিত হয়। বিজয়ের সঠিক তারিখ অজানা; বর্ণনা আশিকপাশাজাদের বর্ণনার ওপর ভিত্তি করে। অঞ্চলটি তখন কান্দারোগুল্লারি ও বাইজেন্টাইনদের মধ্যে হাত বদল হওয়া সীমান্ত এলাকা ছিল; বিজয় অটোমানদের প্রথমবার কৃষ্ণ সাগরের পশ্চিম উপকূলের কাছাকাছি আনে। আঙ্কারার যুদ্ধের পর অঞ্চলটি আবার কান্দারোগুল্লারির হাতে যাবে, তবে বিজেতার আমলে চূড়ান্তভাবে ফিরে পাওয়া হবে।", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["মারমারার দক্ষিণের বাইজেন্টাইন জনপদ দখল — মিহালিচ, কিরমাস্তি, গোলিয়াজি", "9c61b8d4"], "d": ["নিকাইয়া ও ইজমিত দখলের পর বুরসা সমভূমির পশ্চিমে বাইজেন্টাইনদের হাতে থাকা জনপদগুলো একে একে অটোমান শাসনে আসে। উলুআবাত হ্রদের চারপাশের গোলিয়াজি, সুসুরলুক নদীর তীরের কিরমাস্তি ও মিহালিচ মারমারার দক্ষিণ উপকূলকে কারেসি ভূমির সঙ্গে যুক্ত করা করিডর সম্পূর্ণ করে। এই জনপদগুলো দীর্ঘ অবরোধ ছাড়াই, চারপাশ কেটে দেওয়ায় আত্মসমর্পণ করে; অঞ্চলে বাইজেন্টাইন উপস্থিতি এভাবে গেমলিক উপসাগরে সংকুচিত হয়।", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["গর্দুস (করিন্থ) মোরা ডেসপোটেটের হাতে যাওয়া", "392495eb"], "d": ["1358 সাল থেকে ফ্লোরেন্সের আচ্চিয়াইয়োলি পরিবারের আখাইয়া প্রিন্সিপালিটির অধীন তিমার ছিল যে করিন্থ, তা 1395 সালে বাইজান্টিয়ামের মোরা ডেসপট থিওদোরোসের হাতে গেল। শহর এরপর অটোমান বিজয় পর্যন্ত ডেসপোটেটের শাসনে থাকলো।", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["হাজিএমিরোগুল্লারি বেইলিকের সংযুক্তি — অর্দু ও উনিয়ে", "c064f07f"], "d": ["বায়রাম বে অর্দু এলাকায় প্রতিষ্ঠিত এবং পুত্র হাজি এমির 1350-এর দশকে সম্প্রসারিত এই তুর্কমেন বেইলিক ছিল কেন্দ্র বর্তমান এস্কিপাজারে এমন ছোট কিন্তু কৌশলগত উপকূলীয় রাষ্ট্র: সামসুন ও ট্রাবজোনের মধ্যে একমাত্র স্বাধীন কর্তৃত্বক্ষেত্র। এমির সুলায়মান 1398 সালে ইলদিরিম বায়েজিদের জানিক অভিযানে আনুগত্য জানিয়েছিলেন, আঙ্কারার যুদ্ধের পর বেইলিক আবার স্বাধীন হয়। দ্বিতীয় মুরাদের আমলে তাচেদ্দিনোগুল্লারির বিলুপ্তির সমসময়ে বেইলিকের ভূমি সরাসরি অটোমান শাসনে যুক্ত হয় এবং কৃষ্ণ সাগর উপকূল সামসুন থেকে গিরেসুন পর্যন্ত এক হাতে একত্র হয়।", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["গর্দুসের (করিন্থ) বিজয়", "87a2bc59"], "d": ["ফাতিহের মোরা অভিযানে আক্রোকরিন্থ দুর্গ তিন মাস অবরুদ্ধ থাকলো এবং শেষে শান্তিপূর্ণভাবে হস্তগত হলো। মোরার দরজা গণ্য করিন্থ যোজক এভাবে অটোমানদের হাতে এলো।", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["মন্টেনিগ্রোর অটোমান শাসনে অন্তর্ভুক্তি — সেতিনিয়ে", "7fdb7cc8"], "d": ["জেতার শাসক ক্রনোইয়েভিচ রাজবংশ 1496 সালে কর্তৃত্ব ত্যাগ করলে ইশকোদ্রার পেছনের আঙিনা মন্টেনিগ্রোর পার্বত্য অঞ্চল সরাসরি অটোমান শাসনে নেওয়া হয় এবং প্রথমে আলাদা সানজাক, পরে ইশকোদ্রা সানজাকের অংশ হিসেবে সংগঠিত হয়। সেতিনিয়ে মঠ অঞ্চলের ধর্মীয় কেন্দ্র হিসেবে স্বস্থানে রাখা হয়। ভূগোলের কঠোরতার কারণে এখানকার শাসন সমভূমির মতো কঠোরভাবে কখনো চলেনি; দুই শতাব্দী পর একই মঠ থেকে জন্ম নেওয়া ভ্লাদিকা শাসন বাস্তব স্বাধীনতার বীজ হবে।", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["ইরাকাইন অভিযানে বায়েজিদ দুর্গের অটোমান কর্তৃত্ব স্বীকার", "f29e2e17"], "d": ["প্রধান উজির ইব্রাহিম পাশা ইরাকাইন অভিযানে বিংগোল এলাকায় এলে অঞ্চলের বহু কুর্দি গোত্রের সঙ্গে ভান, তোপরাকক্কালে, আভনিক ও বায়েজিদ দুর্গ অটোমান কর্তৃত্বে আসতে রাজি হয়। বায়েজিদ 1514 সালে ইয়াভুজের অভিযানে অটোমানদের সঙ্গে যুক্ত হয়েছিল, কিন্তু বাহিনী ফিরে গেলে সাফাভিরা অঞ্চল ফিরিয়ে নেয়।", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["তাবরিজের আবার সাফাভিদের হাতে যাওয়া — ইরাকাইন প্রত্যাবর্তন", "80b8b761"], "d": ["ইরাকাইন অভিযানে বাহিনী তাবরিজে প্রবেশ করেছিল, কিন্তু আসল লক্ষ্য বাগদাদ হওয়ায় শহরে স্থায়ী গ্যারিসন রাখা হয়নি। শীত বাগদাদে কাটানো বাহিনী পশ্চিমে ফেরার সময় শাহ তাহমাস্প খালি করা আজারবাইজানে আবার ঢোকেন এবং তাবরিজ ফিরিয়ে নেন। এটি ছিল অটোমান-সাফাভি যুদ্ধগুলোর পুনরাবৃত্ত ছাঁচ: তাবরিজ পাঁচবার দখল হয়, পাঁচবারই ধরে রাখা যায়নি; শহর কেবল 1585 সালে দীর্ঘমেয়াদি অটোমান গ্যারিসন পাবে।", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["ভান ও এরচিশ তাহমাস্পের হাতে পড়া (অটোমান অবস্থান 1534-35 সালে শেষ)", "cb93d561"], "d": ["1534 সালে ভানকে অটোমান কর্তৃত্বে দেওয়া অঞ্চলে উলামা পাশা ভান দুর্গে সাফাভি অবরোধে টিকে ছিলেন; দুর্গ সাফাভিদের হাতে যায়, এরচিশ অবরোধকারী সাফাভি বাহিনীও অটোমান সাহায্যে পিছু হটে। কানুনি আহলাতে পৌঁছালে (23 সেপ্টেম্বর 1535) ভান ইতিমধ্যে তাহমাস্পের হাতে। ভান 1548 পর্যন্ত সাফাভি থাকে।", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["বায়েজিদ সানজাকের সাফাভি কর্তৃত্বে যাওয়া (ভান ও এরচিশ 1535 সালেই সাফাভি ছিল)", "806a2cf1"], "d": ["অটোমান-সাফাভি সীমান্তের মাঝের বায়েজিদ সানজাক আবার ইরানের হাতে যায় (Kaya 2017 এটিকে 'ভান ও এরচিশসহ' বলে; তবে Karataş 2025 ও টিডিভি অনুযায়ী ভান ও এরচিশ 22 সেপ্টেম্বর 1535 সালেই সাফাভিতে ফিরেছিল — আগের মাদ্দে দেখুন); এই হাত বদলে সানজাকের কিছু স্থান বিধ্বস্ত হয়। সানজাক ষোড়শ শতকের শেষ চতুর্থাংশ পর্যন্ত দুই রাষ্ট্রের মধ্যে বহুবার হাত বদল হয়।", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["নাখচিভান অভিযানের সময় বায়েজিদ সানজাকের আবার অটোমানদের হাতে আসা", "cf0171fa"], "d": ["কানুনির তৃতীয় ইরান (নাখচিভান) অভিযানের সময় বায়েজিদ সানজাক আবার অটোমান শাসনে নেওয়া হয়। 1554 সালের অভিযানে বায়াজিত বাহিনীর জন্য গুরুত্বপূর্ণ ঘাঁটি হয়; সানজাক 1578 সালে চূড়ান্তভাবে অটোমান সার্বভৌমত্বে আসে।", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["শাহ আব্বাসের কাছে ইরেভান হারানো", "34413cf2"], "d": ["জেলালি বিদ্রোহ আনাতোলিয়াকে অচল করে রাখা বছরগুলোয় পূর্ব রণাঙ্গন অরক্ষিত থাকায় ইউরোপীয় ধাঁচে বাহিনী পুনর্গঠন করা শাহ আব্বাস আক্রমণে যান। 1583 সালে ফারহাদ পাশার নির্মিত ইরেভান দুর্গ সাত মাস অবরোধের পর আত্মসমর্পণ করে। ফারহাদ পাশা চুক্তিতে অর্জিত ককেশীয় রেখার প্রথম কড়া ছিঁড়ে যায়, পরবর্তী তিন বছরে পুরো দক্ষিণ ককেশাস হাতছাড়া হবে।", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["তিফলিস ও গাঞ্জা হারানো", "3fb51753"], "d": ["ইরেভানের পতনের পর সাফাভি বাহিনী কুর উপত্যকা ধরে এগিয়ে যায়; কারাবাখের কেন্দ্র গাঞ্জা ও জর্জিয়ার রাজধানী তিফলিস একের পর এক হাতছাড়া হয়। অটোমান রাষ্ট্র একই সময়ে অস্ট্রীয় রণাঙ্গনে তেরো বছরের দীর্ঘ যুদ্ধ চালাচ্ছিল, আনাতোলিয়ায় জেলালিদের সঙ্গে লড়ছিল; পূর্বে পাঠানোর মতো বাহিনী ছিল না। এভাবে 1590 সালের ফারহাদ পাশা চুক্তিতে গড়া বিস্তৃত ককেশীয় প্রদেশ-ব্যবস্থা বাস্তবে শেষ হয়।", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["শিরভান হারানো — শামাখি, বাকু ও দারবেন্দ", "81beab11"], "d": ["কাস্পিয়ান উপকূলের শিরভান প্রদেশ ওজদেমিরোগলু ওসমান পাশার 1578-1585 অভিযানে অর্জিত হয়ে রেশম বাণিজ্যের মূল উৎস হিসেবে অটোমান অর্থব্যবস্থায় উল্লেখযোগ্য আয় দিয়েছিল। শাহ আব্বাসের উত্তরমুখী অভিযান শামাখি, বাকু ও দারবেন্দ পরপর দখল করে প্রদেশটি বিলুপ্ত করে। ক্ষতি কেবল ভূমির ছিল না: ইরানি রেশমের অটোমান হয়ে ইউরোপে যাওয়ার পথও নিয়ন্ত্রণের বাইরে যায় এবং সাফাভি রাষ্ট্র রেশম ভারত মহাসাগর হয়ে বিক্রি শুরু করে।", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["তাইজ হারানো", "65f20d53"], "d": ["অটোমানরা 1038 (1629) সালে সানার কাসিমি শাসনে ছেড়ে দেওয়া ইয়েমেন কর্তৃত্বের সঙ্গে তাইজও ত্যাগ করে — জায়দি ইমামদের অভ্যন্তরীণ ইয়েমেন ফিরিয়ে নেওয়ার প্রক্রিয়ার প্রথম বড় পদক্ষেপ।", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["ইয়েমেন হারানো — কাসিমি ইমামদের কর্তৃত্ব", "49e83e3c"], "d": ["ইয়েমেন 1538 সাল থেকে অটোমান প্রদেশ ছিল; কিন্তু জায়দি ইমামদের প্রতিরোধ কখনো থামেনি। ইমাম কাসিমের শুরু করা বিদ্রোহ পুত্র আল-মুআয়্যিদ মুহাম্মদের আমলে পুরো দেশে ছড়ায় এবং অটোমান গ্যারিসন একের পর এক অবরুদ্ধ হয়। চতুর্থ মুরাদের বাগদাদ ও ইরেভানে মনোযোগ থাকা বছরগুলোয় সাহায্য পাঠানো যায়নি; তাইজ 1629 সালে হাতছাড়া হয়েছিল, মোখা এই পতনের শেষ পর্যায়ে 22 অক্টোবর 1635 খালি করা হয়। 1635 সালে সানা ও জাবিদের শেষ বাহিনীও ইয়েমেন খালি করে। এভাবে লোহিত সাগরের পূর্ব উপকূল দুইশত সাঁইত্রিশ বছর সাম্রাজ্যের বাইরে থাকে, কেবল 1872 সালে ফিরে পাওয়া যায়। লাহিজ (আল-হাওতা) টিডিভি ইসলাম বিশ্বকোষ অনুযায়ী 1635 পর্যন্ত অটোমানদের হাতে ছিল; সে তারিখ থেকে জায়দি ইমামরা প্রভাবশালী হন।", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["মোখা খালি করা", "c6b3061a"], "d": ["মুস্তাফা বে 10 জুমাদাল-উলা 1045 (22 অক্টোবর 1635) অবশিষ্ট বাহিনী ও অস্ত্র নিয়ে মোখা খালি করেন; এরপর ইমাম কাসিমের পুত্র হাসান ইবনে কাসিম জাবিদ ও মোখায় নিজের লোক নিযুক্ত করে তিহামা উপকূলেও কাসিমি নিয়ন্ত্রণ প্রতিষ্ঠা করেন।", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["লাহসা বানি খালিদ আমিরাতের কাছে হারানো", "a9b6131a"], "d": ["লাহসা ছিল 1550 সালে বসরা উপসাগরের পশ্চিম উপকূল পর্তুগালের জন্য বন্ধ রাখতে গঠিত প্রদেশ; কিন্তু ইস্তানবুল থেকে অনেক দূরে, একটিমাত্র মরুপথের প্রান্তে ছিল। ক্রিট অবরোধ সম্পদ শেষ করে দেওয়া বছরগুলোয় অঞ্চলের বানি খালিদ গোত্র বাররাক ইবনে গুরায়রের নেতৃত্বে অটোমান গ্যারিসন বের করে দিয়ে নিজেদের আমিরাত গড়ে। উপসাগরের পশ্চিম উপকূল দেড় শতাব্দী গোত্রীয় আমিরাতে থাকে; 1795 সালে সৌদিদের, 1871 সালে আবার অটোমানদের হাতে যাবে।", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["প্রেভেজা ও ভোনিৎসা ভেনিসের কাছে হারানো — এপিরাস উপকূলের উন্মুক্ত হওয়া", "1201204c"], "d": ["পবিত্র লিগে যোগ দেওয়া ভেনিস মোরিয়া অভিযান শুরুর আগে আম্ব্রাকিয়া উপসাগরের মুখ পাহারা দেওয়া দুই দুর্গ দখল করে: প্রেভেজা এবং বিপরীত তীরের ভোনিৎসা। একই গ্রীষ্মে আয়ামাভরাও (লেফকাদা) পতিত হয়েছিল। এই তিন ঘাঁটি নৌবহরকে আইওনীয় সাগর থেকে গ্রিসের অভ্যন্তরে নিরাপদে ঢোকানো সম্ভব করে এবং পরের বছর শুরু হওয়া মোরিয়া অভিযানের ঘাঁটি হয়। প্রেভেজা ও ভোনিৎসা পাসারোভিৎসেও ভেনিসের হাতে রাখা হয়; অটোমান শাসনে ফিরবে কেবল 1798 সালে।", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["সোলনোক হারানো — তিসা রেখার বিচ্ছিন্ন হওয়া", "51c2c8ef"], "d": ["উয়ভারের আগস্টে পতনের পর হাবসবুর্গ বাহিনী দক্ষিণে ঘুরে তিসা নদীর ওপর সেতুমুখ সোলনোক দখল করে। শহরটি ছিল বুদিন ও ট্রান্সিলভানিয়ার মধ্যে একমাত্র নিরাপদ পারাপার; এর হারানো মানে হাঙ্গেরির পূর্বার্ধের অটোমান দুর্গগুলো পরস্পর থেকে বিচ্ছিন্ন হওয়া। পরের বছর বুদিন অবরোধে রসদ-পথ কাটা পড়াটা নির্ধারক হয়।", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["মোদন ভেনিসের কাছে হারানো", "114c9cc0"], "d": ["মোরিয়া উপদ্বীপের দক্ষিণ-পশ্চিম প্রান্তের মোদন ছিল ভেনিসের তিন শতাব্দী আগে হারানো এবং 'রাষ্ট্রের দুই চোখের একটি' বলে অভিহিত বন্দর। কোরনের পতনের পর অবরুদ্ধ দুর্গ স্থল ও সমুদ্র থেকে একযোগে আঘাত করে আত্মসমর্পণে বাধ্য করা হয়। মোরোসিনির মোরিয়া অভিযান এভাবে উপদ্বীপের পুরো পশ্চিম উপকূল দখল করে এবং অভ্যন্তরের পথ খোলে।", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["পেচুই হারানো", "99d54cf4"], "d": ["বুদিনের সেপ্টেম্বরে পতনের পর হাবসবুর্গ বাহিনী দানিউবের পশ্চিমে দক্ষিণে নেমে কানুনি আমল থেকে অটোমান পেচুই দখল করে। গাজি কাসিম পাশা মসজিদের জন্য পরিচিত শহরটি বুদিন প্রদেশের সবচেয়ে উন্নত সানজাক কেন্দ্রগুলোর একটি ছিল। এর হারানো মোহাচ সমভূমিতে নামার পথ খোলা বোঝায়; পরের বছর দ্বিতীয় মোহাচ পরাজয় ঠিক এখানেই ঘটবে।", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["সেগেদিন হারানো", "9fbee1b2"], "d": ["তিসা ও মারোস নদীর সঙ্গমস্থলের সেগেদিন ছিল হাঙ্গেরীয় সমভূমির দক্ষিণ দ্বার এবং তেমেশভার প্রদেশে যাওয়ার পথ আটকে রাখত। বুদিন ও পেচুই একই শরতে পতনের পর অবরুদ্ধ দুর্গ অল্প সময়ে আত্মসমর্পণ করে। এক মৌসুমে তিন দুর্গের হারানো 1541 সাল থেকে প্রতিষ্ঠিত হাঙ্গেরিতে অটোমান প্রশাসনিক কাঠামো ভাঙতে শুরু করার লক্ষণ। অ্যাটলাস একই দিনে তিসা তীরের জেন্তাকেও অটোমান থেকে হাবসবুর্গ পক্ষে গেছে ধরে (জেন্তার নির্দিষ্ট আত্মসমর্পণ-দিন সূত্রে পড়া যায়নি, দিনটি সেগেদিন থেকে নেওয়া; টিডিভি zenta: 1686 অক্টোবর থেকে অটোমান ও হাবসবুর্গের নেতৃত্বাধীন মিত্রদের মধ্যে সংঘর্ষ শুরু হয় — ঘোষিত আনুমানিকতা)।", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["বালিয়াবাদ্রা (পাত্রাস) হারানো — মোরিয়ার উত্তর দ্বার", "b9cff63c"], "d": ["করিন্থ উপসাগরের মুখের বালিয়াবাদ্রা ছিল মোরিয়া ও রুমেলির মধ্যে পারাপার নিয়ন্ত্রণকারী বন্দর। ভেনিসীয় বাহিনী শহর দখলের পর উপসাগরের দুই তীরের দুর্গগুলোও একের পর এক পতিত হয় এবং উপদ্বীপ স্থল থেকে পুরোপুরি বিচ্ছিন্ন হয়। এই অভিযানের শেষে পুরো মোরিয়া ভেনিসে যায়; অঞ্চলটি 1715 পর্যন্ত 'Regno di Morea' নামে শাসিত হবে।", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["গর্দুসের (করিন্থ) ভেনিসকে ছেড়ে দেওয়া", "9a25b6b9"], "d": ["পাত্রার পতনের পর করিন্থ শান্তিপূর্ণভাবে ভেনিসীয়দের ছেড়ে দেওয়া হলো এবং মুসলিম অধিবাসীরা শহর ত্যাগ করলো। 1687 সালের আগস্টে মোরোসিনির বাহিনী এথেন্স অভিযানের জন্য করিন্থে জড়ো হচ্ছিল।", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["এগরি হারানো", "983391aa"], "d": ["এগরি 1596 সালে তৃতীয় মেহমেদের সরাসরি অংশগ্রহণে অভিযানে দখল হয়ে নিজ নামে প্রদেশের কেন্দ্র হয়েছিল। উত্তর হাঙ্গেরির এই শেষ বড় অটোমান দুর্গ দ্বিতীয় মোহাচ পরাজয়ের পর পুরোপুরি অবরুদ্ধ অবস্থায় এক বছর টিকে ছিল এবং ক্ষুধার কারণে আত্মসমর্পণ করে। এর হারানোর সঙ্গে অটোমান রাষ্ট্রের হাঙ্গেরিতে উত্তর পার্শ্ব সম্পূর্ণ বিলুপ্ত হয়।", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["ইস্তোলনি বেলগ্রেড (সেকেশফেহেরভার) হারানো — হাঙ্গেরীয় রাজাদের অভিষেক নগরী", "c6147255"], "d": ["হাঙ্গেরীয় রাজারা শতাব্দী ধরে যেখানে মুকুট পরেছেন ও সমাহিত হয়েছেন, সেই শহর 1543 সালে কানুনি দখল করেন এবং বুদিন প্রদেশের সবচেয়ে গুরুত্বপূর্ণ সানজাক কেন্দ্রগুলোর একটি হয়েছিল। বুদিনের পতনের প্রায় দুই বছর পর চারপাশ পুরোপুরি কেটে যাওয়া দুর্গ আত্মসমর্পণ করে। এই ক্ষতির সঙ্গে দানিউবের পশ্চিমে অটোমান উপস্থিতি সিরেম ও ওসিয়েক অঞ্চলে সংকুচিত হয়।", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["জিগেতভার হারানো", "834910a7"], "d": ["জিগেতভার ছিল আইনদাতা সুলতান সুলায়মানের তেরোতম ও শেষ অভিযানে 1566 সালে অবরোধ চলাকালে মৃত্যুবরণের দুর্গ; তাই অটোমান স্মৃতিতে প্রতীকী স্থান ছিল। একশ তেইশ বছর পর, চারপাশের সব দুর্গ পতিত হওয়ার পর জলাভূমিতে সুরক্ষিত দুর্গও আত্মসমর্পণ করে। কানুনির অভ্যন্তরীণ অঙ্গ যেখানে সমাহিত সেই সমাধি ও আশপাশের জনপদ হাবসবুর্গ শাসনে যাওয়ার পর ধ্বংস করা হয়। একই তারিখে অ্যাটলাসে অটোমান থেকে হাবসবুর্গে যাওয়া অন্য বসতি: বার্চ — জিগেতভারের আবি-মার্কেজ ধারা অনুসরণ করে (Bánlaky 0017/1449; ঘোষিত আনুমানিকতা)।", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["ভারাদ হারানো", "6cce360d"], "d": ["ভারাদ 1660 সালে কোপ্রুলু মেহমেদ পাশার দখল করা ও নিজ নামে প্রদেশের কেন্দ্র করা, ট্রান্সিলভানিয়ায় খোলা মূল দুর্গ ছিল। সালানকেমেন পরাজয়ের পর সম্পূর্ণ একা হয়ে পড়া দুর্গ প্রায় দুই বছরের অবরোধের পর ক্ষুধায় আত্মসমর্পণ করে। এর হারানোয় ট্রান্সিলভানিয়ার ওপর অটোমান প্রভাব বাস্তবে শেষ হয় এবং হাবসবুর্গ কর্তৃত্ব তিসার পূর্বে প্রতিষ্ঠিত হয়।", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["ইয়ানোভা হারানো — ট্রান্সিলভানিয়ার পথ বন্ধ", "4b5e30d8"], "d": ["ইয়ানোভা 1658 সালে দখল হওয়া এবং ভারাদ ও তেমেশভারের মধ্যে সংযোগ ধরে রাখা দুর্গ ছিল। ভারাদের পতনের পরপরই চারপাশ কেটে গেলে সেটিও হাতছাড়া হয়। এভাবে তেমেশভার প্রদেশ উত্তর থেকে সম্পূর্ণ বিচ্ছিন্ন হয় এবং কার্লোভিৎস পর্যন্ত অটোমানদের হাতে থাকা একমাত্র হাঙ্গেরীয় ভূমি হিসেবে টিকে থাকে।", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["মন্টেনিগ্রোয় ভ্লাদিকা শাসন প্রতিষ্ঠা — সেতিনিয়ের বাস্তব বিচ্ছেদ", "a924b778"], "d": ["পবিত্র লিগ যুদ্ধ বলকানে অটোমান নিয়ন্ত্রণ শিথিল করা বছরগুলোয় সেতিনিয়ে মঠের প্রধান মেট্রোপলিটন পদ পেত্রোভিচ পরিবারে পিতা থেকে পুত্রে বর্তানো পদে পরিণত হয় এবং অঞ্চল বাস্তবে আলাদা প্রশাসন লাভ করে। পর্বতের দুর্গমতার কারণে এই ভ্লাদিকাত্ব দুই শতাব্দী পূর্ণ স্বাধীনও নয়, পূর্ণ অধীনও নয় অবস্থায় টিকে ছিল; আইনত স্বাধীনতা কেবল 1878 সালের বার্লিন চুক্তিতে স্বীকৃত হবে।", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["গর্দুসের (করিন্থ) পুনর্দখল", "26f53e3a"], "d": ["দামাদ আলী পাশার মোরা অভিযানের প্রথম বড় বিরতিস্থল করিন্থ হলো; অটোমানরা 1715 সালের জুনে শহর ভেনিসীয়দের কাছ থেকে ফিরিয়ে নিল এবং এখান থেকে উপদ্বীপের বাকি অংশে অগ্রসর হলো।", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["নাদিরের আক্রমণ: তাবরিজ, নাখচিভান, হামাদান, কেরমানশাহ, মারাগা ও কাসর-ই শিরিনের হারানো", "d95efd59"], "d": ["সাফাভি রাষ্ট্রের পতনের সুযোগে 1723-1727-এর মধ্যে নেওয়া পশ্চিম ইরানের শহরগুলো ইরানে বাস্তব ক্ষমতা দখলকারী নাদির খানের আক্রমণে একে একে হাতছাড়া হয়। আজারবাইজানে আর্দাবিল ও হালহালও নাদিরের হাতে যায়। হামাদান, কেরমানশাহ ও কাসর-ই শিরিনের হারানো ইস্তানবুলে ভারী প্রতিক্রিয়া সৃষ্টি করে; বাহিনীর অভিযানে না গিয়ে উস্কুদারে অপেক্ষা করা এবং ক্ষতি ধামাচাপা দেওয়ার চেষ্টা ছয় সপ্তাহ পর ফেটে পড়া পাত্রোনা হালিল বিদ্রোহের প্রত্যক্ষ কারণগুলোর একটি হয়। অ্যাটলাস হয়-এর ধারা অনুসরণকারী কোতুরকেও এই দিনে অটোমান থেকে সাফাভিতে গেছে ধরে (Uluerler 2015, Turkish Studies 10/5, পৃ. 6; কোতুরের নির্দিষ্ট দিন সূত্রে নেই — ঘোষিত আনুমানিকতা)।", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["বাগাভার্দ (আরপাচায়) বিপর্যয় — নাদির খানের হাতে ককেশাস হারানো", "4262f54c"], "d": ["সাফাভি রাষ্ট্রের পতনের সুযোগে 1723-1725 সালে দখল করা ককেশাস প্রদেশগুলো দশ বছর ধরে রাখা গেল। ইরানে প্রকৃত ক্ষমতা দখলকারী নাদির খান ইরেভানের কাছে বাগাভার্দে অটোমান বাহিনীকে ভারী পরাজয়ে ফেলেন; সেরদার আবদুল্লাহ কোপরুলু পাশা যুদ্ধক্ষেত্রে প্রাণ হারান। বিপর্যয়ের পর ইরেভান, তিফলিস, গাঞ্জা ও শিরওয়ান কয়েক মাসের মধ্যে খালি করা হলো। পূর্ব সীমান্ত 1746 সালে নিশ্চিত হওয়ার মতো করে 1639 সালের কাসর-ই শিরিন রেখায় ফিরে গেল।", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["বেন্ডারের রুশদের হাতে হারানো", "0daca453"], "d": ["কার্তাল সমভূমির বিপর্যয়ের পর অটোমান বাহিনী দানিউবের দক্ষিণে সরে গিয়েছিল; বোগদান ও ওজির মাঝের দুর্গগুলো একা পড়ে গিয়েছিল। দনিস্টার নদীর পারঘাট রক্ষাকারী বেন্ডার দুই মাসের অবরোধের পর আক্রমণে দখল হলো; শহর লুণ্ঠিত হলো। দুর্গ হারানোয় উত্তর কৃষ্ণসাগর প্রতিরক্ষা রেখার মাঝের সংযোগ ছিঁড়ে গেল, এরপর আক্কেরমান ও কিলিয়াও পতন ঘটল। কুচুক কায়নারজায় বেন্ডার ফেরত দেওয়া হবে, কিন্তু 1806 সালে আবার হারাতে হবে।", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["কুয়েতে সাবাহ আমিরাতের অটোমান আশ্রয়ে আসা", "3584dba0"], "d": ["TDV-এর কুয়েত ভুক্তি অনুযায়ী বন্দরটি নাজদ থেকে আসা উতুব গোত্র অষ্টাদশ শতকের শুরুতে প্রতিষ্ঠা করেছিল এবং সাবাহ পরিবার শতকের শেষ দিকে শাসন গ্রহণ করেছিল। লাহসা যখন সউদিদের হাতে গেল সেই একই বছরগুলোতে ওয়াহহাবি চাপের মুখে বসরার ওপর নির্ভর করা ছাড়া উপায় না থাকা আমিরাত অটোমান আশ্রয়ে এলো। এই বন্ধন 1871 সালে মিদহাত পাশার বসরা পুনর্বিন্যাসে আনুষ্ঠানিক রূপ পাবে এবং কুয়েত বসরা সানজাকের তিনটি কাজার একটি হিসেবে গণ্য হবে; ইরাকের পরবর্তী ভূখণ্ডগত দাবিও এই নথির ওপর ভিত্তি করে।", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["ওয়াহহাবিদের হাতে মক্কা হারানো", "2da23acd"], "d": ["নাজদে জন্ম নেওয়া ওয়াহহাবি আন্দোলন সউদ ইবনে আবদুল আজিজের সময়ে হিজাজের দিকে অগ্রসর হলো; তায়েফ ও মদিনার পর মক্কাও দ্বিতীয়বার দখলে এলো — মক্কার আমির শরিফ গালিব আমিরাতে থাকার শর্তে শহরটি ওয়াহহাবিদের হাতে তুলে দেন। মাজার ভাঙা হলো এবং দামেস্ক ও কায়রো থেকে আসা হজ কাফেলার পথ বন্ধ হলো; সুলতান প্রতি বছর হারামাইনে যে সুররা পাঠাতেন তাও এই বছরগুলোতে ব্যাহত হলো — 1915 সাল পর্যন্ত অবিচ্ছিন্ন চলা এই বরাদ্দের একমাত্র ব্যতিক্রম ওয়াহহাবি আধিপত্যের কাল। হারামাইনের রক্ষক উপাধি সুলতানের বৈধতার মূল ভিত্তিগুলোর একটি হওয়ায় এই ক্ষতি ভূখণ্ড হারানোর চেয়েও বড় রাজনৈতিক আঘাত হলো; পুনরুদ্ধারে সাত বছর লাগবে এবং তা সম্ভব হবে কাভালালি মেহমেদ আলী পাশার সেনাবাহিনীর মাধ্যমে।", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["রাগুসা প্রজাতন্ত্রের (দুব্রোভনিক) অবসান — ফরাসি দখল", "f8e27bf1"], "d": ["কাম্পো ফর্মিও চুক্তির (1797) মাধ্যমে দালমাতিয়া উপকূলে অবস্থান নেওয়া ফরাসিরা 27 মে 1806 সালে দুব্রোভনিক দখল করে ক্ষুদ্র বণিক প্রজাতন্ত্রের অবসান ঘটালো। এভাবে 1458 সাল থেকে অটোমানদের কর দিয়ে স্বায়ত্তশাসন ও বাণিজ্যিক সুবিধা রক্ষা করে আসা দুব্রোভনিকের সাড়ে তিন শতাব্দীর করদ মর্যাদা শেষ হলো; শহর ও প্রজাতন্ত্রের ম্লিয়েত (Mljet) দ্বীপ মানচিত্রে সরাসরি ফরাসি শাসনে চলে যায়।", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["সুখুমের রুশদের হাতে হারানো — পূর্ব কৃষ্ণসাগর উপকূল উন্মুক্ত হওয়া", "adc96bd4"], "d": ["1806-1812 অটোমান-রুশ যুদ্ধে রুশ নৌবাহিনী পূর্ব কৃষ্ণসাগর উপকূলের দিকে অগ্রসর হলো এবং আবখাজিয়ায় অটোমান আধিপত্যের ভিত্তি সুখুমকালে দখল করলো। দুর্গটি ককেশীয় গোত্রগুলোর সঙ্গে যোগাযোগ ও উপকূলীয় বাণিজ্যের কেন্দ্র ছিল। এর পতনের সঙ্গে সঙ্গে রাশিয়া প্রথমবারের মতো কৃষ্ণসাগরের পূর্ব উপকূলে স্থায়ীভাবে বসতি গড়লো; ককেশাসে অটোমান প্রভাব আনাপা ও পোতির আশেপাশে সীমিত হয়ে পড়লো।", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["পার্গাকে অটোমান শাসনে ছেড়ে দেওয়া", "66e0cc5d"], "d": ["পার্গা 1401 সাল থেকে ভেনিসের দখলে ছিল এবং কখনো অটোমান শাসনে আসেনি; ভেনিসের পতনের পর ক্রমান্বয়ে ফ্রান্স ও ব্রিটেনের হাতে গেল। TDV-এর তেপেদেলেনলি আলী পাশা ভুক্তি পরিস্থিতিটি এভাবে সংক্ষেপ করে: শহর ইংরেজদের কাছে আত্মসমর্পণ করেছিল এবং আলী পাশার শাসনে ছেড়ে দেওয়া হয় কেবল 1819 সালে। হস্তান্তরের ফলে অধিবাসীদের বড় অংশ আইওনীয় দ্বীপপুঞ্জে চলে গেল। এভাবে পাসারোভিৎসে ভেনিসের হাতে রেখে আসা প্রেভেজা-পার্গা-ভোনিৎসা ত্রয়ীর শেষটিও সাম্রাজ্যের সঙ্গে যুক্ত হলো; পার্গা চুরানব্বই বছর অটোমান থাকবে।", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["গর্দুসের (করিন্থ) গ্রিক বিদ্রোহীদের হাতে যাওয়া", "892dcdc6"], "d": ["গ্রিক স্বাধীনতা যুদ্ধের সময় আক্রোকরিন্থ বিদ্রোহীদের হাতে গেল এবং দুর্গের অধিনায়ক কামিল বে বন্দি হলেন।", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["আনাবোলুর (নাফপ্লিয়ন) বিদ্রোহীদের হাতে হারানো", "1a67fa50"], "d": ["মোরার সবচেয়ে সুরক্ষিত বন্দর আনাবোলু এক বছরেরও বেশি অবরোধের পর ক্ষুধার কারণে আত্মসমর্পণ করলো। বিদ্রোহের শুরু থেকে দুর্গটি উপদ্বীপে অটোমান নিয়ন্ত্রণের শেষ বড় অবলম্বন ছিল; এর পতনে পুরো মোরা বিদ্রোহীদের হাতে চলে গেল। শহরটি অল্প সময় পরে নতুন গ্রিক রাষ্ট্রের প্রথম রাজধানী হবে।", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["ইনেবাখতির গ্রিক শাসনে যাওয়া", "c9d19d4b"], "d": ["গ্রিক বিদ্রোহ পর্যন্ত অটোমান হাতে থাকা করিন্থ উপসাগরের উত্তর উপকূলের ইনেবাখতি 1829 সালের এপ্রিলে হাতছাড়া হলো এবং গ্রিক শাসনে চলে গেল; শহরের নাম প্রাচীন যুগের নাভপাক্তোসে ফেরানো হলো। শহরের মুসলিম ও ইহুদি জনসংখ্যা সম্পূর্ণ বিলুপ্ত হলো এবং এটি একটি ছোট শহরে পরিণত হলো।", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["আলজিয়ার্সের ফরাসি দখল — তিনশ বছরের ওজাকের অবসান", "0be8f568"], "d": ["পাওনা সংক্রান্ত বিরোধ থেকে উদ্ভূত পাখার ঘটনাকে অজুহাত করে ফ্রান্স তিন বছর আলজেরীয় উপকূল অবরোধ করে রাখলো, এরপর সিদি ফেরুশে সেনা নামালো। তিন সপ্তাহের অভিযান শেষে হুসেইন দে আত্মসমর্পণ করলেন এবং 1516 সাল থেকে চলে আসা অটোমান আলজিয়ার্স ওজাক শেষ হলো। দখল কেবল রাজধানীতে সীমিত থাকলো না; অভ্যন্তরের তিলিমসান, শেরশেল ও মেদেয়াও একই গ্রীষ্মে হাতছাড়া হলো। সমগ্র উপকূল ফরাসি নিয়ন্ত্রণে আসতে আরও চব্বিশ বছর লাগবে।", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["ইউবোয়ার (এগ্রিবোজ) গ্রিসকে দেওয়া — দ্বীপসহ (কারিস্তোস, ওরেওই)", "7b524aa4"], "d": ["গ্রিক স্বাধীনতা যুদ্ধজুড়ে তীব্র সংঘর্ষের মঞ্চ হলেও অটোমান হাতে থাকা এগ্রিবোজ শান্তিচুক্তি কার্যকর হওয়ার পর 1831 সালে গ্রিকদের দেওয়া হলো। 1470 সাল থেকে গুরুত্বপূর্ণ নৌঘাঁটি এই শহরের মুসলিম অধিবাসীরা সব সম্পত্তি খুব কম দামে বিক্রি করে দলবেঁধে অটোমান ভূখণ্ডে চলে গেল; শহর দীর্ঘকাল শূন্য পড়ে রইল এবং জার্মান পর্যটক ফালমেরায়ার 1842 সালে একে ভূতুড়ে শহর বলে বর্ণনা করলেন।", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["ওরানের (ওয়াহরান) ফরাসি দখল", "a8415d66"], "d": ["1792 সালে স্পেন যুদ্ধ ছাড়াই যে ওরান হস্তান্তর করেছিল, তা আলজেরিয়ার পশ্চিমের সবচেয়ে বড় বন্দর ছিল। রাজধানীর পতনের ছয় মাস পর ফরাসি সেনারা শহরে প্রবেশ করলো। এখান থেকে শুরু হওয়া পশ্চিমমুখী অভিযান অল্প সময়েই আমির আবদুল কাদিরের পনেরো বছর স্থায়ী প্রতিরোধের মুখোমুখি হবে।", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["আন্নাবার (বোন) দখল", "21f37fb1"], "d": ["পূর্ব আলজেরিয়ার তিউনিসীয় সীমান্তের কাছের বন্দর আন্নাবা ফরাসি বাহিনী দখল করে কনস্তান্তিনের দিকে অভিযানের ঘাঁটি বানালো। শহরটি একই সঙ্গে সার্দিনিয়া দ্বীপের বিপরীতে আফ্রিকার সবচেয়ে কাছের বন্দর ছিল।", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["এথেন্সকে নতুন গ্রিক রাষ্ট্রের কাছে ছেড়ে দেওয়া (বাভারীয় সেনারা যেদিন অ্যাক্রোপলিস গ্রহণ করে)", "deee4d37"], "d": ["1456 সাল থেকে অটোমান এথেন্স গ্রিক স্বাধীনতা যুদ্ধের সময় কয়েকবার হাতবদল হয়েছিল, অ্যাক্রোপলিসের গ্যারিসন 1827 সালে আবার অটোমান নিয়ন্ত্রণে এসেছিল। লন্ডন প্রটোকলে টানা সীমানার উত্তরে পড়ায় শহর নতুন রাজ্যের কাছে হস্তান্তরিত হলো এবং গ্যারিসন অ্যাক্রোপলিস খালি করলো। অ্যাটলাসের দিন হলো বাভারীয় সেনারা যেদিন অ্যাক্রোপলিস গ্রহণ করে; অটোমান গ্যারিসনের প্রকৃত প্রস্থান কয়েক দিন পরে ঘটে (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, böl. 13; Finlay, Journals and Letters, c. I, s. 67)। পরের বছর এথেন্স আনাবোলুর জায়গায় গ্রিসের রাজধানী ঘোষিত হলো।", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["বিজায়ার (বুজি) দখল", "a8927e00"], "d": ["কাবিলিয়া পর্বত যেখানে সাগরে মিশেছে সেই বিজায়া বন্দর আলজিয়ার্স ও আন্নাবার মধ্যবর্তী উপকূল রেখার শেষ স্বাধীন সংযোগ ছিল। নৌ-কামানের সহায়তায় দখল হলো; তবে এর পেছনের পার্বত্য অভ্যন্তর আরও ত্রিশ বছর ফরাসি নিয়ন্ত্রণে আসবে না। উপকূল বরাবর এই দখলগুলো অটোমান আলজেরিয়ার বছর বছর মানচিত্রে ক্ষয়ে যাওয়াকে গড়ে তোলে।", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["সেতিফ দখল", "2073731a"], "d": ["কনস্তান্তিনের এক বছর আগে পতনের পর ফরাসি বাহিনী মালভূমিতে উঠে প্রাচীন রোমান শহর সেতিফ দখল করলো এবং সেখানে স্থায়ী গ্যারিসন স্থাপন করলো। সেতিফ উপকূল ও সাহারার মধ্যবর্তী কাফেলা পথের সংযোগস্থল ছিল; এর দখল দেখালো যে ফ্রান্স এখন কেবল বন্দর নয়, অভ্যন্তরীণ বাণিজ্য নেটওয়ার্কও নিয়ন্ত্রণ করতে শুরু করেছে।", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["বিসকরা দখল — সাহারার দরজা হারানো", "d895cad0"], "d": ["বিসকরা আটলাস পর্বতের দক্ষিণ পাদদেশে সাহারার দিকে খোলা দরজা এবং খেজুর মরূদ্যানের কেন্দ্র ছিল। আমির আবদুল কাদিরের প্রতিরোধ ভাঙতে শুরু করা বছরগুলোতে এটি দখল হওয়ায় ফরাসি নিয়ন্ত্রণ প্রথমবারের মতো মরুভূমির উত্তর প্রান্তে পৌঁছলো। এরপর থেকে মরূদ্যানে মরূদ্যানে এগিয়ে যাওয়া মরু অভিযান চলবে।", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["তুগগুর্ত দখল — সমগ্র আলজেরিয়ার হাতছাড়া হওয়া", "33c056e2"], "d": ["সাহারার উত্তরের মরূদ্যান শহর তুগগুর্ত দখলের মাধ্যমে 1830 সালে শুরু হওয়া দখল বর্তমান আলজেরিয়ার উত্তর অর্ধেকে সম্পূর্ণ হলো। অটোমান রাষ্ট্র এই বছরগুলোতে ক্রিমিয়া যুদ্ধে ফ্রান্সের সঙ্গে একই পক্ষে লড়ছিল; আলজেরিয়ার ওপর আইনি দাবি কখনো আনুষ্ঠানিকভাবে ত্যাগ না করলেও বাস্তবে একটি পদক্ষেপও নিতে পারেনি। উত্তর আফ্রিকায় হাতে থাকা একমাত্র ভূখণ্ড ছিল ত্রিপোলিতানিয়া।", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["উবাইদের পতন — কর্দোফান মাহদি বাহিনীর হাতে যাওয়া", "58299f62"], "d": ["নিজেকে মাহদি ঘোষণাকারী মুহাম্মদ আহমদের শুরু করা আন্দোলন সুদানে মিশরের শাসনের বিরুদ্ধে দ্রুত ছড়িয়ে পড়লো। কর্দোফানের কেন্দ্র উবাইদ চার মাসের অবরোধের পর পতিত হলো এবং বিদ্রোহের রাজধানী হলো; শহরের কোষাগার ও অস্ত্রভাণ্ডার আন্দোলনের সেনাবাহিনী গড়ে তোলা সম্ভব করলো। সুদান আইনগতভাবে তখনও অটোমানদের সঙ্গে সংযুক্ত মিশরীয় খেদিভের ভূখণ্ড ছিল, তাই এই ক্ষতি মানচিত্রে সাম্রাজ্যের মূল অংশ থেকে খসে পড়া।", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["খার্তুমের পতন — সমগ্র সুদান হারানো", "d4b98464"], "d": ["দশ মাসের অবরোধের পর মাহদি বাহিনী নীল ও শ্বেত নীলের মিলনস্থলের খার্তুমে প্রবেশ করলো; শহরের গভর্নর গর্ডন নিহত হলেন, সাহায্যের জন্য পাঠানো ব্রিটিশ দল দুই দিন দেরি করে পৌঁছালো। এই তারিখের পর সেন্নার, দোঙ্গোলা ও কর্দোফানসহ সমগ্র সুদান চৌদ্দ বছর মাহদি রাষ্ট্রের শাসনে থাকলো। অঞ্চলটি কেবল 1899 সালে অটোমান বন্ধন সম্পূর্ণ ছিন্ন অবস্থায় ব্রিটিশ-মিশরীয় যৌথ শাসনে যাবে।", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["মাসাওয়ার ইতালীয় দখল — লোহিত সাগরের পশ্চিম উপকূল হারানো", "c333b95b"], "d": ["হাবেশ প্রদেশের কেন্দ্র মাসাওয়া বন্দর মাহদি বিদ্রোহ সুদান জুড়ে যে বিশৃঙ্খলা সৃষ্টি করেছিল তার সুযোগ নেওয়া ইতালি দখল করলো; এটি ইতালীয় ইরিত্রিয়ার কেন্দ্রবিন্দু হলো। উত্তরের সুয়াকিন ও উপকূলের দাহলাক দ্বীপপুঞ্জও একই প্রক্রিয়ায় হাতছাড়া হলো। এভাবে সুলতান প্রথম সেলিমের সময় থেকে চলে আসা লোহিত সাগরের পশ্চিম উপকূলে অটোমান আধিপত্যের অবসান হলো এবং সাগরের দুই তীরই এখন বিদেশি জলে পরিণত হলো।", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["রোডসের ইতালীয় দখল", "e08662c5"], "d": ["ত্রিপোলিতানিয়া যুদ্ধে অটোমান রাষ্ট্রকে আলোচনার টেবিলে বসাতে চাওয়া ইতালি যুদ্ধকে ভূমধ্যসাগরে ছড়িয়ে রোডসে সেনা নামালো। দ্বীপ কয়েক দিনের মধ্যে দখল হলো। 1522 সালে কানুনি দীর্ঘ অবরোধের পর যে রোডস জয় করেছিলেন এবং তিনশ নব্বই বছর ধরে রেখেছিলেন, তা এভাবে সাম্রাজ্যের পূর্ব ভূমধ্যসাগরের সবচেয়ে বড় দ্বীপ ঘাঁটি থাকা বন্ধ করলো; উশি চুক্তিতে অস্থায়ী দখল গণ্য হলেও আর কখনো ফেরত পাওয়া যায়নি।", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["দোদেকানিজের ইতালীয় দখল", "200aacf2"], "d": ["রোডস দখলের এক সপ্তাহের মধ্যে ইতালীয় নৌবাহিনী আশেপাশের দ্বীপগুলোও দখল করলো; এই দ্বীপপুঞ্জকে পরে 'দোদেকানিজ' নাম দেওয়া হবে। দ্বীপগুলোর বেশির ভাগ আনাতোলীয় উপকূল থেকে কয়েক মাইল দূরে ছিল এবং এজিয়ানের দক্ষিণ-পূর্ব পথ নিয়ন্ত্রণ করতো। দখলটি উশি চুক্তিতে ত্রিপোলিতানিয়া ত্যাগের বিনিময়ে অস্থায়ী গণ্য হলো, কিন্তু ইতালি দ্বীপগুলো কখনো খালি করেনি; 1947 সালে এগুলো গ্রিসের কাছে হস্তান্তরিত হবে।", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["ইস্তানকোয়ের (কস) দখল", "ab246c62"], "d": ["দোদেকানিজ অভিযানের শেষ সংযোগ ইস্তানকোয় বদরুম উপদ্বীপের ঠিক বিপরীতে উর্বর ও ঘনবসতিপূর্ণ দ্বীপ ছিল। দখলের ফলে এজিয়ানের দক্ষিণ-পূর্ব কোণের সব দ্বীপ ইতালীয় নিয়ন্ত্রণে এলো এবং আনাতোলিয়ার দক্ষিণ-পশ্চিম উপকূল আগাগোড়া বিদেশি দ্বীপশৃঙ্খলে ঘেরা হলো।", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["ইকারিয়ার স্বাধীনতা ঘোষণা", "c4452033"], "d": ["সামোস ও খিওসের মাঝের ছোট ইকারিয়া দ্বীপে জনগণ ইতালীয় দখলের সৃষ্ট অনিশ্চয়তার মধ্যে বিদ্রোহ করে অটোমান জান্ডারমারিকে দ্বীপ থেকে বের করে দিল এবং নিজস্ব পতাকা, ডাকটিকিট ও পরিষদসহ পাঁচ মাসের একটি 'মুক্ত রাষ্ট্র' ঘোষণা করলো। 1912 সালের নভেম্বরে দ্বীপ গ্রিসের সঙ্গে যুক্ত হলো। ক্ষুদ্রতা সত্ত্বেও এই ঘটনা এজিয়ানে কেন্দ্রীয় প্রশাসন কীভাবে ভেঙে পড়ছিল তার স্পষ্ট নির্দেশক।", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["সামোসের অটোমান শাসন থেকে বেরিয়ে যাওয়া", "3a862f2b"], "d": ["সামোস 1832 সাল থেকে অটোমানদের কর দেওয়া এবং ইস্তানবুলের নিযুক্ত একজন বে দ্বারা শাসিত স্বায়ত্তশাসিত আমিরাত ছিল। ত্রিপোলিতানিয়া যুদ্ধের সৃষ্ট শূন্যতায় দ্বীপের ঐক্যপন্থী আন্দোলন প্রশাসন দখল করলো এবং স্বায়ত্তশাসিত আমিরাত ব্যবস্থা কার্যত শেষ হলো; দ্বীপ একই বছর গ্রিসের সঙ্গে যুক্ত হওয়ার ঘোষণা দিল। আনাতোলীয় উপকূল থেকে দুই কিলোমিটার দূরের এই দ্বীপ এজিয়ানে হারানো প্রথম ভূখণ্ডগুলোর একটি হলো।", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["ইয়ানিয়ার পতন — এপিরাস ও পার্গা হারানো", "d42fce18"], "d": ["বলকান যুদ্ধে পাঁচ মাস অবরুদ্ধ ইয়ানিয়া বিজানি অবস্থানগুলোর পতনের পর আত্মসমর্পণ করলো; শহরের সঙ্গে সমগ্র এপিরাস গ্রিসে চলে গেল। ইয়ানিয়া সানজাকের অধীন পার্গাও এই তারিখে হাতছাড়া হলো এবং চুরানব্বই বছরের অটোমান শাসনের অবসান ঘটলো। ইয়ানিয়ার হারানো মানে ছিল সাম্রাজ্যের আদ্রিয়াটিকে খোলা শেষ জানালা বন্ধ হওয়া।", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["এদির্নের বুলগেরিয়ানদের হাতে পতন", "459d2e56"], "d": ["সাড়ে পাঁচ মাসের অবরোধের পর গোলাবারুদ ও রসদ শেষ হওয়া এদির্ন আত্মসমর্পণ করলো; শুকরি পাশা বন্দি হলেন। 1361 সাল থেকে অটোমান এবং বিরানব্বই বছর রাজধানী থাকা শহরের পতন বলকান যুদ্ধের সবচেয়ে ভারী আঘাত গণ্য হলো। এদির্ন চার মাস পর, দ্বিতীয় বলকান যুদ্ধে বুলগেরিয়ার অন্যান্য রণাঙ্গনে ভেঙে পড়ার সুযোগে পুনরুদ্ধার হবে।", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["ইয়ানবুর শরিফ হুসেইনের বাহিনীর হাতে হারানো", "e291c816"], "d": ["শরিফ হুসেইনের জুনে শুরু করা বিদ্রোহ লোহিত সাগর উপকূলে ছড়িয়ে পড়লো; মদিনার বন্দর ইয়ানবু ব্রিটিশ নৌবাহিনীর সহায়তায় বিদ্রোহীদের হাতে গেল। বন্দরটি বিদ্রোহের জন্য বাইরে থেকে আসা অস্ত্র ও অর্থ প্রবাহের প্রধান দরজা হয়ে উঠলো। এভাবে মদিনায় ফখরুদ্দিন পাশার বাহিনীর সমুদ্রের সঙ্গে সংযোগ কেটে গেল এবং শহর হিজাজ রেলপথের প্রান্তে একা পড়লো।", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["তৃতীয় গাজা যুদ্ধ — গাজা ও খান ইউনিসের হারানো", "c142a069"], "d": ["দুটি ব্যর্থ চেষ্টার পর অ্যালেনবি তৃতীয় আক্রমণে বীরসেবা ঘুরে ফ্রন্ট ভেদ করলেন এবং ছয় মাস ধরে রাখা গাজা রেখা ভেঙে পড়লো। গাজা ও তার দক্ষিণের খান ইউনিস একই দিনে খালি করা হলো। এই ভাঙন ফিলিস্তিন রণাঙ্গনের বিপর্যয়ের সূচনা হলো; জেরুজালেম পাঁচ সপ্তাহ পরে পতিত হবে।", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["গুমুলজিনার দখল — পশ্চিম থ্রেস হারানো", "904d813c"], "d": ["মুদ্রোসের পর প্রথমে মিত্রবাহিনীর নিয়ন্ত্রণে আসা পশ্চিম থ্রেস সান রেমো সম্মেলনের সিদ্ধান্তে গ্রিসের কাছে ছেড়ে দেওয়া হলো এবং গ্রিক সেনাবাহিনী গুমুলজিনায় প্রবেশ করলো। 1913 সালে বুলগেরিয়া থেকে পুনরুদ্ধার হওয়া অঞ্চলটি সাম্রাজ্যের রুমেলিতে হারানো শেষ ভূখণ্ড হলো। অঞ্চলের তুর্কি জনগোষ্ঠীর মর্যাদা তিন বছর পর লোজানে সংখ্যালঘু ব্যবস্থায় নির্ধারিত হবে। এই দখলের মাধ্যমে পশ্চিম থ্রেসের গুমুলজিনা, ইসকেচে, দেদেআগাচ ও সোফুলু কাজাগুলো গ্রিসের কাছে চলে গেল।", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["ইলখানি রাষ্ট্রের বিলুপ্তি: আবু সাইদ বাহাদুর খানের মৃত্যু", "0f187469"], "d": ["TDV ইসলাম বিশ্বকোষের ইলখানিরা ভুক্তি অনুযায়ী আবু সাইদের উত্তরাধিকারী না রেখে মৃত্যু এক শতাব্দী ধরে ইরানে কর্তৃত্বকারী ইলখানি রাষ্ট্রের বিভক্তি ঘটালো; আমিররা সিংহাসন কলহের সুযোগ নিয়ে জালায়ির, কারাকোয়ুনলু, মুজাফফারি, খোরাসান সারবেদার ও এরেতনাওগুল্লারির মতো স্থানীয় রাজবংশ গড়লেন। এই বিভাজন অঞ্চলটিকে এক শতাব্দী স্থায়ী বেগলিকের মোজাইকে ভাগ করলো; অবশেষে তৈমুরের অভিযানে আবার একীভূত হবে।", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["তৈমুরের ইরানের বড় অংশ নিজের শাসনে আনা", "1cee2b82"], "d": ["TDV ইসলাম বিশ্বকোষের তৈমুর ভুক্তি অনুযায়ী 1380-এর দশকের শুরু থেকে সারবেদার, কার্ত ও মুজাফফারির মতো ইলখানি-পরবর্তী স্থানীয় রাজবংশগুলোকে একে একে নিশ্চিহ্ন করা তৈমুর 1386-1388 সালের 'তিন বছরের অভিযান'-এর সময় ইরানের বড় অংশ কার্যত নিজের শাসনে আনলেন; মুজাফফারি রাজবংশের চূড়ান্ত পরিণতি আসবে 1393 সালে। অঞ্চলটি এভাবে এক শতাব্দীর বিভক্তির পর আবার একক কেন্দ্রীয় কর্তৃত্বের অধীনে এলো।", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["আরাস বিজয়: কারা ইউসুফ তৈমুরি আবু বকর মির্জাকে পরাজিত করলেন", "4b61a75a"], "d": ["1405 সালে তৈমুরের মৃত্যুর পর নির্বাসন থেকে ফেরা কারাকোয়ুনলু বে কারা ইউসুফ আভনিক দখল করে পূর্ব আনাতোলিয়ার ভূখণ্ডে পুনরায় অধিকার নেওয়ার পর আজারবাইজান ও দুই ইরাকের মালিক গণ্য তৈমুরের নাতি আবু বকর মির্জার বিরুদ্ধে অভিযান চালালেন এবং তাঁকে আরাস নদীর তীরে পরাজিত করলেন। এই বিজয় তাবরিজ কারাকোয়ুনলুকে দিল না: TDV `tebriz` লেখে যে শহর 1408 সালে আবু বকর মির্জার হাতে ছিল; আজারবাইজান জয় এনে দেওয়া যুদ্ধ হলো 13 এপ্রিল 1408 সারদরুদ।", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["সারদরুদ বিজয়: তাবরিজ ও আজারবাইজান কারাকোয়ুনলুর হাতে গেল", "1f0a429d"], "d": ["কারা ইউসুফ তৈমুরি আবু বকর মির্জাকে আরাসের পর দ্বিতীয়বার তাবরিজের কাছে সারদরুদে পরাজিত করলেন; এই বিজয় আজারবাইজান কারাকোয়ুনলুকে এনে দিল। কারা ইউসুফ এরপর বিস্তাম বেকে ইরাক-ই আজম জয়ের দায়িত্ব দিলেন;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["ইস্তানবুলে প্লেগ মহামারি ও প্রাসাদের এদির্নে স্থানান্তর", "70c7a163"], "d": ["TDV ইসলাম বিশ্বকোষের ইস্তানবুল ভুক্তি অনুযায়ী শহরের দ্রুত ও ঘন বসতি স্থাপন সময়ে সময়ে মহামারি রোগ ছড়ানোর ক্ষেত্র তৈরি করেছিল; 1466 সালের প্লেগ মহামারির সময় প্রাসাদ ও রাষ্ট্রের গণ্যমান্যরা সাময়িকভাবে এদির্নে সরে গিয়েছিলেন। এ ধরনের মহামারিতে শহরের জনসংখ্যা গুরুতর ক্ষতির শিকার হতো।", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["উজুন হাসানের কারাকোয়ুনলু রাষ্ট্রের অবসান", "ef68399e"], "d": ["TDV ইসলাম বিশ্বকোষের উজুন হাসান ভুক্তি অনুযায়ী আককোয়ুনলু শাসক উজুন হাসান কারাকোয়ুনলু শাসক জাহান শাহকে বিঙ্গোল-সানজাক অঞ্চলে 12 রবিউস সানি 872 / 10 নভেম্বর 1467 তারিখে পরাজিত করে হত্যা করলেন; জাহান শাহের পুত্র হাসান আলী 1468 সালের সেপ্টেম্বরে মারান্দে পরাজিত হলেন, 1469 সালের এপ্রিল-মে মাসে হামাদানের সামনে নিহত হলেন এবং কারাকোয়ুনলু রাষ্ট্রের চূড়ান্ত অবসান ঘটলো। ভূখণ্ড আককোয়ুনলু আধিপত্যে গেল; রাষ্ট্র পরবর্তী দশ বছরে ইরানের অভ্যন্তর পর্যন্ত বিস্তৃত হবে।", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["সাহন-ই সেমান মাদ্রাসাগুলোর শিক্ষাদানের জন্য খোলা", "021f2a83"], "d": ["TDV ইসলাম বিশ্বকোষের সাহন-ই সেমান ভুক্তি অনুযায়ী ফাতিহ কমপ্লেক্সের অন্তর্ভুক্ত এই আটটি মাদ্রাসা সে সময়ের সর্বোচ্চ মানের শিক্ষা প্রতিষ্ঠান হিসেবে পরিকল্পিত হয়েছিল এবং অটোমান উলেমা শ্রেণিক্রমের শীর্ষ গঠন করেছিল। এখানে মুদাররিস হওয়া ও এখান থেকে স্নাতক হওয়া পরবর্তী শতাব্দীগুলোতে কাজি ও মুদাররিসের পেশায় সবচেয়ে মর্যাদাপূর্ণ ধাপ গণ্য হতো।", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["তোপকাপি প্রাসাদের (সারায়-ই জাদিদ) সমাপ্তি", "d2db6323"], "d": ["TDV ইসলাম বিশ্বকোষের তোপকাপি প্রাসাদ ভুক্তি অনুযায়ী সমকালীন সূত্রগুলো নির্মাণের শুরু ও শেষের তারিখে ভিন্নমত পোষণ করে; বাব-ই হুমায়ুন শিলালিপির 883 (1478) তারিখ অনুযায়ী ফাতিহের আদেশে সম্ভবত 1465 সালে শুরু হওয়া নির্মাণ এই বছরের মধ্যে মূলত সমাপ্ত হয়েছিল এবং প্রাসাদ পুরনো প্রাসাদের রাষ্ট্রীয় কেন্দ্রের স্থান নিল। এভাবে সুলতান তিন শতাব্দী ধরে রাষ্ট্রের প্রশাসনিক ও আনুষ্ঠানিক হৃদয় হতে যাওয়া নতুন বাসস্থানে উঠলেন।", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["দ্বিতীয় বায়েজিদের ইস্তানবুলে সিংহাসনারোহণ", "9b686d04"], "d": ["TDV ইসলাম বিশ্বকোষের দ্বিতীয় বায়েজিদ ভুক্তি অনুযায়ী আমাসিয়ার সানজাক বে শাহজাদা বায়েজিদ পিতার মৃত্যুসংবাদে দ্রুত ইস্তানবুলে এসে সিংহাসনে বসলেন; ভাই জেমের কোনিয়া থেকে যাত্রাকে জানিসারিদের সমর্থনে পেছনে ফেললেন। সিংহাসনারোহণের সময় জানিসারিদের প্রথামাফিক জুলুস বখশিশ বিতরণ করা হলো। এই সিংহাসন বদল দুই ভাইয়ের মধ্যকার সংগ্রামেরও সলতে জ্বালিয়ে দিল।", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["সুলতান জেমের বুরসায় নিজেকে সুলতান ঘোষণা", "b355168a"], "d": ["TDV ইসলাম বিশ্বকোষের সুলতান জেম ভুক্তি অনুযায়ী কারামান হয়ে বুরসায় পৌঁছানো জেম শহর দখল করে নিজেকে সুলতান ঘোষণা করলেন এবং খুতবা পাঠ করালেন। এই স্বল্পস্থায়ী সালতানাত বড় ভাই দ্বিতীয় বায়েজিদের পাঠানো বাহিনী ইয়েনিশেহিরে জেমকে পরাজিত করায় শেষ হলো। পরাজয়ের পর জেম মিশরের দিকে পালাতে বাধ্য হলেন।", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["গেদিক আহমেদ পাশার মৃত্যুদণ্ড", "6d75a58c"], "d": ["TDV ইসলাম বিশ্বকোষের গেদিক আহমেদ পাশা ভুক্তি অনুযায়ী ওত্রান্তো অভিযান ও উজির-ই আজমত্বের জন্য পরিচিত পাশা সুলতান জেম প্রশ্নে তাঁর অবস্থান এবং প্রভাব নিয়ে উদ্বেগের কারণে দ্বিতীয় বায়েজিদের আদেশে এদির্নে মৃত্যুদণ্ডপ্রাপ্ত হলেন। ফাতিহের যুগের সবচেয়ে অভিজ্ঞ সেনাপতিদের একজনের মৃত্যু প্রাসাদে ব্যাপক প্রতিধ্বনি তুললো।", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["ইস্তানবুলে প্রথম ছাপাখানা স্থাপন", "04475930"], "d": ["TDV ইসলাম বিশ্বকোষের Matbaa ভুক্তি অনুযায়ী স্পেন থেকে আসা ইহুদি অভিবাসী ভাই দাউদ ও শামুয়েল ইবনে নাহমিয়াস ইস্তানবুলে হিব্রু হরফে ছাপার প্রথম ছাপাখানা স্থাপন করলেন। এটি অটোমান ভূখণ্ডে সক্রিয় প্রথম ছাপাখানা উদ্যোগ হিসেবে নথিভুক্ত হলো; তুর্কি-আরবি হরফে ছাপা সম্ভব হবে আরও অনেক পরে, অষ্টাদশ শতকে।", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["শাহ ইসমাইলের তাবরিজ দখল: সাফাভি রাষ্ট্রের প্রতিষ্ঠা", "014d81e6"], "d": ["TDV ইসলাম বিশ্বকোষের সাফাভিরা ও আককোয়ুনলুরা ভুক্তিগুলো অনুযায়ী আরদাবিল তেক্কের তরুণ শায়খ ইসমাইল আনাতোলিয়ার কিজিলবাশ মুরিদদের নিয়ে গঠিত বাহিনী দিয়ে নাখচিভান অঞ্চলে আককোয়ুনলু সুলতান আলভেন্দকে ভারী পরাজয়ে ফেললেন; আলভেন্দ দিয়ারবাকিরে পালালেন, ইসমাইল তাবরিজে প্রবেশ করে সিংহাসনে বসলেন এবং বারো ইমামি শিয়া মতকে সরকারি মাজহাব ঘোষণা করলেন। এভাবে আককোয়ুনলু আধিপত্য এবং অঞ্চলের ইলখানি-পরবর্তী বেগলিক যুগ দুটোই শেষ হলো; তিন শতাব্দী স্থায়ী সাফাভি রাষ্ট্র প্রতিষ্ঠিত হলো।", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["ইস্তানবুলে 'ছোট কেয়ামত' ভূমিকম্প", "53e3b1d6"], "d": ["TDV ইসলাম বিশ্বকোষের ইস্তানবুল ভুক্তি অনুযায়ী শহরে আঘাত হানা প্রচণ্ড ভূমিকম্প জনগণের মধ্যে 'ছোট কেয়ামত' নামে স্মরণ করা হলো; প্রাচীর, মসজিদ ও বহু ভবনে ভারী ক্ষতি হলো, বহু প্রাণহানি ঘটলো। দ্বিতীয় বায়েজিদের আদেশে শহরে ব্যাপক মেরামত ও নির্মাণ অভিযান শুরু হলো।", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["শাহকুলু বিদ্রোহের শুরু", "3d9a4a90"], "d": ["TDV ইসলাম বিশ্বকোষের শাহকুলু বাবা তেকেলি ভুক্তি অনুযায়ী সাফাভি প্রচারণায় পুষ্ট শাহকুলু তেকে অঞ্চলে বিশাল তুর্কমেন জনগোষ্ঠীকে নিজের চারপাশে জড়ো করে ধর্মীয়-সামাজিক প্রকৃতির এক বড় বিদ্রোহ শুরু করলেন। বিদ্রোহ সে সময়ের সবচেয়ে গুরুতর অভ্যন্তরীণ নিরাপত্তা সংকটগুলোর একটি হয়ে রাষ্ট্রের কেন্দ্রীয় কর্তৃত্বকে গভীরভাবে নাড়া দিল।", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["দ্বিতীয় বায়েজিদের দিমেতোকার পথে মৃত্যু", "c46e98c9"], "d": ["সিংহাসন ত্যাগের পর জন্মস্থান দিমেতোকায় যাওয়ার উদ্দেশ্যে ইস্তানবুল ছেড়ে যাওয়া সাবেক সুলতান দিনে মাত্র 5-6 কিমি পথ অতিক্রমকারী পালকিতে এগোতে এগোতে চোরলুর কাছে আবালার গ্রামে অসুস্থ হয়ে পড়লেন এবং 25 রবিউল আউয়াল 918 (10 জুন 1512) তারিখে ইন্তেকাল করলেন। TDV ইসলাম বিশ্বকোষ মৃত্যুর কারণকে অত্যন্ত সন্দেহজনক মনে করে; কিছু দেশি-বিদেশি সূত্র অনুযায়ী বিষপ্রয়োগের সম্ভাবনার ওপর জোর দেওয়া হয়। একত্রিশ বছরের সালতানাত শেষে ওসমান গাজীর বংশের অষ্টম সুলতান এভাবে প্রাণ হারালেন।", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["শাহজাদা আহমেদের ইয়াভুজ সেলিমের আদেশে মৃত্যুদণ্ড", "65abb2f2"], "d": ["TDV ইসলাম বিশ্বকোষের প্রথম সেলিম ভুক্তি অনুযায়ী পিতা দ্বিতীয় বায়েজিদের প্রিয়পাত্র ও সিংহাসনের প্রধান প্রতিদ্বন্দ্বী শাহজাদা আহমেদ ভাই সেলিমের সিংহাসনারোহণের পর শুরু করা সংগ্রামে ইয়েনিশেহির সমভূমিতে পরাজিত হলেন এবং যুদ্ধক্ষেত্র থেকে পালানোর সময় ধরা পড়ে নিহত হলেন। এই ঘটনার মাধ্যমে সেলিম ভাই ও ভাতিজাদের মধ্যকার সিংহাসন প্রতিদ্বন্দ্বিতা মূলত শেষ করলেন।", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["ইব্রাহিম পাশা প্রধান উজির নিযুক্ত", "9c94c1e3"], "d": ["TDV ইসলাম বিশ্বকোষের ইব্রাহিম পাশা, মাকবুল ভুক্তি অনুযায়ী হাস ওদাবাশিত্ব থেকে রুমেলি বেইলারবেইত্বে এবং একই দিনে উজির-ই আজমত্বে উন্নীত ইব্রাহিম পাশা 13 শাবান 929 (27 জুন 1523) তারিখে প্রধান উজির হলেন। এটি প্রাসাদ সেবা থেকে সরাসরি প্রধান উজিরত্বে যাওয়ার নজিরবিহীন নিয়োগ ছিল এবং কানুনির কাছে ইব্রাহিম পাশার অসাধারণ ঘনিষ্ঠতা দেখাচ্ছিল।", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["বারবারোসা হাইরেদ্দিন পাশা কাপুদান-ই দরিয়া নিযুক্ত", "a0ff6bab"], "d": ["TDV ইসলাম বিশ্বকোষের বারবারোসা হাইরেদ্দিন পাশা ভুক্তি অনুযায়ী আলজিয়ার্সের সাফল্যের জন্য পরিচিত হাইরেদ্দিন পাশা 6 এপ্রিল 1534 তারিখে ইস্তানবুলে ডাকা হয়ে কাপুদান-ই দরিয়া ও জাজাইর-ই বাহর-ই সেফিদ বেইলারবেই পদে নিযুক্ত হলেন। এই নিয়োগ অটোমান নৌবাহিনীর পুনর্গঠন ও ভূমধ্যসাগরে নৌশক্তির প্রাতিষ্ঠানিকীকরণের সূচনা গণ্য হয়।", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["রুস্তেম পাশা প্রথমবার প্রধান উজির হলেন", "ddfcc014"], "d": ["TDV ইসলাম বিশ্বকোষের রুস্তেম পাশা ভুক্তি অনুযায়ী হাদিম সুলাইমান পাশা এক উজিরের সঙ্গে বিরোধের কারণে পদচ্যুত হওয়ার পর 17 রমজান 951 (2 ডিসেম্বর 1544) তারিখে রুস্তেম পাশা উজির-ই আজম পদে নিযুক্ত হলেন। মিহরিমাহ সুলতানের সঙ্গে বিবাহের সুবাদে প্রাসাদের সঙ্গে ঘনিষ্ঠতা বাড়া রুস্তেম পাশা এই পদে কানুনি যুগের সবচেয়ে প্রভাবশালী রাষ্ট্রনায়কদের একজন হয়ে উঠলেন।", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["এবুস্সুউদ এফেন্দি শায়খুল ইসলাম হলেন", "11ed04f8"], "d": ["TDV ইসলাম বিশ্বকোষের এবুস্সুউদ এফেন্দি ভুক্তি অনুযায়ী আট বছর রুমেলি কাজিআসকের পদে থাকা এবুস্সুউদ এফেন্দি শাবান 952 (অক্টোবর 1545) তারিখে শায়খুল ইসলাম পদে নিযুক্ত হলেন এবং এই পদে আটাশ বছর এগারো মাস থাকলেন। কানুনির আইনসংকলনগুলোকে শরিয়া আইনের সঙ্গে সামঞ্জস্যপূর্ণ করা ফতোয়ার জন্য পরিচিত এবুস্সুউদ এফেন্দি তাঁর সময়ের আইন ও শিক্ষা প্রতিষ্ঠান গড়ে তুলতে নির্ণায়ক ভূমিকা রাখলেন।", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["বারবারোসা হাইরেদ্দিন পাশার মৃত্যু", "3378a0bf"], "d": ["TDV ইসলাম বিশ্বকোষের বারবারোসা হাইরেদ্দিন পাশা ভুক্তি অনুযায়ী স্বল্পস্থায়ী অসুস্থতার পর 6 জমাদিউল আউয়াল 953 (5 জুলাই 1546) তারিখে ইস্তানবুলে ইন্তেকাল করলেন। বেশিকতাশে নিজের নির্মিত মাদ্রাসা সংলগ্ন সমাধিতে সমাহিত বারবারোসার মৃত্যু অটোমান নৌবাহিনীর গড়ে তোলা ভূমধ্যসাগরীয় আধিপত্যের এক যুগের সমাপ্তি হিসেবে দেখা হলো।", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["সুলাইমানিয়া মসজিদ ও কমপ্লেক্সের নির্মাণ শুরু", "101ec36f"], "d": ["TDV ইসলাম বিশ্বকোষের সুলাইমানিয়া মসজিদ ও কমপ্লেক্স ভুক্তি অনুযায়ী স্থপতি সিনানের প্রধান স্থপতিত্বে 1550 সালে ভিত্তি স্থাপিত কমপ্লেক্সটি মসজিদের পাশাপাশি মাদ্রাসা, হাসপাতাল, ইমারত ও গ্রন্থাগার নিয়ে এক বিশাল সামাজিক কমপ্লেক্স হিসেবে পরিকল্পিত হলো। নির্মাণ কানুনির সালতানাতের শক্তি ও ইস্তানবুলের নগর উন্নয়নের প্রতীক সবচেয়ে বড় ভবন কর্মসূচিগুলোর একটি ছিল।", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["ইস্তানবুল ও আশেপাশে নতুন প্লেগ তরঙ্গ শুরু", "547d6bf6"], "d": ["TDV ইসলাম বিশ্বকোষের তাউন ভুক্তি অনুযায়ী ইসলামি বিশ্বকে প্রভাবিত ষোড়শ শতকের মহামারিগুলোর একটি 1552-1566 সালের মধ্যে ঘটলো এবং বিশেষ করে ইস্তানবুল, আনাতোলিয়া, রুমেলি, মিশর ও উত্তর আফ্রিকায় প্রভাব ফেললো। প্রসারিত বাণিজ্যপথ ও বাড়তে থাকা জনগতিশীলতা সাম্রাজ্যের সবচেয়ে শক্তিশালী সময়ে মহামারি ছড়ানো সহজ করা কারণগুলোর মধ্যে গণ্য।", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["কারা আহমেদ পাশা প্রধান উজির নিযুক্ত", "a7d7748e"], "d": ["TDV ইসলাম বিশ্বকোষের কারা আহমেদ পাশা ভুক্তি অনুযায়ী দ্বিতীয় উজির হিসেবে কর্তব্যরত কারা আহমেদ পাশা বর্তমান প্রধান উজিরের হঠাৎ পদচ্যুতির পর 27 শাওয়াল 960 (5 অক্টোবর 1553) তারিখে উজির-ই আজম পদে উন্নীত হলেন। এই পরিবর্তন শাহজাদা মুস্তাফার মৃত্যুদণ্ডের কাছাকাছি দিনগুলোর, প্রাসাদের ভেতরের ক্ষমতার ভারসাম্য দ্রুত হাতবদলের সময়কে নির্দেশ করে।", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["কাপুদান-ই দরিয়া পিরি রেইসের মৃত্যুদণ্ড", "3b2ad7a0"], "d": ["TDV ইসলাম বিশ্বকোষের পিরি রেইস ভুক্তি অনুযায়ী হুরমুজ অবরোধ তুলে নেওয়ার সময় ঘুষের বিনিময়ে মুসলমানদের সম্পদ লুট এবং সেনাবাহিনীকে যুদ্ধক্ষেত্রে ফেলে যাওয়ার অভিযোগ মিশরে পৌঁছালে বিখ্যাত নাবিক ও মানচিত্রকার 960 সালের শেষ দিকে (1553-এর শেষে) কায়রোতে মৃত্যুদণ্ডপ্রাপ্ত হলেন। সম্পত্তি বাজেয়াপ্ত হওয়া পিরি রেইসের মৃত্যু সে সময়ের বসরা ও ভারত মহাসাগরের নৌনীতিতে পাশাদের মধ্যকার প্রতিদ্বন্দ্বিতার ফল বলে বিবেচিত হয়।", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["কারা আহমেদ পাশার মৃত্যুদণ্ড, রুস্তেম পাশা আবার প্রধান উজির", "9a85076a"], "d": ["TDV ইসলাম বিশ্বকোষের রুস্তেম পাশা ও কারা আহমেদ পাশা ভুক্তিগুলো অনুযায়ী 13 জিলকদ 962 (29 সেপ্টেম্বর 1555) দিবসে দিওয়ান সভার সময় হঠাৎ মৃত্যুদণ্ডপ্রাপ্ত কারা আহমেদ পাশার জায়গায় হুরেম ও মিহরিমাহ সুলতানদের সমর্থনে রুস্তেম পাশা একই দিনে দ্বিতীয়বার প্রধান উজির নিযুক্ত হলেন। ঘটনার নেপথ্য সূত্রগুলোতে অস্পষ্ট রাখা হয়েছে, প্রাসাদের ভেতরের ষড়যন্ত্রের ফল বলে মূল্যায়িত হয়েছে।", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["হুরেম সুলতানের মৃত্যু", "1ae998b5"], "d": ["TDV ইসলাম বিশ্বকোষের হুরেম সুলতান ভুক্তি অনুযায়ী কানুনির হাসেকি সুলতান হিসেবে বছরের পর বছর প্রাসাদের ভেতরে বিশাল প্রভাবের অধিকারী হুরেম সুলতান 26 জমাদিউস সানি 965 (15 এপ্রিল 1558) তারিখে ইস্তানবুলে ইন্তেকাল করলেন এবং সুলাইমানিয়া মসজিদ কমপ্লেক্সের সমাধিতে সমাহিত হলেন। 1534 সালে ভালিদে সুলতান হাফসার মৃত্যুর পর হারেমের ওপর কর্তৃত্ব সুসংহত করা হুরেম সুলতানের মৃত্যু পুত্র বায়েজিদ ও সেলিমের মধ্যকার সিংহাসন প্রতিদ্বন্দ্বিতার সামনের ভারসাম্য রক্ষাকারী প্রভাবও সরিয়ে দিল।", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["সোকোল্লু মেহমেদ পাশার প্রধান উজিরত্বে উত্থান", "896391a2"], "d": ["TDV ইসলাম বিশ্বকোষের সোকোল্লু মেহমেদ পাশা ভুক্তি অনুযায়ী সেমিজ আলী পাশার 30 জিলকদ 972 (29 জুন 1565) তারিখে মৃত্যুতে প্রধান উজিরত্বে উঠে আসা সোকোল্লু মেহমেদ পাশা কানুনির শেষ প্রধান উজির হলেন এবং এই দায়িত্ব তাঁর পরে দ্বিতীয় সেলিম ও তৃতীয় মুরাদের সময়েও চালিয়ে অটোমান ইতিহাসের সবচেয়ে দীর্ঘ সময় দায়িত্ব পালনকারী উজির-ই আজমদের একজন হয়ে উঠলেন।", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["দ্বিতীয় সেলিমের ইস্তানবুলে পৌঁছে সিংহাসনারোহণ", "0289ef97"], "d": ["কানুনি সুলতান সুলাইমানের জিগেতভারে মৃত্যুর পর খবর শৃঙ্খলা নষ্ট না করার জন্য সোকোল্লু মেহমেদ পাশা সপ্তাহের পর সপ্তাহ গোপন রাখলেন। TDV ইসলাম বিশ্বকোষ অনুযায়ী সেলানিকি সেলিমের ইস্তানবুলে আসার তারিখ 15 রবিউল আউয়াল 974 (30 সেপ্টেম্বর 1566) দিলেও সমকালীন ইতিহাসবিদদের অধিকাংশ 9 রবিউল আউয়ালকে (24 সেপ্টেম্বর) সঠিক মনে করেন। কানুনির মৃত্যু কেবল 24-25 অক্টোবর 1566 তারিখে বেলগ্রেডে আনুষ্ঠানিকভাবে ঘোষিত হলো।", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["কিলিচ আলী পাশার পুনর্গঠিত নৌবহর সাগরে নামলো", "d0fc9f48"], "d": ["ইনেবাখতির ভারী পরাজয়ের (7 অক্টোবর 1571) পর পুরো শীতকাল নৌঘাঁটিতে জাহাজ নির্মাণ হলো। TDV ইসলাম বিশ্বকোষ অনুযায়ী 1 সফর 980 (13 জুন 1572) তারিখে 250 গ্যালি এবং প্রায় 300 স্বেচ্ছাসেবক রেইস চেকতিরি নিয়ে গঠিত নতুন নৌবহর শক্তি প্রদর্শনের সঙ্গে সাগরে নামানো হলো।", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["সোকোল্লু মেহমেদ পাশা গুপ্তহত্যার শিকার হয়ে নিহত", "6ffa8dec"], "d": ["তিন সুলতানের সময় চৌদ্দ বছর প্রধান উজির থাকা সোকোল্লু মেহমেদ পাশা 20 শাবান 987 (12 অক্টোবর 1579) তারিখে প্রাসাদের বিকেলের দিওয়ানে আবেদনপত্র দেওয়ার ভান করে এগিয়ে আসা এক দরবেশের ছুরিকাঘাতে নিহত হলেন। TDV ইসলাম বিশ্বকোষ অনুযায়ী গুপ্তহত্যাটি মৃত্যুদণ্ডপ্রাপ্ত হামজাভিয়া শায়খ হামজা বালির প্রতিশোধের সঙ্গে সম্পর্কিত কিনা তা নিয়ে বিতর্ক আছে।", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["ইংল্যান্ডের সঙ্গে প্রথম বাণিজ্য আহিদনামা — ইংরেজদের ক্যাপিটুলেশন প্রদান", "59c8e3ee"], "d": ["1578 সালের অক্টোবরে ইস্তানবুলে পাঠানো ইংরেজ প্রতিনিধি উইলিয়াম হারবর্ন সোকোল্লু মেহমেদ পাশা ও হোজা সাদেদ্দিন এফেন্দির সমর্থনে তৃতীয় মুরাদের কাছ থেকে 1580 তারিখের একটি আহিদনামা পেলেন। এই আহিদনামার মাধ্যমে ইংরেজ বণিকরা আগে ফরাসি ও ভেনিসীয়দের দেওয়া বাণিজ্যিক সুবিধাগুলো (ক্যাপিটুলেশন) সমান মাত্রায় ভোগের অধিকার পেল। রানি প্রথম এলিজাবেথ ও তৃতীয় মুরাদের মধ্যে চিঠি বিনিময় হলো এবং দুই রাষ্ট্রের মধ্যে আনুষ্ঠানিক সম্পর্কও স্থাপিত হলো। এই সুবিধাগুলোর পরপরই 1581 সালে লন্ডনে Levant Company প্রতিষ্ঠিত হলো; ইংরেজরা 1825 সাল পর্যন্ত অঞ্চলে তাদের বাণিজ্য এই কোম্পানির মাধ্যমে চালালো।", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["ইস্তানবুল মানমন্দির হাট্ট-ই হুমায়ুনের আদেশে ধ্বংস", "3bc0c78c"], "d": ["মানমন্দিরগুলো রাষ্ট্রের জন্য দুর্ভাগ্য বয়ে আনে বলে ফতোয়া ও প্রাসাদের বিরোধিতার প্রভাবে 4 জিলহজ 987 (22 জানুয়ারি 1580) তারিখের এক হাট্ট-ই হুমায়ুনের মাধ্যমে ইস্তানবুল মানমন্দির সব যন্ত্রপাতিসহ ধ্বংস করা হলো। TDV ইসলাম বিশ্বকোষ অনুযায়ী এটি তাকিউদ্দিন আর-রাসিদের প্রতিষ্ঠিত প্রতিষ্ঠানের স্বল্পস্থায়ী পরিণতি হলো।", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["শাহজাদা মেহমেদের আতমেইদানের খতনা উৎসব শুরু", "c2926d5d"], "d": ["তৃতীয় মুরাদের পুত্র শাহজাদা মেহমেদ 6 জমাদিউল আউয়াল 990 (29 মে 1582) তারিখে শুরু হওয়া এবং ছাপ্পান্ন-সাতান্ন দিন স্থায়ী জাঁকজমকপূর্ণ অনুষ্ঠানের মাধ্যমে খতনা করানো হলো। TDV ইসলাম বিশ্বকোষ অনুযায়ী আতমেইদানে আয়োজিত উৎসবগুলো সে সময়ের সবচেয়ে জমকালো প্রাসাদীয় উদযাপনগুলোর একটি ছিল।", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["নুরবানু ভালিদে সুলতানের ইন্তেকাল", "77d0a577"], "d": ["তৃতীয় মুরাদের মা নুরবানু সুলতান 22 জিলকদ 991 (7 ডিসেম্বর 1583) তারিখে ইন্তেকাল করলেন। TDV ইসলাম বিশ্বকোষ অনুযায়ী ভালিদে সুলতান হিসেবে ভেনিস ও ফ্রান্সের দরবারের সঙ্গে চিঠিপত্র চালিয়েছিলেন, ভেনিস সিনেট একই বছর তাঁর সেবার বিনিময়ে 2000 ভেনিসীয় স্বর্ণমুদ্রা মূল্যের উপহার পাঠাতে সম্মত হয়েছিল।", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["মুদ্রামান কমানো আক্চের কারণে বেইলারবেই ঘটনা ফেটে পড়লো", "db2f2e61"], "d": ["রাষ্ট্র আক্চের রুপার অনুপাত কমিয়ে বেতন দেওয়ায় সিপাহি ও জানিসারিরা প্রাসাদ ঘেরাও করে ইতিহাসে বেইলারবেই ঘটনা নামে পরিচিত রক্তাক্ত বিদ্রোহ ঘটালো। TDV ইসলাম বিশ্বকোষের আবদুলকাদির শেইহি এফেন্দি ভুক্তি অনুযায়ী শায়খুল ইসলাম এই ঘটনায় পদচ্যুত হলেন।", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["তৃতীয় মেহমেদ সিংহাসনে বসলেন, উনিশ শাহজাদাকে শ্বাসরোধ করে হত্যা", "2cd9a8c5"], "d": ["তৃতীয় মেহমেদ পিতা তৃতীয় মুরাদের মৃত্যুতে 16 জমাদিউল আউয়াল 1003 (27 জানুয়ারি 1595) শুক্রবার ইস্তানবুলে পৌঁছে সিংহাসনে বসলেন। TDV ইসলাম বিশ্বকোষ অনুযায়ী একই রাতে চারজন প্রাপ্তবয়স্কসহ (মুস্তাফা, বায়েজিদ, ওসমান ও আবদুল্লাহ) উনিশ শাহজাদাকে শ্বাসরোধ করে হত্যা করা হলো; এটি অটোমান ইতিহাসের সবচেয়ে বড় ভ্রাতৃহত্যা ছিল।", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["সাফিয়ে সুলতান ভালিদে সুলতান হিসেবে প্রভাব অর্জন করলেন", "000bec21"], "d": ["তৃতীয় মুরাদের পত্নী ও তৃতীয় মেহমেদের মা সাফিয়ে সুলতান পুত্রের সিংহাসনারোহণের সঙ্গে ভালিদে সুলতান উপাধিতে প্রাসাদ রাজনীতিতে নির্ণায়ক অবস্থানে উঠলেন। TDV ইসলাম বিশ্বকোষ অনুযায়ী এই সময়ে হারেমভিত্তিক প্রভাব রাষ্ট্রের কাজে সরাসরি হস্তক্ষেপের মাত্রায় পৌঁছালো।", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["তৃতীয় মেহমেদ জানিসারিদের চাপে নিজে অভিযানে বেরোলেন", "d3c50656"], "d": ["প্রধান উজির দামাদ ইব্রাহিম পাশার আপত্তি সত্ত্বেও জানিসারিদের চাপে তৃতীয় মেহমেদ কানুনি সুলতান সুলাইমানের পর নিজে সেনাবাহিনীর নেতৃত্ব নেওয়া প্রথম সুলতান হিসেবে 20 জুন 1596 তারিখে ইস্তানবুল থেকে অভিযানে বেরোলেন। TDV ইসলাম বিশ্বকোষ অনুযায়ী এটি প্রাচীন গাজা ঐতিহ্যের পুনরুজ্জীবন বোঝাচ্ছিল।", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["1570-এর দশকে শুরু হওয়া তাউন মহামারি ইস্তানবুলকে প্রভাবিত করে চললো", "eb4ca37a"], "d": ["TDV ইসলাম বিশ্বকোষের তাউন ভুক্তি অনুযায়ী 1570-এর দশকে শুরু হওয়া মহামারি সপ্তদশ শতকের শুরু পর্যন্ত প্রভাব বজায় রাখলো এবং প্রধানত ইস্তানবুল সহ আনাতোলিয়া, বলকান, মিশর ও উত্তর আফ্রিকাকে আঘাত করলো। মহামারির সময়গুলো প্রাসাদ ও শহরের জীবনকে প্রায়ই ব্যাহত করা এক দীর্ঘস্থায়ী হুমকি গঠন করতো।", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["কারাইয়াজিজি আবদুলহালিম মারা গেলেন, বিদ্রোহী আন্দোলন দুর্বল হলো", "876ca7a6"], "d": ["12 আগস্ট 1601 তারিখে এলবিস্তানের কাছে সেপেতলিতে ভারী পরাজয়ের পর আহত অবস্থায় পিছু হটা কারাইয়াজিজি আবদুলহালিম 1010 সালে (1602) মারা গেলেন। TDV ইসলাম বিশ্বকোষ অনুযায়ী মৃত্যুসংবাদ ইস্তানবুলে 1010 সালের রমজানে (ফেব্রুয়ারি-মার্চ 1602) পৌঁছালো; সূত্রগুলো তাঁর মৃত্যু ক্ষতের কারণে নাকি নিজের লোকদের হাতে ঘটেছিল তা বিতর্কিত বলে উল্লেখ করে।", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["ভ্রাতৃহত্যা প্রথার কার্যত অবসান", "9046c607"], "d": ["প্রথম আহমেদ সিংহাসনারোহণে পূর্ববর্তী সুলতানদের বিপরীতে ভাই শাহজাদা মুস্তাফাকে হত্যা না করে প্রাণ ভিক্ষা দিলেন; এই সিদ্ধান্ত অটোমান উত্তরাধিকার ব্যবস্থায় ইকবার-ইরশেদ পদ্ধতি কার্যত গ্রহণের সূচনা গণ্য হয়। TDV ইসলাম বিশ্বকোষের 'Mustafa I' ভুক্তি মুস্তাফা এই তারিখের পর প্রাসাদে কক্ষবন্দি জীবন কাটিয়েছেন বলে জানায়। প্রথাটি শতাব্দীর পর শতাব্দী চলে আসা সিংহাসনারোহণ-হত্যাগুলোর কার্যত অবসান ঘটালো।", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["সুলতানআহমেদ মসজিদের ভিত্তি স্থাপিত", "1683262f"], "d": ["প্রথম আহমেদের আদেশে আতমেইদানে স্থপতি সেদেফকার মেহমেদ আগার নির্মাণ করা মসজিদের ভিত্তি অনুষ্ঠানসহ স্থাপিত হলো। TDV ইসলাম বিশ্বকোষের 'Sultan Ahmed Camii ve Külliyesi' ভুক্তি অনুযায়ী ভবনটি বিজয়ের সাফল্য ছাড়া সরাসরি রাজকোষ থেকে নির্মিত প্রথম বড় সুলতানি মসজিদ হওয়ার কারণে সে যুগের সমালোচনারও বিষয় হলো। কমপ্লেক্সটি মসজিদের সঙ্গে মাদ্রাসা, ইমারত ও সমাধিও অন্তর্ভুক্ত করে পরিকল্পিত হলো।", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["তরুণ ওসমানকে জানিসারিদের হত্যা (হাইলে-ই ওসমানিয়ে)", "324f6582"], "d": ["হজের অজুহাতে ইস্তানবুলের বাইরে গিয়ে জানিসারি ওজাক ভেঙে দেওয়ার পরিকল্পনার গুজবে বিদ্রোহ করা জানিসারি ও সিপাহিরা দ্বিতীয় ওসমানকে সিংহাসনচ্যুত করে ইয়েদিকুলে কারাগারে শ্বাসরোধ করে হত্যা করালো। TDV ইসলাম বিশ্বকোষের 'Osman II' ভুক্তি অনুযায়ী এই ঘটনা অটোমান ইতিহাসে একজন সুলতানের প্রকাশ্যে সামরিক বিদ্রোহে নিহত হওয়ার প্রথম নজির এবং রাজবংশ-সেনাবাহিনী সম্পর্কে গভীর ফাটল সৃষ্টি করলো। শেষ ঘণ্টাগুলো এভাবে কাটলো: জানিসারি আগা আলী আগার প্রাসাদে আশ্রয় নেওয়ার চেষ্টা ফল না দিলে সুলতানকে, TDV-এর ভাষায় 'মর্মান্তিকভাবে, খালি মাথায়, বিপর্যস্ত অবস্থায়' একটি ঘোড়ায় চড়িয়ে ভীষণ অপমানের মধ্যে প্রথমে প্রথম মুস্তাফা যেখানে ছিলেন সেই ওর্তা মসজিদে, একই দিনের বিকেলে ইয়েদিকুলে নিয়ে যাওয়া হলো; কিছু ঐতিহাসিকের মতে মৃত্যু প্রমাণ করার জন্য তাঁর কান ও নাক কেটে প্রথম মুস্তাফার মাকে দেখানো হলো। ঘটনার পর প্রথম মুস্তাফা দ্বিতীয়বার সিংহাসনে বসানো হলেন। 'হাইলে-ই ওসমানিয়ে' (ওসমান ট্র্যাজেডি) নামে পরিচিত ঘটনা প্রাসাদ-ওজাক ভারসাম্য স্থায়ীভাবে নষ্ট করলো এবং শতাব্দীজুড়ে চলা বৈধতার বিতর্ক শুরু করলো।", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["প্রথম মুস্তাফার দ্বিতীয়বার সিংহাসনারোহণ", "34a0b29a"], "d": ["তরুণ ওসমানকে জানিসারিদের হত্যার পর রাজবংশে অন্য কোনো প্রাপ্তবয়স্ক পুরুষ সদস্য না থাকায় প্রথম মুস্তাফা দ্বিতীয়বার সিংহাসনে বসলেন। TDV ইসলাম বিশ্বকোষের 'Mustafa I' ভুক্তি অনুযায়ী এই দ্বিতীয় সালতানাতও আগেরটির মতোই রাষ্ট্রের কাজ কার্যত চালাতে না পেরে কাটলো এবং রাষ্ট্র পরিচালনা উজির ও ভালিদে সুলতানের হাতে রয়ে গেল। চৌদ্দ মাস স্থায়ী এই সময় 1623 সালে চতুর্থ মুরাদের সিংহাসনারোহণে শেষ হলো।", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["জিবালি অগ্নিকাণ্ড", "3e42fb08"], "d": ["জিবালিতে শুরু হয়ে বাতাসের প্রভাবে দ্রুত ছড়ানো অগ্নিকাণ্ড ইস্তানবুলের একটি বড় অংশ ছাই করলো; TDV ইসলাম বিশ্বকোষের 'İstanbul' ভুক্তি অনুযায়ী সমকালীন সূত্রগুলো হাজার হাজার ঘর পুড়ে যাওয়ার কথা জানায়। অগ্নিকাণ্ডকে কাঠের ঘরের গঠন ও তামাকসেবনের সঙ্গে সম্পর্কিত করা চতুর্থ মুরাদের অল্প পরেই ঘোষণা করা কঠোর তামাক ও কফিহাউস নিষেধাজ্ঞার সরাসরি কারণ হলো। বিপর্যয় সে যুগের ইস্তানবুলে বারবার ঘটা বড় অগ্নিকাণ্ডগুলোর কেবল একটি ছিল।", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["চতুর্থ মুরাদের তামাক ও কফিহাউস নিষেধাজ্ঞা", "5dd71297"], "d": ["জিবালি অগ্নিকাণ্ডের পর অগ্নিকাণ্ড ও শৃঙ্খলার উদ্বেগে চতুর্থ মুরাদ তামাকসেবন ও কফিহাউস নিষিদ্ধ করলেন; নিষেধাজ্ঞা না মানলে মৃত্যুদণ্ডসহ ভারী শাস্তি প্রয়োগ হলো। TDV ইসলাম বিশ্বকোষের 'Murad IV' ভুক্তি অনুযায়ী সুলতান নিষেধাজ্ঞা তদারকি করতে নিজেই ছদ্মবেশে শহরের রাস্তায় ঘুরে বেড়ানোর মতো কঠোর অভ্যন্তরীণ শৃঙ্খলা নীতি অনুসরণ করলেন। এই কঠোর ব্যবস্থাগুলো চতুর্থ মুরাদের কেন্দ্রীয় কর্তৃত্ব পুনঃপ্রতিষ্ঠার প্রচেষ্টার অংশ হিসেবে মূল্যায়িত হয়।", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["ইস্তানবুলে প্লেগ মহামারি", "f33f58c5"], "d": ["চতুর্থ মুরাদের সময় ইস্তানবুল জনসংখ্যার গুরুত্বপূর্ণ অংশকে প্রভাবিত করা এক ভারী প্লেগ মহামারিতে কেঁপে উঠলো; শহরের ভেতরের বাণিজ্য ও দৈনন্দিন জীবন মাসের পর মাস ব্যাহত হলো। TDV ইসলাম বিশ্বকোষের 'İstanbul' ভুক্তি সপ্তদশ শতকে বারবার ঘটা মহামারিগুলো শহরের জনসংখ্যার ভারসাম্যকে গুরুতরভাবে প্রভাবিত করেছে বলে নথিভুক্ত করে। মহামারির সময় প্রাসাদ ও অভিজাত শ্রেণি কিছু সময়ের জন্য শহরের বাইরের বাগান ও কুটিরে সরে গিয়েছিল।", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["হেজারফেন আহমেদ চেলেবির ডানা নিয়ে উড়াল (জনশ্রুতি)", "df474c04"], "d": ["এভলিয়া চেলেবির বর্ণিত জনশ্রুতি অনুযায়ী হেজারফেন আহমেদ চেলেবি নিজের তৈরি ডানা নিয়ে গালাতা টাওয়ার থেকে লাফ দিয়ে উসকুদার পর্যন্ত ভেসে যেতে সক্ষম হলেন; ঐতিহাসিক নিশ্চয়তা বিতর্কিত হলেও এটি প্রযুক্তিগত কল্পনার প্রতীক হলো। সুলতান শুরুতে পুরস্কৃত করা হেজারফেনকে ঘটনার সৃষ্ট প্রতিধ্বনির কারণে পরে আলজিয়ার্সে নির্বাসিত করলেন।", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["জিনজি হোজা হুসেইন এফেন্দির প্রাসাদে প্রভাব অর্জন", "41d21572"], "d": ["সুলতান ইব্রাহিমের মানসিক কষ্ট চিকিৎসার জন্য প্রাসাদে ডাকা ঝাড়ফুঁককারী হুসেইন এফেন্দি অল্প সময়েই সুলতানের আস্থা অর্জন করে আনাতোলিয়া কাজিআসকের পদ পর্যন্ত উঠলেন। TDV ইসলাম বিশ্বকোষের 'Hüseyin Efendi, Cinci Hoca' ভুক্তি অনুযায়ী তিনি এই প্রভাব সম্পদ সঞ্চয় ও সে সময়ের রাজনৈতিক ঘটনায় হস্তক্ষেপে ব্যবহার করলেন। ইব্রাহিমের মৃত্যুর পর সব পদ থেকে অপসারিত হয়ে 1648 সালে মৃত্যুদণ্ডপ্রাপ্ত হলেন।", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["কেমানকেশ মুস্তাফা পাশার মৃত্যুদণ্ড", "0ecc8030"], "d": ["চতুর্থ মুরাদের সময় থেকে প্রধান উজির থাকা এবং আর্থিক সংস্কারে রাজকোষে গুরুত্বপূর্ণ উদ্বৃত্ত অর্জনকারী কেমানকেশ মুস্তাফা পাশা প্রাসাদের ভেতরের প্রতিদ্বন্দ্বীদের ইব্রাহিমকে প্রভাবিত করা এবং জানিসারি বিদ্রোহ ঘটানোর অভিযোগে শ্বাসরোধ করে মৃত্যুদণ্ডপ্রাপ্ত হলেন। TDV ইসলাম বিশ্বকোষের 'Kemankeş Mustafa Paşa' ভুক্তি অনুযায়ী মৃত্যুদণ্ড 21 জিলকদ 1053 / 31 জানুয়ারি 1644 তারিখে কার্যকর হলো: কেমানকেশ কারা মুস্তাফা পাশাকে হোজাপাশা বাজারে জল্লাদ কারা আলী শ্বাসরোধ করে হত্যা করলেন এবং চার্শিকাপিতে নিজের সমাধিতে সমাহিত করা হলো। তাঁর মৃত্যু সে সময়ের প্রধান উজির পদের অস্থিরতার একটি চমকপ্রদ উদাহরণ হিসেবে স্মরণ করা হয় এবং স্বল্পস্থায়ী কঠোর সংস্কারের কালকে শেষ করলো।", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["ক্রিট অভিযানের দিওয়ানে সিদ্ধান্ত এবং নৌবহরের যাত্রা", "9076827e"], "d": ["ভেনিসের মালিকানাধীন ক্রিট দ্বীপের দিকে বড় আকারের অভিযান শুরুর সিদ্ধান্ত দিওয়ান-ই হুমায়ুনে নেওয়া হলো এবং কাপুদান-ই দরিয়ার নেতৃত্বে অটোমান নৌবহর ইস্তানবুল থেকে ক্রিটের দিকে যাত্রা করলো। TDV ইসলাম বিশ্বকোষের 'Girit' ভুক্তি অনুযায়ী এই সিদ্ধান্ত প্রায় পঁচিশ বছর স্থায়ী দীর্ঘ অবরোধ ও যুদ্ধকালের রাজনৈতিক সূচনা গঠন করলো। অভিযান শুরু ইব্রাহিমের সময়ের সবচেয়ে বড় পররাষ্ট্রনীতি উদ্যোগ হিসেবে রাষ্ট্রের উচ্চপদস্থদের মধ্যে ব্যাপক বিতর্ক সৃষ্টি করেছিল।", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["চতুর্থ মেহমেদের সাত বছর বয়সে সিংহাসনারোহণ", "a197a3bc"], "d": ["ইব্রাহিমের অপসারণের সঙ্গে সঙ্গেই মাত্র সাত বছর বয়সী পুত্র মেহমেদ সিংহাসনে বসে চতুর্থ মেহমেদ উপাধিতে সুলতান হলেন। TDV ইসলাম বিশ্বকোষের 'Mehmed IV' ভুক্তি অনুযায়ী এত অল্প বয়সে সিংহাসনে আরোহণ ঠাকুরমা কোসেম সুলতান ও মা তুরহান সুলতানের মধ্যে প্রাসাদের ভেতরের প্রভাব সংগ্রাম তীব্র করলো। এই ক্ষমতার লড়াই 1651 সালে কোসেম সুলতানের হত্যায় পরিণত হবে।", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["তারহুনজু আহমেদ পাশার ভারসাম্যপূর্ণ বাজেট সংস্কার", "376fc7f2"], "d": ["প্রধান উজির তারহুনজু আহমেদ পাশা দীর্ঘ যুদ্ধের বছরগুলোর সৃষ্ট আর্থিক সংকট কাটাতে প্রাসাদ ব্যয়সহ এক কঠোর মিতব্যয় কর্মসূচি বাস্তবায়ন করে অটোমান ইতিহাসে পরিচিত প্রথম ভারসাম্যপূর্ণ বাজেট (তারহুনজু লায়িহা) প্রস্তুত করলেন। TDV ইসলাম বিশ্বকোষের 'Tarhuncu Ahmed Paşa' ভুক্তি অনুযায়ী এই সংস্কার রাজকোষে গুরুত্বপূর্ণ উদ্বৃত্ত এনে দিলেও প্রাসাদ মহল ও উচ্চ আমলাতন্ত্রে ব্যাপক অসন্তোষ সৃষ্টি করলো। এই অসন্তোষ এক বছর পর তাঁর মৃত্যুদণ্ডে পরিণত হবে।", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["চিনার ঘটনা (ভাক-আ-ই ভাকভাকিয়ে)", "4c6ed90f"], "d": ["TDV ইসলাম বিশ্বকোষের চিনার ঘটনা ভুক্তি অনুযায়ী ক্রিট অভিযান থেকে বেতন ছাড়া ফেরা জানিসারি ও সিপাহিরা ইস্তানবুলে বিদ্রোহ করে দুর্নীতির অভিযোগে অভিযুক্ত রাষ্ট্রনায়কদের মৃত্যুদণ্ড দাবি করলো। প্রধান উজির জুরনাজেন মুস্তাফা পাশার বাজেয়াপ্তি ও নির্বাসনের প্রস্তাব গৃহীত হলো না; প্রথমে তিনজন কর্মকর্তা, তারপর প্রায় ত্রিশজন রাষ্ট্রনায়ক মৃত্যুদণ্ডপ্রাপ্ত হলেন এবং তাঁদের লাশ সুলতানআহমেদ চত্বরের চিনার গাছে ঝোলানো হলো। ঘটনাটি তাই চিনার ঘটনা নামে পরিচিত হলো।", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["কোপরুলু মেহমেদ পাশার শর্তসাপেক্ষ সম্মতিতে প্রধান উজির নিযুক্ত", "3a6b7f8f"], "d": ["TDV ইসলাম বিশ্বকোষের কোপরুলু মেহমেদ পাশা ভুক্তি অনুযায়ী আশি বছরের কাছাকাছি কোপরুলু মেহমেদ পাশা সিলমোহর নিলেন কেবল ভালিদে তুরহান সুলতান ও চতুর্থ মেহমেদের কাছে উত্থাপিত কঠিন শর্তগুলো — নিয়োগে হস্তক্ষেপ না করা, তাঁর বিরুদ্ধে যা বলা হয় তা বিশ্বাস না করা — মানিয়ে নেওয়ার পর। বোয়নুইয়েরি মেহমেদ পাশার জায়গায় 26 জিলকদ 1066 তারিখে দায়িত্ব শুরু করলেন এবং রাষ্ট্রীয় শৃঙ্খলা কঠোরভাবে পুনঃপ্রতিষ্ঠায় নামলেন।", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["কাদিজাদেলি আন্দোলন কোপরুলু মেহমেদ পাশা কর্তৃক দমন", "5ec3ce84"], "d": ["TDV ইসলাম বিশ্বকোষের কাদিজাদেলিলার ভুক্তি অনুযায়ী কোপরুলু মেহমেদ পাশা দায়িত্ব নেওয়ামাত্র কাদিজাদে মেহমেদ এফেন্দির দল ও তরিকতপন্থীদের মধ্যকার ধর্মীয় সংঘাত হাতে নিলেন। উলেমার সঙ্গে পরামর্শের পর আন্দোলনের নেতা উস্তুভানি মেহমেদ এফেন্দি, তুর্ক আহমেদ ও দিভানে মুস্তাফার জন্য মৃত্যুদণ্ডের ফরমান জারি করা হলেও এই শাস্তি নির্বাসনে রূপান্তরিত হলো এবং তিনজনকে সাইপ্রাসে পাঠানো হলো; এভাবে আন্দোলনের দ্বিতীয় পর্ব শেষ হলো।", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["ইস্তানবুলে বড় অগ্নিকাণ্ড: আগাকাপিসির পুড়ে যাওয়া", "b9253b66"], "d": ["TDV ইসলাম বিশ্বকোষের আগাকাপিসি ভুক্তি অনুযায়ী চতুর্থ মেহমেদের আমলে 1660 সালের জুলাইয়ে লাগা বড় অগ্নিকাণ্ডে জানিসারি আগার সরকারি সদর দপ্তর আগাকাপিসি সম্পূর্ণ পুড়ে গেল এবং পরে পুনর্নির্মিত হলো। এই অগ্নিকাণ্ড সে সময়ের ইস্তানবুলকে বারবার আঘাত করা বড় শহুরে অগ্নিকাণ্ডগুলোর একটি ছিল।", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["কোপরুলুজাদে ফাজিল আহমেদ পাশা প্রধান উজির নিযুক্ত", "c1999b5c"], "d": ["TDV ইসলাম বিশ্বকোষের কোপরুলুজাদে ফাজিল আহমেদ পাশা ভুক্তি অনুযায়ী পিতা কোপরুলু মেহমেদ পাশার মৃত্যুতে 8 রবিউল আউয়াল 1072 (1 নভেম্বর 1661) তারিখে প্রধান উজির নিযুক্ত হলেন। পিতার বিপরীতে নম্র স্বভাব, ধার্মিক এবং জ্ঞানী-শিল্পীর পৃষ্ঠপোষক হিসেবে পরিচিত ফাজিল আহমেদ পাশা পনেরো বছরের বেশি প্রধান উজিরত্বকালে ইস্তানবুল ও বিজিত ভূখণ্ডে গ্রন্থাগার ও দাতব্য প্রতিষ্ঠান স্থাপন করালেন।", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["ভানি মেহমেদ এফেন্দির ইয়েনি জামি ওয়ায়েজ ও সুলতানের শিক্ষক পদে নিযুক্তি", "7ea6aaae"], "d": ["TDV ইসলাম বিশ্বকোষের মেহমেদ এফেন্দি, ভানি ভুক্তি অনুযায়ী কোপরুলুজাদে ফাজিল আহমেদ পাশা প্রধান উজির হওয়ায় ইস্তানবুলে ডাকা এবং চতুর্থ মেহমেদের কাছে পরিচিত করানো ভানি মেহমেদ এফেন্দি অল্প সময়েই সুলতানের ঘনিষ্ঠ মনোযোগ অর্জন করলেন। 1665 সালে ইয়েনি জামি ওয়ায়েজ ও সুলতানের শিক্ষক পদে নিযুক্ত হয়ে প্রাসাদের সবচেয়ে প্রভাবশালী ধর্মগুরুদের একজন হয়ে উঠলেন।", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["মেরজিফনলু কারা মুস্তাফা পাশা প্রধান উজির নিযুক্ত", "3d1e836c"], "d": ["TDV ইসলাম বিশ্বকোষের মেরজিফনলু কারা মুস্তাফা পাশা ভুক্তি অনুযায়ী ফাজিল আহমেদ পাশার মৃত্যুতে 28 শাবান 1087 (5 নভেম্বর 1676) তারিখে প্রধান উজির নিযুক্ত হলেন। কোপরুলু পরিবারের জামাতা ও প্রশিক্ষিত হিসেবে রাষ্ট্র পরিচালনায় দীর্ঘ অভিজ্ঞতার অধিকারী মেরজিফনলু চতুর্থ মেহমেদের সবচেয়ে শক্তিশালী ও প্রভাবশালী প্রধান উজিরদের একজন হলেন।", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["ভানি মেহমেদ এফেন্দির নির্বাসনে মৃত্যু", "cda714aa"], "d": ["TDV ইসলাম বিশ্বকোষের মেহমেদ এফেন্দি, ভানি ভুক্তি অনুযায়ী ভিয়েনা অভিযান সুলতানকে মানিয়ে নেওয়া প্রধান ব্যক্তিদের একজন গণ্য ভানি মেহমেদ এফেন্দি অভিযানের বিপর্যয়ে শেষ হওয়ার পর জনমতের চাপে অনুগ্রহ হারিয়ে বুরসার কেস্তেল শহরে নির্বাসিত হলেন। 14 জিলকদ 1096 (12 অক্টোবর 1685) তারিখে সেখানে ইন্তেকাল করলেন এবং নিজের নির্মিত মসজিদের প্রবেশপথে সমাহিত হলেন।", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["কোপরুলুজাদে ফাজিল মুস্তাফা পাশার প্রধান উজির নিযুক্তি ও আর্থিক সংস্কার", "b048570e"], "d": ["TDV ইসলাম বিশ্বকোষের কোপরুলুজাদে ফাজিল মুস্তাফা পাশা ভুক্তি অনুযায়ী 11 মুহাররম 1101 (25 অক্টোবর 1689) তারিখে প্রধান উজির নিযুক্ত ফাজিল মুস্তাফা পাশা জিজিয়া সংগ্রহ পদ্ধতি শরিয়তসম্মত ভিত্তিতে পুনর্বিন্যস্ত করলেন, মাঙ্গির মুদ্রাস্ফীতির বিরুদ্ধে লড়লেন এবং প্রাসাদ প্রতিষ্ঠান থেকে সম্পদ স্থানান্তর করে রাজকোষ শক্তিশালী করলেন। এ ছাড়া প্রদেশ প্রশাসনকে নির্ভরযোগ্য কর্মকর্তাদের দিয়ে জোরদার করে কেন্দ্রীয় দিওয়ানের মতো স্থানীয় পরিষদ গঠন করালেন।", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["মালিকানে ব্যবস্থার কার্যকর হওয়া", "316b8426"], "d": ["TDV ইসলাম বিশ্বকোষের মালিকানে ভুক্তি অনুযায়ী সপ্তদশ শতকের শেষ চতুর্থাংশে যুদ্ধ ব্যয় বৃদ্ধি ও ভূখণ্ড হারানোয় আয় কমে যাওয়ায় রাজকোষ ভারী আর্থিক সংকটে পড়লো। 1106 (1695) সালে কার্যকর হওয়া মালিকানে ব্যবস্থায় মুলতাজিমদের আজীবন স্থির কর অধিকার দিয়ে স্বল্পমেয়াদি শোষণের বদলে উৎপাদন রক্ষার প্রণোদনা আনা হলো।", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["দ্বিতীয় মুস্তাফার সিংহাসনারোহণ", "b53656c7"], "d": ["TDV ইসলাম বিশ্বকোষের Mustafa II ভুক্তি অনুযায়ী একত্রিশ বছর বয়সে সিংহাসনে বসা দ্বিতীয় মুস্তাফা প্রধান উজির ও শায়খুল ইসলামের অনুমোদনের অপেক্ষা না করে সালতানাত ঘোষণা করলেন; তরবারি বাঁধার অনুষ্ঠান কয়েক দিন পর এস্কি জামিতে হলো। ভিয়েনা বিপর্যয়ের পর বহু রণাঙ্গনের যুদ্ধ চলতে থাকা সময়ে সিংহাসনে বসা সুলতান অটোমান ইতিহাসের নিজে অভিযানে বেরোনো শেষ সুলতান হলেন।", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["ফেইজুল্লাহ এফেন্দির দ্বিতীয়বার শায়খুল ইসলাম নিযুক্তি", "1cf14cff"], "d": ["TDV ইসলাম বিশ্বকোষের ফেইজুল্লাহ এফেন্দি, সাইয়িদ ভুক্তি অনুযায়ী দ্বিতীয় মুস্তাফার সিংহাসনারোহণের পর 11 শাওয়াল 1106 (25 মে 1695) তারিখে দ্বিতীয়বার শায়খুল ইসলাম পদে নিযুক্ত হলেন। সুলতানের ওপর তাঁর প্রভাব আট বছরের বেশি স্থায়ী এই দায়িত্বকালে ক্রমশ বাড়লো।", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["ফেইজুল্লাহ এফেন্দির পুত্রদের উচ্চপদে বসানো এবং জমে ওঠা ক্ষোভ", "a6398280"], "d": ["TDV ইসলাম বিশ্বকোষের ফেইজুল্লাহ এফেন্দি, সাইয়িদ ভুক্তি অনুযায়ী শায়খুল ইসলাম দ্বিতীয় মুস্তাফার কাছ থেকে পুত্র ফেতহুল্লাহ এফেন্দি তাঁর পরে শায়খুল ইসলাম হবেন এই মর্মে নজিরবিহীন ফরমান পেলেন এবং আত্মীয়দের অল্প বয়সে উচ্চ পদে বসালেন। এই চর্চা উলেমা শ্রেণি, সেনাবাহিনী ও ইস্তানবুলের জনগণের মধ্যে ব্যাপক অসন্তোষ সৃষ্টি করলো; রাজধানী এদির্নেতে সরানোর গুজবের সঙ্গে মিলে 1703 সালের এদির্ন ঘটনার ক্ষেত্র প্রস্তুত করলো।", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["এদির্ন ঘটনার শুরু", "5a106458"], "d": ["TDV-এর 'Edirne Vak'ası' ভুক্তি অনুযায়ী বেতন না পাওয়া সৈন্যদের বিদ্রোহে শুরু হওয়া আন্দোলন অল্প সময়ে জানিসারি, মাদ্রাসা ছাত্র, কারিগর ও জনগণের যোগ দেওয়া ব্যাপক বিদ্রোহে পরিণত হলো। বিদ্রোহের মূল লক্ষ্য ছিল রাষ্ট্রের কাজে অতিরিক্ত হস্তক্ষেপের অভিযোগে অভিযুক্ত শায়খুল ইসলাম ফেইজুল্লাহ এফেন্দি। প্রায় 60.000 লোকের এক ভিড় ইস্তানবুল থেকে এদির্নের দিকে মিছিল করলো।", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["নেভশেহিরলি দামাদ ইব্রাহিম পাশার প্রধান উজিরত্ব", "8d627a6f"], "d": ["TDV-এর 'Damad İbrâhim Paşa, Nevşehirli' ভুক্তি অনুযায়ী অস্ট্রিয়ার সঙ্গে চলমান শান্তি আলোচনার সময় 8 জমাদিউস সানি 1130 (9 মে 1718) তারিখে প্রধান উজির পদে নিযুক্ত হয়ে নিয়োগ পাওয়ামাত্র যুদ্ধ শেষ করার আলোচনায় মনোযোগ দিলেন; দুই মাস পর পাসারোভিৎস চুক্তি স্বাক্ষরিত হলো (21 জুলাই 1718)। TDV-এর ভাষায় 'তিনি সামাজিক ও আর্থিক বিষয়ে কাজ করতে চাইছিলেন, বহু বছর ধরে পরাজয়ে শেষ হওয়া যুদ্ধ ভুলিয়ে দেওয়া এক শান্তির সময়ের আকাঙ্ক্ষা করছিলেন'। অর্থ দপ্তরে সংস্কার করে সৈন্যদের বেতন কমালেন এবং রাষ্ট্রীয় কোষাগারে গুরুত্বপূর্ণ উদ্বৃত্ত সৃষ্টি করলেন। বারো বছর স্থায়ী তাঁর প্রধান উজিরত্ব নিজের নাম বহনকারী যুগের (লালে যুগ) রাজনৈতিক কাঠামো গঠন করলো।", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["তুলুম্বাজি ওজাকের প্রতিষ্ঠা", "f58b0d97"], "d": ["TDV-এর 'Tulumbacı' ভুক্তি অনুযায়ী 1715 মোরা অভিযান থেকে ফেরা গেরচেক দাউদের ইস্তানবুলের অগ্নিকাণ্ডে তুলুম্বা দিয়ে দেখানো সাফল্যের ফলে প্রধান উজির নেভশেহিরলি দামাদ ইব্রাহিম পাশা তাঁকে একটি সরকারি অগ্নিনির্বাপক ওজাক গড়ার দায়িত্ব দিলেন। আজেমি ওগলান ব্যারাকে ছয় কর্মকর্তা ও পঞ্চাশ সৈনিক নিয়ে গঠিত ওজাক 1724 সালে 150 এবং 1755 সালে 461 জনে পৌঁছালো। দাউদ 1733 সালে মৃত্যু পর্যন্ত ওজাকের প্রধান থাকলেন।", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["মেহমেদ এফেন্দির পঞ্চদশ লুইয়ের গ্রহণ", "0ff5b174"], "d": ["TDV-এর 'Yirmisekiz Çelebi Mehmed Efendi' ভুক্তি অনুযায়ী দূত তুইলেরি প্রাসাদে ফ্রান্সের রাজা পঞ্চদশ লুইয়ের কাছে আনুষ্ঠানিকভাবে গৃহীত হলেন এবং তৃতীয় আহমেদের উপহার ও চিঠি পেশ করলেন। সফরকালে ভার্সাই, ত্রিয়ানন ও মার্লি প্রাসাদ, হাসপাতাল, মানমন্দির ও কারখানা ঘুরে দেখলেন; যা দেখলেন তা চিত্রের মাধ্যমে নথিভুক্ত করলেন।", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["মেহমেদ এফেন্দির ইস্তানবুলে প্রত্যাবর্তন", "a09a8bba"], "d": ["TDV-এর 'Yirmisekiz Çelebi Mehmed Efendi' ভুক্তি অনুযায়ী এক বছরের প্যারিস দূতিয়ালি থেকে ফেরা দূতের পর্যবেক্ষণ লালে যুগের স্থাপত্যরুচিকে প্রভাবিত করলো। তাঁর পুত্রের পরবর্তীকালে ইব্রাহিম মুতেফেররিকার সঙ্গে কাজ করা দূতিয়ালির সবচেয়ে স্থায়ী উত্তরাধিকার প্রথম তুর্কি ছাপাখানা প্রতিষ্ঠার ভিত্তি প্রস্তুত করলো।", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["সাদাবাদ প্রাসাদের নির্মাণ", "aec9c65e"], "d": ["TDV-এর 'Sâdâbâd' ভুক্তি অনুযায়ী কাগিতহানে নদীর তীরে ফরাসি প্রাসাদ স্থাপত্য থেকে অনুপ্রাণিত প্রাসাদ, খাল, ঝরনা ও কুটির নিয়ে গঠিত এক বিশাল বিনোদন ও বিশ্রামস্থল কমপ্লেক্স নির্মিত হলো। সে সময়ের সবচেয়ে প্রিয় বিনোদনস্থল হয়ে ওঠা সাদাবাদ কবি নেদিমের কবিতায় অমর হলো। কমপ্লেক্সটি 1730 সালের পাত্রোনা হালিল বিদ্রোহের সময় বহুলাংশে ধ্বংস হলো।", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["রুশ বাহিনীর দেরবেন্দ দখল: প্রথম পিটারের কাস্পিয়ান অভিযান", "c2b269f9"], "d": ["সাফাভি রাষ্ট্র আফগান আক্রমণে অভ্যন্তরীণ বিশৃঙ্খলায় জড়িয়ে পড়ার সময় রুশ জার প্রথম পিটার কাস্পিয়ান উপকূলের ইরানি ভূখণ্ড দখলের উদ্দেশ্যে অভিযানে বেরোলেন; উপকূলীয় শহর দেরবেন্দ উল্লেখযোগ্য প্রতিরোধ ছাড়াই রুশ বাহিনীর কাছে আত্মসমর্পণ করলো। TDV ইসলাম বিশ্বকোষের দেরবেন্দ ভুক্তি অনুযায়ী এই দখল তেরো বছর স্থায়ী অস্থায়ী রুশ আধিপত্যের সূচনা ছিল; অটোমান রাষ্ট্রও একই বিশৃঙ্খলার সুযোগে ককেশাসের পশ্চিম অংশের দিকে অগ্রসর হলো। সেনাবাহিনী আস্ত্রাখান থেকে সমুদ্রপথে আগ্রাখান উপসাগরে নেমে সেখান থেকে উপকূল ধরে তারকু হয়ে স্থলপথে হেঁটেছিল; তারকুর শামখাল পিটারকে আপ্যায়ন করে রুশ আনুগত্যে এলেন।", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["তারকু শামখালিক বিলুপ্তি: রুশ সরাসরি শাসন", "b0f029c6"], "d": ["1722 সালে পিটারকে আপ্যায়ন করে রুশ আনুগত্যে আসা তারকুর শামখাল আদিল-গিরে 1725 সালে বিদ্রোহ করলেন; ইয়েরোপকিন 1725 সালের শরতে তারকু ধ্বংস করলেন, শামখাল 1726 সালের মে মাসের মাঝামাঝি গ্রেপ্তার হয়ে নির্বাসিত হলেন এবং শামখালিক বিলুপ্ত হলো। তারকু ও আশেপাশের এলাকা 1735 সালের গাঞ্জা চুক্তি পর্যন্ত সরাসরি রুশ প্রশাসনে থাকলো।", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["ইব্রাহিম মুতেফেররিকাকে ছাপাখানা স্থাপনের অনুমতি", "0659dd0a"], "d": ["TDV-এর 'İbrâhim Müteferrika' ভুক্তি অনুযায়ী তৃতীয় আহমেদের ফরমান ও শায়খুল ইসলাম ইয়েনিশেহিরলি আবদুল্লাহ এফেন্দির ফতোয়ায় প্রথম তুর্কি ছাপাখানা স্থাপনের অনুমতি দেওয়া হলো। ছাপাখানা ইস্তানবুলের ইয়াভুজসেলিম এলাকায় কার্যক্রম শুরু করলো। মুতেফেররিকা 1747 সালে মৃত্যু পর্যন্ত তেইশ খণ্ডে সতেরোটি গ্রন্থ ছাপলেন।", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["প্রথম মুদ্রিত গ্রন্থ ভানকুলু অভিধানের সমাপ্তি", "684700e8"], "d": ["TDV-এর 'İbrâhim Müteferrika' ভুক্তি অনুযায়ী ছাপাখানার প্রথম গ্রন্থ সিহাহুল-জাওহারির তুর্কি অনুবাদ (ভানকুলু অভিধান) 1729 সালের শুরুতে সমাপ্ত হলো। এটি অটোমান ভূখণ্ডে আরবি হরফে ছাপা প্রথম বই ছিল এবং তুর্কি মুদ্রণ ইতিহাসের সূচনা গণ্য হয়।", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["নেভশেহিরলি দামাদ ইব্রাহিম পাশার মৃত্যুদণ্ড", "50c64341"], "d": ["TDV-এর 'Damad İbrâhim Paşa, Nevşehirli' ভুক্তি অনুযায়ী পাত্রোনা হালিল বিদ্রোহের সময় প্রাসাদে নিহত প্রধান উজিরের লাশ ইস্তানবুলের রাস্তায় টেনে নিয়ে গিয়ে সুলতানআহমেদ চত্বরের তৃতীয় আহমেদ ফোয়ারার কাছে ফেলে রাখা হলো। বারো বছরের প্রধান উজিরত্ব ও লালে যুগ এভাবে রক্তাক্তভাবে শেষ হলো।", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["তৃতীয় আহমেদের সিংহাসন ত্যাগ, প্রথম মাহমুদের সিংহাসনারোহণ", "a43f5d40"], "d": ["TDV-এর 'Mahmud I' ভুক্তি অনুযায়ী বিদ্রোহীদের চাপের মুখে তৃতীয় আহমেদ নিজের ও সন্তানদের জন্য নিরাপত্তার নিশ্চয়তা নিয়ে সিংহাসন ছাড়লেন এবং ভাতিজা শাহজাদা মাহমুদকে নিজে সিংহাসনে বসালেন। চাচার 'রাষ্ট্রের কাজ নিজের হাতে নাও, কাউকে বিশ্বাস করো না' উপদেশ নিয়ে সিংহাসনে বসা প্রথম মাহমুদ সর্বপ্রথম নিজেকে সিংহাসনে বসানো বিদ্রোহী গোষ্ঠীর প্রভাব ভাঙতে উদ্যোগী হলেন।", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["হুমবারাজি আহমেদ পাশার গোলন্দাজ ওজাক সংস্কার", "ea3a7c64"], "d": ["TDV-এর 'Humbaracı' ভুক্তি অনুযায়ী ইসলাম গ্রহণকারী ফরাসি বংশোদ্ভূত কর্মকর্তা আহমেদ পাশা প্রধান উজির হেকিমোগলু আলী পাশার সময় বেতনভুক্ত হুমবারাজি সংগঠনের ইউরোপীয় ধাঁচে সংস্কারে নামলেন। সরাসরি প্রধান উজিরের অধীন, 300 বেতনভুক্ত ও 301 তিমারধারীসহ মোট 601 জনের এক নতুন কাঠামো গড়লেন। সে সময়ের প্রযুক্তিতে 100 মর্টার কামান ও 50.000 গোলা তৈরি করালেন।", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["হেন্দেসেহানের (প্রকৌশল বিদ্যালয়ের প্রথম নমুনা) প্রতিষ্ঠা", "a77ed1f3"], "d": ["TDV-এর 'Mahmud I' ভুক্তি অনুযায়ী হুমবারাজি আহমেদ পাশা উসকুদারে হুমবারাহানে নামেও পরিচিত হেন্দেসেহানে প্রতিষ্ঠা করে প্রাসাদ কর্মচারী ও বোস্তানজিদের মধ্য থেকে বাছাই করা শিক্ষার্থীদের গণিত ও জ্যামিতিভিত্তিক সামরিক শিক্ষা দিলেন। এই প্রতিষ্ঠান পরবর্তীকালে বিকশিত প্রকৌশল বিদ্যালয়গুলোর প্রথম নমুনা গণ্য হয়।", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["গাঞ্জা চুক্তি: দেরবেন্দ ও বাকু ইরানকে ফেরত", "ff19d531"], "d": ["অটোমান হুমকির বিরুদ্ধে ইরানের সঙ্গে মিত্রতা খোঁজা রাশিয়া তেরো বছর ধরে দখলে রাখা কাস্পিয়ান উপকূলের শহরগুলো গাঞ্জা চুক্তির মাধ্যমে নাদির খানের (তখনও শাহ উপাধি না নেওয়া) নেতৃত্বাধীন ইরানকে ফেরত দিল। TDV ইসলাম বিশ্বকোষের দেরবেন্দ ভুক্তি অনুযায়ী এই পশ্চাদপসরণ দক্ষিণে একই সঙ্গে দুই ফ্রন্টে (অটোমান ও ইরান) লড়তে না চাওয়া রাশিয়ার ফল ছিল এবং নাদিরের কয়েক বছর পর সিংহাসনারোহণের পথ খুলে দেওয়া সামরিক মর্যাদা সুসংহত করলো। রুশ শাসনাধীন তারকিও (তারকু) এই পশ্চাদপসরণে ইরান পক্ষে ফিরলো (মানচিত্রে গাঞ্জার দিন ব্যবহৃত হয়)। রুশ শাসনাধীন সালিয়ান ও শাবরানও এই পশ্চাদপসরণে ইরান পক্ষে ফেরে (বসতিভিত্তিক নির্দিষ্ট দিন সূত্রে নেই, মানচিত্রে গাঞ্জার দিন ব্যবহৃত হয় — ঘোষিত আনুমানিকতা)।", "711f14d9"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["নাদির শাহের মুগান সমভূমিতে সিংহাসনারোহণ: সাফাভি রাজবংশের কার্যত অবসান", "4f640979"], "d": ["TDV ইসলাম বিশ্বকোষের নাদির শাহ ভুক্তি অনুযায়ী মুগান সমভূমিতে জড়ো হওয়া প্রায় বিশ হাজার লোকের কুরুলতাই জোর দিয়ে চাইলো তিনি ইরানের প্রধান হোন; নাদির সাফাভি ও অটোমানদের মধ্যকার যুদ্ধের কারণ হওয়া চরমপন্থী শিয়া ধারণা ত্যাগ করে মধ্যপন্থী জাফরি মাজহাব গ্রহণের শর্তে এই প্রস্তাব মেনে 24 শাওয়াল 1148 (8 মার্চ 1736) তারিখে নাদির শাহ উপাধিতে সিংহাসনে বসলেন। এর অর্থ ছিল দুই শতাব্দীর সাফাভি রাজবংশের কার্যত অবসান এবং আফশারি রাজবংশের প্রতিষ্ঠা।", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["ইস্তানবুলে প্লেগ মহামারির শুরু", "9fa82b56"], "d": ["TDV-এর 'Tâun' ভুক্তি অনুযায়ী ইসলামি ভূগোলে 1739-1743 সালের মধ্যে প্রভাব ফেলা প্লেগ মহামারি এই সময়ে ইস্তানবুলকেও আঘাত করলো। ভুক্তি জানায় যে অষ্টাদশ শতকের মহামারিগুলো আগের শতাব্দীগুলোর তুলনায় অপেক্ষাকৃত হালকা ছিল। মহামারির সময়গুলোর মধ্যে 1713, 1719, 1728-1729 এবং 1759-1765 সালও গণ্য হয়।", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["হোজাপাশা অগ্নিকাণ্ড", "321c7d0d"], "d": ["TDV-এর 'Fatma Sultan Camii' ভুক্তি অনুযায়ী রাতে শুরু হওয়া হোজাপাশা অগ্নিকাণ্ড বাব-ই আলি ও আশেপাশের এলাকা বিধ্বস্ত করলো; এলাকার ফাতমা সুলতান মসজিদও এই অগ্নিকাণ্ডে ক্ষতিগ্রস্ত হয়েছিল বলে অনুমান করা হয়। তৃতীয় ওসমানের সময় ইস্তানবুলে আঘাত হানা বড় অগ্নিকাণ্ডগুলোর একটি এই বিপর্যয় শহরের বাণিজ্য ও প্রশাসনিক কেন্দ্রে ভারী ক্ষতি করলো।", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["কোজা রাগিপ মেহমেদ পাশার প্রধান উজিরত্ব", "a1846910"], "d": ["কবি ও কূটনীতিক পরিচয়ে খ্যাত রাগিপ পাশা তৃতীয় ওসমান কর্তৃক প্রধান উজির পদে নিযুক্ত হলেন (1757 সালের অক্টোবরে তৃতীয় ওসমানের মৃত্যুতে দায়িত্ব চালিয়ে গেলেন, তৃতীয় মুস্তাফার কাছ থেকে নতুন সিলমোহর নিলেন)। সপ্তবর্ষীয় যুদ্ধ চলাকালে অটোমান রাষ্ট্রকে ইউরোপের সংঘাতের বাইরে রাখা ভারসাম্যপূর্ণ পররাষ্ট্রনীতি অনুসরণ করলেন। ছয় বছর স্থায়ী প্রধান উজিরত্বকালে গ্রন্থাগার স্থাপনের মতো সাংস্কৃতিক কর্মকাণ্ডকেও গুরুত্ব দিলেন।", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["রাগিপ পাশার ইন্তেকাল", "6bc19323"], "d": ["রাগিপ পাশা ছয় বছরের প্রধান উজিরত্বের পর ইন্তেকাল করলেন। তাঁর মৃত্যুতে তৃতীয় মুস্তাফার সময়ের সবচেয়ে দীর্ঘস্থায়ী ও ভারসাম্যপূর্ণ প্রধান উজিরত্ব শেষ হলো।", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["ইস্তানবুলের বড় ভূমিকম্প ও ফাতিহ মসজিদের ধসে পড়া", "2475b4dc"], "d": ["TDV-এর 'Fâtih Camii ve Külliyesi' ভুক্তি অনুযায়ী 1766 সালের বড় ভূমিকম্পে মসজিদের প্রধান গম্বুজ সম্পূর্ণ ধসে পড়লো, দেয়ালগুলো মেরামতের অযোগ্য মাত্রায় ক্ষতিগ্রস্ত হলো। তৃতীয় মুস্তাফার আদেশে স্থপতি সারিম ইব্রাহিম এফেন্দি ও ইজ্জেত মেহমেদ বের নেতৃত্বে 1767 সালে শুরু হওয়া পুনর্নির্মাণ পুরনো নকশা থেকে ভিন্ন নতুন নকশায় 1771 সালে সমাপ্ত হলো।", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["ব্যারন দ্য টটের নেতৃত্বে স্বল্পস্থায়ী গোলন্দাজ বিদ্যালয় পরীক্ষা", "4192260c"], "d": ["TDV-এর 'Mühendishâne-i Bahrî-i Hümâyun' ভুক্তি অনুযায়ী 1768 অটোমান-রুশ যুদ্ধের ব্যর্থতা প্রযুক্তিগত সামরিক শিক্ষার প্রয়োজন সামনে এনে দিল; ফরাসি কর্মকর্তা ব্যারন দ্য টটের অবদানে খোলা স্বল্পস্থায়ী গোলন্দাজ বিদ্যালয় 1772 সালের অক্টোবরে কার্যক্রম শুরু করলেও ফলহীন থাকলো। এই পরীক্ষা 1775 সালে প্রতিষ্ঠিত হতে যাওয়া মুহেন্দিসহানে-ই বাহরি-ই হুমায়ুনের অগ্রদূত গণ্য হয়।", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["তৃতীয় সেলিমের সিংহাসনারোহণ", "00d046d9"], "d": ["প্রথম আবদুলহামিদের মৃত্যুতে ভাতিজা তৃতীয় সেলিম সিংহাসনে বসলেন। TDV ইসলাম বিশ্বকোষের সেলিম III ভুক্তি অনুযায়ী শাহজাদা থাকাকালীন থেকে ইউরোপীয় সেনাবাহিনীর সংস্কারে আগ্রহী নতুন সুলতান সিংহাসনারোহণের অল্প পরেই মৌলিক নবায়ন কর্মসূচি তৈরি করাতে শুরু করলেন। এই কর্মসূচি কয়েক বছরের মধ্যে নিজাম-ই জেদিদ নামে পরিচিত হবে।", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["নিজাম-ই জেদিদ সংস্কার কর্মসূচি প্রস্তুত করা শুরু", "eff78a68"], "d": ["তৃতীয় সেলিম রাষ্ট্রের উচ্চপদস্থ ও বিদেশি বিশেষজ্ঞদের কাছ থেকে চাওয়া প্রস্তাব অনুযায়ী ব্যাপক নবায়ন কর্মসূচি প্রস্তুত করালেন। TDV ইসলাম বিশ্বকোষের নিজাম-ই জেদিদ ভুক্তি অনুযায়ী এই কর্মসূচি কেবল নতুন সেনাবাহিনী গঠনে সীমাবদ্ধ থাকেনি; অর্থ, প্রাদেশিক প্রশাসন ও কূটনীতিও ধারণকারী ব্যাপক সংস্কার আন্দোলনে রূপ নিল। কর্মসূচি পরবর্তী পনেরো বছর সমর্থক ও বিরোধী দুইই পাবে।", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["ইউরোপীয় রাজধানীগুলোতে স্থায়ী দূতাবাস স্থাপিত", "2e9dc8a1"], "d": ["তৃতীয় সেলিম অটোমান রাষ্ট্রের ইতিহাসে প্রথমবার বড় ইউরোপীয় কেন্দ্রগুলোতে স্থায়ীভাবে দায়িত্ব পালনকারী স্থায়ী দূত পাঠালেন। TDV ইসলাম বিশ্বকোষের Elçi ভুক্তি অনুযায়ী এই পদক্ষেপ সে পর্যন্ত কেবল অস্থায়ী ও এককালীন প্রতিনিধিদল দিয়ে চলা অটোমান কূটনীতিকে স্থায়ী সংগঠন দিল। নতুন দূতাবাসগুলোর প্রধান কাজ ছিল ইউরোপের রাজনৈতিক ও সামরিক ঘটনাপ্রবাহ নিয়মিত ইস্তানবুলে জানানো।", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["ইরাদ-ই জেদিদ কোষাগার স্থাপিত", "ae5c8ce2"], "d": ["নিজাম-ই জেদিদ সেনাবাহিনী ও সংস্কার কর্মসূচির ব্যয় মেটাতে আলাদা কোষাগার স্থাপিত হলো। TDV ইসলাম বিশ্বকোষের Esham ভুক্তি অনুযায়ী নতুন কোষাগারের আয়ের মধ্যে কিছু মুকাতার সরাসরি রাষ্ট্রের হাতে পরিচালনা এবং এশাম বিক্রি নিয়ন্ত্রণের আওতায় আনা অন্তর্ভুক্ত ছিল। এই ব্যবস্থা ঐতিহ্যবাহী অর্থ ব্যবস্থার বাইরে নতুন উৎস সৃষ্টির প্রচেষ্টা ছিল।", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["কাবাকচি মুস্তাফা বিদ্রোহের শুরু", "b98eee17"], "d": ["নিজাম-ই জেদিদের বিরুদ্ধে জমে ওঠা অসন্তোষ ইয়ামাক সৈন্যদের কাবাকচি মুস্তাফার নেতৃত্বে বিদ্রোহে ফেটে পড়লো। TDV ইসলাম বিশ্বকোষের কাবাকচি বিদ্রোহ ভুক্তি অনুযায়ী বিদ্রোহীরা অল্প সময়ে ইস্তানবুলের নিয়ন্ত্রণ নিল এবং নিজাম-ই জেদিদপন্থী রাষ্ট্রনায়কদের মাথা দাবি করলো। বিদ্রোহ কয়েক দিনের মধ্যে তৃতীয় সেলিমের সিংহাসনচ্যুতিতে পরিণত হলো।", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["তৃতীয় সেলিম সিংহাসনচ্যুত", "ff2c30ec"], "d": ["কাবাকচি মুস্তাফা বিদ্রোহের চাপে শায়খুল ইসলামের কাছ থেকে নেওয়া ফতোয়ার মাধ্যমে তৃতীয় সেলিম সিংহাসনচ্যুত হলেন। TDV ইসলাম বিশ্বকোষের সেলিম III ভুক্তি অনুযায়ী এই সিদ্ধান্ত আঠারো বছর স্থায়ী সংস্কার যুগের কার্যত শেষ হওয়ার মুহূর্ত ছিল; নিজাম-ই জেদিদ সেনাবাহিনীও অল্প সময়ে বিলুপ্ত হলো। সেলিমকে তোপকাপি প্রাসাদে আটক রাখা শুরু হলো।", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["চতুর্থ মুস্তাফা সিংহাসনে বসলেন", "8f1ac86c"], "d": ["তৃতীয় সেলিমের সিংহাসনচ্যুতির সঙ্গে সঙ্গেই ভাতিজা চতুর্থ মুস্তাফা সুলতান ঘোষিত হলেন। TDV ইসলাম বিশ্বকোষের মুস্তাফা IV ভুক্তি অনুযায়ী নতুন সুলতান বিদ্রোহকে সমর্থনকারী নিজাম-ই জেদিদ-বিরোধী মহলের প্রভাবে সালতানাত শুরু করলেন। এই স্বল্পস্থায়ী সময় কেন্দ্রীয় কর্তৃত্ব আরও দুর্বল হওয়া অস্থিরতার পর্ব হলো।", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["আলেমদার মুস্তাফা পাশা সেনাবাহিনী নিয়ে ইস্তানবুলে প্রবেশ করলেন", "0cad3dea"], "d": ["রুসচুকের আয়ান আলেমদার মুস্তাফা পাশা তৃতীয় সেলিমকে আবার সিংহাসনে বসানোর উদ্দেশ্যে সেনাবাহিনী নিয়ে ইস্তানবুলের সামনে এলেন। TDV ইসলাম বিশ্বকোষের আলেমদার মুস্তাফা পাশা ভুক্তি অনুযায়ী শহরে প্রবেশে স্বয়ং চতুর্থ মুস্তাফা তাঁকে অভ্যর্থনা জানালেন; তবে কয়েক দিনের মধ্যে প্রাসাদের ভেতরের ক্ষমতার ভারসাম্য সম্পূর্ণ বদলে যাবে। এই প্রবেশ সেলিমের মৃত্যু ও নতুন সিংহাসনারোহণে শেষ হওয়া ঘটনাশৃঙ্খলা শুরু করলো।", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["তৃতীয় সেলিম নিহত", "e452f5f6"], "d": ["আলেমদার মুস্তাফা পাশা যেদিন বাব-ই আলি দখল করলেন, সেদিন চতুর্থ মুস্তাফার আদেশে তৃতীয় সেলিম প্রাসাদে নিহত হলেন। TDV ইসলাম বিশ্বকোষের সেলিম III ভুক্তি অনুযায়ী এটি সিংহাসনচ্যুত এক সুলতানকে আবার সিংহাসনে বসানোর প্রচেষ্টা আটকানোর উদ্দেশ্যে নেওয়া সিদ্ধান্ত ছিল। সেলিমের মৃত্যু একই দিনে মাহমুদের সিংহাসনারোহণে পরিণত হলো।", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["দ্বিতীয় মাহমুদ সিংহাসনে বসলেন", "661c1974"], "d": ["তৃতীয় সেলিমের নিহত হওয়ার পর রাজবংশের একমাত্র পুরুষ সদস্য থাকা মাহমুদ আলেমদার মুস্তাফা পাশার সমর্থনে সিংহাসনে বসলেন। TDV ইসলাম বিশ্বকোষের মাহমুদ II ভুক্তি অনুযায়ী নতুন সুলতান সালতানাতের প্রথম মাসগুলো নিজেকে সিংহাসনে বসানো আলেমদারের তত্ত্বাবধানে এবং আয়ান ও কেন্দ্রের মধ্যকার ভারসাম্য পুনঃপ্রতিষ্ঠার চেষ্টায় কাটালেন। এই সময় পরবর্তী বিশ বছরের মৌলিক সংস্কার প্রক্রিয়ার সূচনা হলো।", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["সেকবান-ই জেদিদ সেনাবাহিনী গঠিত", "6f9eb5e4"], "d": ["আলেমদার মুস্তাফা পাশা বিলুপ্ত নিজাম-ই জেদিদের জায়গায় ইউরোপীয় ধাঁচে সজ্জিত নতুন সেনাবাহিনী গঠন করালেন। TDV ইসলাম বিশ্বকোষের সেকবান-ই জেদিদ ভুক্তি অনুযায়ী তিন রেজিমেন্ট নিয়ে গঠিত এই বাহিনী জানিসারিদের চোখে সরাসরি হুমকি বলে গণ্য হলো এবং প্রতিষ্ঠার মাত্র কয়েক মাস পর এক জানিসারি বিদ্রোহে নির্মূল হলো।", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["ইবরাইলের পতন — দানিউব রেখায় প্রথম বড় ফাটল", "ee519321"], "d": ["1806 সালে শুরু হওয়া রুশ যুদ্ধে দানিউবের উত্তর তীরের ইবরাইল দুর্গ কাউন্ট কামিনস্কির নেতৃত্বাধীন রুশ বাহিনীর অবরোধ ও গোলাবর্ষণের শিকার হলো। ভেতরে 4100 পদাতিক, 1100 অশ্বারোহী ও 260 কামান ছিল; দুর্গ খাদ্যসংকটের কারণে জেনারেল এসেনের কাছে আত্মসমর্পণ করলো। দানিউব প্রতিরক্ষা রেখার উত্তর প্রান্ত এভাবে খুলে গেল।", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["রুসচুকের আত্মসমর্পণ — দানিউবের দক্ষিণ তীরও হাতছাড়া", "084062e8"], "d": ["রুসচুক কাউন্ট কামিনস্কির নেতৃত্বাধীন রুশ সেনাবাহিনীর দীর্ঘ ও রক্তাক্ত অবরোধ প্রতিরোধ করলো; গ্যারিসন ও বেসামরিক জনগণ নিরাপদে শহর ত্যাগের শর্তে আত্মসমর্পণ করলো। দানিউবের দক্ষিণ তীরের সবচেয়ে শক্তিশালী দুর্গনগরের পতন যুদ্ধের গতি রাশিয়ার পক্ষে ঘুরিয়ে দিল।", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["এশকিনজি ওজাক গঠিত", "67c56759"], "d": ["দ্বিতীয় মাহমুদ জানিসারি ওজাকের ভেতর থেকে বাছাই করা সৈন্যদের নিয়ে ইউরোপীয় ধাঁচে প্রশিক্ষণ নেবে এমন এক নতুন ইউনিট গঠন করালেন। TDV ইসলাম বিশ্বকোষের এশকিনজি ওজাক ভুক্তি অনুযায়ী ইউনিট 12 জুন 1826 তারিখে প্রশিক্ষণ শুরু করলো, কিন্তু জানিসারিরা এটিকে নিজেদের ওজাকের শেষ বলে দেখলো। তিন দিন পর ফেটে পড়া বিদ্রোহ এশকিনজি ওজাকেরও স্বল্প আয়ু শেষ করলো।", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["আসাকির-ই মানসুরে-ই মুহাম্মদিয়ে গঠিত", "14b84a7e"], "d": ["জানিসারি ওজাক বিলুপ্তির সঙ্গে সঙ্গেই দ্বিতীয় মাহমুদ তার জায়গায় নিয়মিত ও ইউরোপীয় ধাঁচে প্রশিক্ষিত নতুন সেনাবাহিনী গঠন করালেন। TDV ইসলাম বিশ্বকোষের আসাকির-ই মানসুরে-ই মুহাম্মদিয়ে ভুক্তি অনুযায়ী এই বাহিনী পদক্রম, প্রশিক্ষণ কর্মসূচি ও বেতন ব্যবস্থায় আগের প্রচেষ্টাগুলো থেকে ভিন্নভাবে স্থায়ী প্রতিষ্ঠান হয়ে উঠলো। সেনাবাহিনী পরবর্তী বছরগুলোতে তানজিমাত যুগের নিজামিয়ে সেনাবাহিনীতে রূপান্তরিত হবে।", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["বেকতাশি তরিকা বন্ধ", "f7d9a367"], "d": ["জানিসারি ওজাক বিলুপ্তির সঙ্গে একই সময়ে ওজাকের সঙ্গে ধর্মীয় বন্ধনের জন্য পরিচিত বেকতাশি তরিকাও নিষিদ্ধ হলো। TDV ইসলাম বিশ্বকোষের বেকতাশিলিক ভুক্তি অনুযায়ী কয়েকজন ছোট তেক্কের শায়খ মৃত্যুদণ্ডপ্রাপ্ত হলেও হাজি বেকতাশ দরগার শায়খ আমাসিয়ায় নির্বাসিত হলেন এবং তেক্কেগুলো নকশবন্দি পরিচালনায় হস্তান্তরিত হলো। তরিকা এই ভারী আঘাত সত্ত্বেও সংগঠন গোপনে চালিয়ে গেল।", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["পাখার ঘটনা — দখলের অজুহাত", "e949001e"], "d": ["ফ্রান্সের আলজিয়ার্সের কাছে পুরনো শস্য ঋণ পরিশোধ না হওয়ায় উত্তেজিত আলোচনায় দে হুসেইন ফরাসি কনসাল দেভালকে হাতের পাখা দিয়ে আঘাত করলেন। পাওনা সংক্রান্ত বিরোধ থেকে সৃষ্ট এই ঘটনাকে তিন বছর পর শুরু হতে যাওয়া দখলের সরকারি অজুহাত বানানো হলো।", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["আলজেরীয় উপকূলের ফরাসি অবরোধ — তিন বছর স্থায়ী অবরোধ", "d0ba97a5"], "d": ["পাখার ঘটনার পর ফ্রান্স আলজেরীয় উপকূল অবরোধ করলো। অবরোধ তিন বছর স্থায়ী হলো; ওজাকের সামুদ্রিক বাণিজ্য ও আয়ের উৎস শুকিয়ে গেল, দখল শুরুর আগেই প্রতিরোধ শক্তি ক্ষয় হলো।", "79d27be2"]},
"OLAYLAR_EK7:1828-02-22:0":{"b": ["তুর্কমানচাই চুক্তি: ইরেভান ও তালিশ রাশিয়ার হাতে গেল", "abffcfdb"], "d": ["1826-1828 রুশ-ইরান যুদ্ধ ইরানের ভারী পরাজয়ে শেষ হলে তুর্কমানচাইয়ে স্বাক্ষরিত চুক্তির মাধ্যমে ইরেভান ও নাখচিভান খানাত এবং কাস্পিয়ান উপকূলের তালিশ অঞ্চল (লেনকোরান, আস্তারা) রাশিয়াকে ছেড়ে দেওয়া হলো; এ ছাড়া ভারী যুদ্ধক্ষতিপূরণ ধার্য হলো। TDV ইসলাম বিশ্বকোষের ইরেভান ভুক্তি অনুযায়ী এই ক্ষতি ককেশাসে রুশ-ইরান সীমান্ত আজ পর্যন্ত বহুলাংশে বৈধ থাকার মতো করে টানার মুহূর্ত এবং আর্মেনীয় জনগোষ্ঠীর ইরেভানে অভিবাসনও উসকে দিল। এই চুক্তির মাধ্যমে ইরেভান খানাত (এচমিয়াদজিন, ইগদির, নোরাপাত, বেরি) ও নাখচিভান খানাত (জুলফা, শারুর) রাশিয়ার হাতে গেল।", "847d76d5"]}
});
